import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c1-001","clusterId":"C","werkstueckRef":"C.1.1","stufe":1,"question":"Wie antwortest du ihm am treffendsten?","options":["Du stimmst zu: Eine gemeinsame Fluchtbewegung braucht einen Ausgangspunkt, nur liegt er wohl außerhalb des Bereichs, den unsere Teleskope erfassen.","Du stimmst halb zu: Den Mittelpunkt gab es, doch die Ausdehnung hat ihn inzwischen so weit fortgetragen, dass kein Raumschiff ihn je erreichen kann.","Du widersprichst: Die Galaxien entfernen sich gar nicht wirklich voneinander, die beobachtete Fluchtbewegung ist bloß eine Täuschung durch das Licht.","Du widersprichst: Der Raum selbst dehnt sich überall zugleich aus, jede Galaxie entfernt sich von jeder, und einen Ort zum Hinfliegen gibt es nicht."],"correctIndex":3,"explanation":"Der Schluss deines Freundes überträgt ein Alltagsbild auf den Kosmos: Bei einer Explosion im Raum fliegen Teile von einem Ort weg, und es gibt einen Mittelpunkt. Der Urknall war aber keine Explosion in einen bestehenden Raum hinein, sondern die Entstehung und Ausdehnung des Raumes selbst, nicht an einem Punkt, sondern überall zugleich. Dazu passt die Beobachtung: Je weiter eine Galaxie entfernt ist, desto schneller entfernt sie sich. Einen Mittelpunkt, von dem alles wegfliegt, gibt es nicht, und daher auch keinen Ort, zu dem man fliegen könnte. Gestützt wird das Modell von zwei unabhängigen Beobachtungen: der Expansion der Galaxien und der kosmischen Mikrowellen-Hintergrundstrahlung, die aus allen Richtungen des Himmels nahezu gleichmäßig messbar ist. Einen fernen oder fortgetragenen Mittelpunkt anzunehmen, klingt wie ein vorsichtiger Kompromiss, hält aber am Bild der Explosion im Raum fest, das die Lehrerin gerade ausgeschlossen hat. Die Fluchtbewegung zur Täuschung zu erklären, verwirft dagegen genau die Beobachtung, auf die sich das Modell stützt.","coreRule":"⚡ Wer aus „alles entfernt sich voneinander“ auf einen Mittelpunkt schließt, überträgt ein Alltagsbild (Explosion im Raum) auf einen Vorgang, bei dem der Raum selbst sich ausdehnt, überall zugleich.","quote":"Es war die Entstehung und Ausdehnung des Raumes selbst -- nicht an einem Punkt, sondern überall zugleich.","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.1 (Kontext & Tiefe, „Keine Explosion im Raum“)","status":"entwurf","scenario":"In der Physikstunde erklärt eure Lehrerin: Der Urknall war keine Explosion in einen bestehenden Raum hinein, sondern der Raum selbst dehnt sich aus, überall zugleich. Beobachtet wird, dass sich Galaxien voneinander entfernen, und zwar umso schneller, je weiter sie entfernt sind; dazu kommt eine Hintergrundstrahlung, die aus allen Richtungen des Himmels nahezu gleichmäßig eintrifft. Nach der Stunde sagt dein Freund: „Wenn sich alle Galaxien voneinander entfernen, muss es irgendwo einen Mittelpunkt geben, wo der Urknall stattfand. Dort müsste man hinfliegen können.“","kurz":"Der Urknall war kein Ereignis an einem Ort im Raum, sondern die Ausdehnung des Raumes selbst, überall zugleich. Das Explosionsbild aus dem Alltag legt einen Mittelpunkt nahe, passt aber nicht dazu.","prueffrage":"Aus welcher Richtung am Himmel trifft die Hintergrundstrahlung ein, und was fällt dir an der Verteilung auf?","rueckmeldung":[{"option":0,"text":"Ein Ausgangspunkt jenseits der Reichweite unserer Teleskope wirkt wie ein sicherer Ausweg. Er hält aber am Bild einer Explosion im Raum fest, und dazu passt nicht, dass die Hintergrundstrahlung aus allen Richtungen nahezu gleich ankommt."},{"option":1,"text":"Ein Mittelpunkt, der „fortgetragen“ wurde, klingt wie ein vorsichtiger Kompromiss. Er setzt aber weiter einen Ort voraus, an dem der Urknall stattfand. Es dehnte sich jedoch der Raum selbst überall zugleich aus, einen solchen Ort gab es nie."},{"option":2,"text":"Der Freund schließt tatsächlich zu schnell, aber die Beobachtung wegzuerklären, hilft nicht. Dass sich Galaxien umso schneller entfernen, je weiter sie weg sind, ist gemessen und stützt das Modell, statt ihm zu widersprechen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Scientific American (1999): „According to the big bang, space itself is expanding …“ (Antworten von J. R. Primack und T. Takahashi)","oeffentlich":true,"url":"https://www.scientificamerican.com/article/according-to-the-big-bang-1999-10-21","abruf":"2026-10-12"},{"typ":"url","kurz":"ESA: Planck and the cosmic microwave background","oeffentlich":true,"url":"https://www.esa.int/Science_Exploration/Space_Science/Planck/Planck_and_the_cosmic_microwave_background","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hubble, E. (1929): A Relation between Distance and Radial Velocity among Extra-Galactic Nebulae. PNAS 15(3), 168–173 (aus Landkarte-Fn gl-c-hubble-lemaitre)","oeffentlich":false,"doi":"10.1073/pnas.15.3.168"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7824c94ffbce5c78"}},{"id":"qx-c1-002","clusterId":"C","werkstueckRef":"C.1.1","stufe":2,"question":"Der Heiler soll nennen, über welche der vier fundamentalen Kräfte (Gravitation, Elektromagnetismus, starke und schwache Kernkraft) seine „Energie“ übertragen werden soll. Er kann keine nennen, die auf seine Beschreibung passt. Was folgt daraus für seine Behauptung?","scenario":"Bei einem Heilerabend sagt jemand, er lenke „kosmische Heilenergie“ in deine Hände.","options":["Seine „Energie“ ist mit hoher Wahrscheinlichkeit keine physikalische Größe, sondern eine bildhafte Redeweise; für eine neue Kraft müsste er außergewöhnliche Belege liefern.","Seine „Heilenergie“ ist eine fünfte, noch unentdeckte Grundkraft; dass er keine der vier bekannten nennen kann, belegt gerade, dass sie neu ist.","Seine Behauptung gilt als gestützt, wenn viele Besucher des Abends Besserung berichten; solche Berichte wiegen schwerer als die Frage nach der übertragenden Kraft.","Seine Behauptung enthält einen Zirkelschluss: Er begründet die Heilenergie mit der Besserung der Zuhörer und die Besserung mit der Heilenergie; die Kräftefrage trifft das nicht."],"correctIndex":0,"explanation":"Jede bisher beobachtete Wechselwirkung lässt sich auf die vier bekannten Grundkräfte zurückführen. Wer behauptet, eine „Energie“ zu lenken, behauptet etwas Physikalisches und muss sagen können, über welche dieser Kräfte sie übertragen werden soll; kann er das nicht, ist das Wort wahrscheinlich nur bildhaft gemeint. Eine neue, fünfte Kraft wäre denkbar, doch Präzisionsexperimente suchen gezielt danach und lassen ihr bislang nur winzige Spielräume; wer sie behauptet, muss außergewöhnliche Belege liefern.","coreRule":"⚡ Nenne die Kraft: Passt keine der vier fundamentalen Kräfte, ist „Energie“ eine Metapher und keine Physik – und wer eine neue Kraft behauptet, trägt die Beweislast.","beleg":"Werkstück C.1.1 (Anwendung & Relevanz, „Gegen die Esoterik & ‚Energieheilung‘“, mit Verweis auf D.4.1; Kontext & Tiefe, Absatz zur ‚fünften Kraft‘); Fn. gl-c-dunkle-energie (Adelberger u. a. 2003, Suche nach einer fünften Kraft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer „Energie“ lenkt, behauptet etwas Physikalisches und sollte sagen können, über welche Kraft sie wirkt. Kann er das nicht, ist das Wort wahrscheinlich nur ein Bild. Eine neue Kraft wäre denkbar, bräuchte aber außergewöhnliche Belege.","prueffrage":"Was würde sich an Messgeräten ändern, wenn tatsächlich etwas in deine Hände fließt?","rueckmeldung":[{"option":1,"text":"Eine fünfte Kraft ist denkbar, nur folgt sie nicht aus einer Lücke: Dass der Heiler nichts Passendes nennen kann, belegt keine neue Kraft. Sie bräuchte außergewöhnliche Belege, nach ihr wird bereits gezielt gesucht."},{"option":2,"text":"Berichte von Besserung sind echte Beobachtungen und wirken stark. Sie sagen aber nichts darüber, auf welchem Weg eine „Energie“ übertragen wird; Besserung kann viele andere Ursachen haben. Die Frage nach der Kraft bleibt unbeantwortet."},{"option":3,"text":"Zirkelschlüsse sind in solchen Kreisen tatsächlich verbreitet. Hier begründet der Heiler seine Energie aber nicht mit ihrer Wirkung, es fehlt also ein Kreis. Die Kräftefrage trifft einen anderen Punkt: ob „Energie“ wörtlich gemeint sein kann."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CERN: The Standard Model","oeffentlich":true,"url":"https://home.cern/science/physics/standard-model","abruf":"2026-10-12"},{"typ":"url","kurz":"Adelberger, E. G.; Heckel, B. R.; Nelson, A. E. (2003): Tests of the Gravitational Inverse-Square Law. Ann. Rev. Nucl. Part. Sci. 53, 77–121 (arXiv-Fassung)","oeffentlich":true,"url":"https://arxiv.org/abs/hep-ph/0307284","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"42a40df1c2c5ddcc"}},{"id":"qx-c1-003","clusterId":"C","werkstueckRef":"C.1.1","stufe":3,"question":"Welche der folgenden Äußerungen ist ein Fehlschluss, der aus einer offenen Frage einen Beleg gegen ein gut gestütztes Modell machen will?","options":["„Die Physik kann nicht sagen, was vor dem Urknall war. Also ist die ganze Theorie widerlegt, und eine übernatürliche Erklärung muss an ihre Stelle treten.“","„Ob hinter dem Anfang des Universums ein Sinn oder ein erster Beweger steht, ist eine Frage für Philosophie und Religion und lässt sich nicht im Experiment prüfen.“","„Was vor dem Urknall war, ist offen. In extremen Zuständen wie einer Singularität könnten Regeln gelten, die ganz anders sind als in unserem Alltag.“","„Die Natur der Dunklen Energie ist noch nicht verstanden. Ihr Zahlenwert ist aber präzise vermessen, und die Forschung arbeitet weiter daran.“"],"correctIndex":0,"explanation":"Der Satz schließt von einer offenen Frage auf die Falschheit des gesamten Modells. Das ist ein Argument aus Unwissenheit: „Das weiß man nicht, also ist das übrige Wissen hinfällig und meine Erklärung gewinnt.“ Dieser Schluss trägt nicht. Ein Modell wird durch seine Belege getragen, bei der Urknall-Theorie vor allem durch die beobachtete Expansion der Galaxien und die kosmische Hintergrundstrahlung. Eine ungeklärte Frage am Rand ändert an diesen Belegen nichts. Zudem wäre die Ersatzerklärung dadurch nicht gestützt, denn sie müsste selbst Belege liefern. Die anderen Sätze sind unproblematisch. Philosophische oder religiöse Fragen nach einem Sinn oder ersten Beweger sind legitim, solange sie nicht als wissenschaftliche Argumente getarnt werden, um belegte Modelle zu leugnen. Auch ehrlich benannte Lücken sind kein Fehler, solange sie als Lücken behandelt werden und nicht als Freibrief.","coreRule":"⚡ Eine offene Frage am Rand eines Modells ist kein Beleg gegen das Modell. Wer das Modell kippen will, muss zeigen, dass es die gut belegten Beobachtungen schlechter erklärt, nicht nur auf eine Lücke zeigen.","beleg":"Werkstück C.1.1 (Der Kipppunkt; Red Flags, Argument aus Unwissenheit)","status":"entwurf","scenario":"In einer Diskussion über den Ursprung des Universums fallen vier Sätze. Es geht um die Frage, wie man mit offenen Fragen eines wissenschaftlichen Modells umgehen sollte.","kurz":"Eine offene Frage am Rand widerlegt kein Modell, das auf Belegen wie der Expansion der Galaxien und der Hintergrundstrahlung ruht. Der Fehler: aus „das weiß man nicht“ wird „also stimmt meine Erklärung“, die selbst Belege bräuchte.","prueffrage":"Welche Beobachtungen stützen die Theorie, und ändert sich an ihnen etwas, nur weil eine Frage offen ist?","rueckmeldung":[{"option":1,"text":"Hier wird eine Frage nach Sinn oder erstem Beweger gestellt, die sich tatsächlich nicht im Experiment prüfen lässt. Das Modell wird dabei nicht angegriffen und nichts an seine Stelle gesetzt, deshalb liegt kein Fehlschluss vor."},{"option":2,"text":"Die Lücke wird als offen benannt, und die Vermutung über andere Regeln bleibt vorsichtig („könnten“). Weder wird das Modell widerlegt noch eine Ersatzerklärung durchgesetzt, eine ehrlich benannte Lücke ist hier kein Fehler."},{"option":3,"text":"Auch dieser Satz nennt eine Wissenslücke, hält aber zugleich fest, was gesichert ist, nämlich den präzise vermessenen Zahlenwert. Er behandelt die Lücke als Aufgabe der Forschung und nicht als Grund, das Modell zu verwerfen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024), Abschn. 2.4","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"url","kurz":"ESA: Planck and the cosmic microwave background","oeffentlich":true,"url":"https://www.esa.int/Science_Exploration/Space_Science/Planck/Planck_and_the_cosmic_microwave_background","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hubble, E. (1929): A Relation between Distance and Radial Velocity among Extra-Galactic Nebulae. PNAS 15(3), 168–173","oeffentlich":false,"doi":"10.1073/pnas.15.3.168"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4864c6c94a3c7065"}},{"id":"qx-c1-004","clusterId":"C","werkstueckRef":"C.1.1","stufe":4,"question":"Welche Antwort deckt den Denkfehler in dieser Rechtfertigung am genauesten auf?","scenario":"Ein Esoteriker kontert: „Selbst die Physik gibt zu, dass sie Dunkle Energie nicht versteht – dann darf ich auch meine unsichtbare Lebensenergie annehmen.“","options":["Er verallgemeinert voreilig: Weil die Physik die Dunkle Energie nicht versteht, hält er alle ihre Aussagen für unsicher, obwohl ihre übrigen Ergebnisse davon unberührt bleiben.","Er beruft sich auf die Mehrheit: Weil viele Menschen an eine unsichtbare Lebensenergie glauben, gilt sie als gesichert, und die Frage nach ihrer Messbarkeit tritt dahinter zurück.","Er setzt Ungleiches gleich: Die Lücke bei der Dunklen Energie ist gemessen und eindeutig umrissen, eine bloß behauptete Lebensenergie hat nichts Vergleichbares.","Er argumentiert im Kreis: Er begründet die Lebensenergie mit der Dunklen Energie und die Dunkle Energie mit der Lebensenergie, sodass keine von beiden etwas stützt."],"correctIndex":2,"explanation":"Der Schluss „Die Physik versteht etwas nicht, also darf ich irgendetwas Unsichtbares annehmen“ macht aus einer Wissenslücke einen Freibrief. Die Dunkle Energie ist aber nicht aus der Luft gegriffen: Supernova-Messungen zeigen eine beschleunigte Ausdehnung des Universums (Riess u. a. 1998; Perlmutter u. a. 1999), und ihr Anteil am Universum ist vermessen, nach den Planck-Daten von 2018 rund 68 %. Ihre Natur ist keineswegs verstanden, die Lücke selbst aber genau umrissen und überprüfbar; einer „Lebensenergie“ ohne Messgröße und ohne beobachtbaren Effekt fehlt genau das. Die Beweislast liegt bei dem, der eine Behauptung aufstellt, nicht bei den Kritikern.","coreRule":"⚡ Eine Lücke im Wissen, die genau vermessen ist, trägt eine Hypothese; eine Lücke, die nur als Platz für eine Behauptung dient, trägt nichts.","beleg":"Werkstück C.1.1 (Kontext & Tiefe); Fn. gl-c-dunkle-energie (Riess u. a. 1998; Perlmutter u. a. 1999; Planck Collaboration 2020, A&A 641, A6)","status":"entwurf","kurz":"Eine Wissenslücke ist kein Freibrief: Die Lücke bei der Dunklen Energie ist gemessen und genau umrissen, einer bloß behaupteten Lebensenergie fehlt jede Messgröße. Wer „unverstanden“ mit „beliebig annehmbar“ gleichsetzt, setzt Ungleiches gleich.","prueffrage":"Was genau gibt die Physik zu, wenn sie sagt, sie verstehe die Dunkle Energie nicht?","rueckmeldung":[{"option":0,"text":"Dass die Lücke bei der Dunklen Energie den Rest der Physik nicht erschüttert, stimmt. Der Esoteriker zweifelt aber gar nicht an der ganzen Physik. Er nimmt eine einzelne offene Frage als Vorbild für seine eigene Annahme, und dort liegt der Fehler."},{"option":1,"text":"Die Berufung auf die Mehrheit ist ein bekannter Fehlschluss und beliebt. Im Satz des Esoterikers kommt sie aber nicht vor: Er verweist weder auf viele Gläubige noch auf Zahlen, sondern auf eine Lücke der Physik."},{"option":3,"text":"Zwei Behauptungen stehen im Satz zwar nebeneinander, doch eine stützt die andere nicht. Die Dunkle Energie ruht auf eigenen Messungen, nicht auf der Lebensenergie. Ein Kreis entsteht deshalb nicht; der Esoteriker benutzt sie nur als Vergleich."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Riess, A. G. u. a. (1998): Observational Evidence from Supernovae for an Accelerating Universe and a Cosmological Constant. AJ 116, 1009–1038","oeffentlich":true,"doi":"10.1086/300499","url":"https://arxiv.org/abs/astro-ph/9805201","abruf":"2026-10-12"},{"typ":"url","kurz":"Planck Collaboration (2020): Planck 2018 results. VI. Cosmological parameters. A&A 641, A6 (arXiv-Fassung)","oeffentlich":true,"url":"https://arxiv.org/abs/1807.06209","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8aaff840cb473eec"}},{"id":"qx-c1-005","clusterId":"C","werkstueckRef":"C.1.2","stufe":1,"question":"Was ist an dem Schluss deiner Freundin fehlerhaft?","options":["Sie betrachtet nur das Zimmer. Muskelarbeit und Staubsauger setzen Wärme frei, sodass anderswo mehr Unordnung entsteht, als im Zimmer verschwindet.","Sie verwechselt Zeitfolge mit Ursache. Dass es nach der Stunde ordentlicher ist, beweist nicht, dass ihr Aufräumen die Ordnung im Zimmer bewirkt hat.","Sie argumentiert im Kreis. Sie setzt voraus, dass Aufräumen die Unordnung im Universum senkt, und folgert daraus am Ende genau dasselbe wieder.","Sie vergisst die Zeit. In einer Woche ist das Zimmer von selbst wieder unordentlich, sodass die Unordnung im Universum dann wieder auf dem alten Stand wäre."],"correctIndex":0,"explanation":"Entropie misst, auf wie viele Arten ein System im Kleinen angeordnet sein kann; in einem abgeschlossenen System, das mit seiner Umgebung weder Energie noch Stoff austauscht, nimmt sie insgesamt nie ab. Lokale Ordnung entsteht nur unter Energieeinsatz, und dabei entsteht anderswo mehr Unordnung, etwa als Wärme aus Muskeln und Staubsauger. Gemessen daran zählt die Anordnung von Kleidung und Büchern thermodynamisch sogar verschwindend wenig; die Alltagsordnung dient hier nur als Bild. Der Schluss „Ordnung im Zimmer heißt weniger Unordnung insgesamt“ ist deshalb falsch. Die anderen Gedanken klingen vernünftig, treffen aber nicht den Kern: Zeitfolge und Ursache sind nicht verwechselt, denn das Aufräumen hat die Ordnung im Zimmer tatsächlich bewirkt. Dass ein Zimmer von selbst wieder unordentlich wird, ist richtig, bringt die Unordnung im Universum aber nicht auf den alten Stand zurück, denn die Wärme der Stunde ist nicht verschwunden. Auch ein Zirkelschluss liegt nicht vor, denn ihre Folgerung geht von einer beobachteten Ordnung im Zimmer aus und nicht von ihrem Ergebnis.","coreRule":"⚡ Lokale Ordnung gibt es nur auf Kosten von mehr Unordnung anderswo: Rechne immer die ganze Bilanz, nicht nur das Zimmer.","quote":"","quoteLabel":"","beleg":"Werkstück C.1.2 (Das aufgeräumte Zimmer; Kontext & Tiefe, Erster und Zweiter Hauptsatz)","status":"entwurf","scenario":"Du räumst eine Stunde lang dein Zimmer auf: Kleidung gefaltet, Bücher sortiert, Boden gesaugt. Deine Freundin sagt: „Ich habe Ordnung geschaffen, also hat die Unordnung im Universum abgenommen.“","kurz":"Wer ein Zimmer aufräumt, ordnet nur einen kleinen Teil der Welt und setzt dabei Wärme frei; insgesamt nimmt die Unordnung nicht ab. Der Fehler ist der Sprung von der Ordnung im Zimmer auf das ganze Universum.","prueffrage":"Was verbraucht der Staubsauger, und was gibt dein Körper während der Stunde Arbeit an die Luft ab?","rueckmeldung":[{"option":1,"text":"Nach Post-hoc-Fehlern wird oft gefragt, deshalb liegt der Verdacht nahe. Hier stimmt die Ursache aber: Das Aufräumen hat die Ordnung im Zimmer wirklich bewirkt. Der Fehler liegt erst im Schluss auf das ganze Universum."},{"option":2,"text":"Ordnung und Unordnung sind verwandte Begriffe, daher wirkt der Satz wie eine bloße Wiederholung. Die Freundin geht aber von der beobachteten Ordnung im Zimmer aus und schließt auf das Universum. Das ist ein Sprung vom Teil aufs Ganze, kein Kreis."},{"option":3,"text":"Dass ein Zimmer von selbst wieder unordentlich wird, stimmt. Die Unordnung im Universum fällt dadurch aber nicht auf den alten Stand zurück, denn die Wärme der Stunde ist nicht verschwunden. Der Fehler steckt schon im Schluss selbst."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: University Physics Vol. 2, 3.3 First Law of Thermodynamics","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/3-3-first-law-of-thermodynamics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e7d3c47872e3a4f9"}},{"id":"qx-c1-006","clusterId":"C","werkstueckRef":"C.1.2","stufe":2,"question":"Welche Antwort prüft den Einwand richtig?","scenario":"In einer Diskussion sagt jemand: „Mein Kaffee kühlt im Zimmer ab, und dabei sinkt seine Entropie. Damit ist bewiesen, dass der Satz ‚Die Gesamtentropie nimmt nie ab' nicht stimmen kann.“ Das Zimmer ist ein abgeschlossenes System aus Kaffee und Raumluft.","options":["Der Einwand ist ein Fehlschluss, denn Kaffee und Raumluft tauschen Energie mit der Außenwelt aus, und diese Zufuhr von außen gleicht den Entropieverlust des Kaffees aus.","Der Einwand ist ein Fehlschluss, denn er betrachtet nur den Kaffee; die kühlere Raumluft gewinnt mehr Entropie, als der Kaffee verliert, und die Summe beider steigt beim Abkühlen.","Der Einwand ist ein Fehlschluss, denn der Satz verlangt nur, dass die Gesamtenergie von Kaffee und Raumluft erhalten bleibt, und die bleibt beim Abkühlen unverändert.","Der Einwand ist ein Fehlschluss, denn der Satz gilt nur im Mittel; die Gesamtentropie von Kaffee und Raumluft kann beim Abkühlen auch einmal sinken, ohne den Satz zu widerlegen."],"correctIndex":1,"explanation":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für jeden Teil einzeln. Der Einwand betrachtet nur den Kaffee und übersieht die Umgebung: Die Wärme verteilt sich, bis Tasse und Raum gleich warm sind, und dabei gewinnt der kühlere Raum mehr Entropie, als der Kaffee verliert. Das lässt sich nachrechnen: Gleichen sich zwei gleiche Stahlkörper (Wärmekapazität je 1800 J/K, rund 4 kg Stahl), die nur miteinander Wärme austauschen, von 400 K und 300 K auf je 350 K an, verliert der heiße rund 240 J/K Entropie, der kalte gewinnt rund 277 J/K, netto steigt die Entropie um rund 37 J/K. Die Wärme geht dabei nicht verloren, sondern verteilt sich als ungeordnete Bewegung der Luftteilchen. Dass ein System von außen Energie aufnehmen und dadurch Entropie senken kann, trifft hier nicht zu, denn Kaffee und Raum bilden zusammen ein abgeschlossenes System. Der Satz handelt von der Entropie und nicht von der Energie, deren Erhaltung ein eigener Grundsatz ist und nichts über die Richtung des Abkühlens sagt. Und Schwankungen, die den Satz im Mittel bestehen lassen, betreffen nur sehr kleine Systeme; das Abkühlen einer Tasse ist ein gerichteter Vorgang.","coreRule":"⚡ Lokal darf die Entropie sinken – solange sie in der Umgebung mehr zunimmt. Prüfe bei „Das widerspricht dem Gesetz“ immer, ob das ganze System betrachtet wurde.","beleg":"Werkstück C.1.2; Fn. gl-c-waermefluss (Ling/Moebs/Sanny 2016, Abschn. 4.6 Beispiel 4.5 und 4.7 Beispiel 4.9)","status":"entwurf","kurz":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für den Kaffee allein. Die kühlere Raumluft gewinnt mehr Entropie, als der Kaffee verliert, die Summe steigt also. Der Einwand sieht nur eine Hälfte des Systems.","prueffrage":"Wohin geht die Wärme, die der Kaffee abgibt, und wie verändert sich dabei die Raumluft?","rueckmeldung":[{"option":0,"text":"Von außen zugeführte Energie kann in offenen Systemen tatsächlich Entropie senken. Das Szenario nennt Kaffee und Raumluft aber ausdrücklich ein abgeschlossenes System; eine Zufuhr von außen gibt es hier nicht."},{"option":2,"text":"Die Gesamtenergie bleibt beim Abkühlen tatsächlich erhalten. Der Satz handelt aber von der Entropie, und die Energieerhaltung sagt nichts darüber, in welche Richtung die Wärme fließt oder wie sich die Entropie ändert."},{"option":3,"text":"Statistische Schwankungen gibt es wirklich, doch sie spielen nur bei sehr kleinen Systemen eine Rolle. Eine abkühlende Tasse ist ein gerichteter Vorgang, und der eigentliche Fehler des Einwands, die Raumluft auszublenden, bleibt unberührt."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7, Beispiel 4.9","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"89191dd9e8d5cff1"}},{"id":"qx-c1-007","clusterId":"C","werkstueckRef":"C.1.2","stufe":3,"question":"Ein Redner sagt: „Der menschliche Körper ist hochgeordnet. Das widerlegt den Zweiten Hauptsatz der Thermodynamik und beweist eine Lebenskraft.“ Welcher Denkfehler steckt in diesem Schluss?","options":["Er stützt sich auf bloße Autorität, denn dass der Redner überzeugend auftritt, zeigt noch nicht, dass der Zweite Hauptsatz widerlegt ist oder dass es eine Lebenskraft gibt.","Er argumentiert im Kreis, denn er nimmt eine Lebenskraft als Ursache der Ordnung im Körper an und folgert aus dieser Ordnung dann wieder die Lebenskraft als Beweis.","Er verallgemeinert voreilig, denn er schließt vom Körper des Menschen auf alle Lebewesen, obwohl Pflanzen und Pilze ganz anders gebaut sind und leben.","Er betrachtet nur den Körper und nicht die Umgebung, denn Lebewesen halten ihre Ordnung durch ständige Energieaufnahme und erhöhen dabei die Entropie ihrer Umgebung."],"correctIndex":3,"explanation":"Der Zweite Hauptsatz verlangt nur, dass die Gesamtentropie eines abgeschlossenen Systems nicht abnimmt. Ein Körper ist aber kein abgeschlossenes System: Er nimmt ständig Energie von außen auf (Nahrung) und gibt Wärme und Abfallprodukte an die Umgebung ab. Dadurch steigt die Entropie der Umgebung stärker, als die Entropie im Körper sinkt, sodass die Gesamtentropie nicht abnimmt. Lokale Ordnung ist also möglich, wenn sie mit Energie und Abwärme bezahlt wird; ein Widerspruch zum Hauptsatz entsteht nicht. Die anderen Einwände wären in anderen Fällen berechtigt, passen hier aber nicht: Der Redner beruft sich auf keine Autorität, sondern auf eine Beobachtung. Er argumentiert auch nicht im Kreis, und er spricht ausdrücklich vom menschlichen Körper und nicht von allen Lebewesen.","coreRule":"⚡ Ordnung in einem Teil ist kein Gegenbeweis zum Zweiten Hauptsatz: Prüfe immer das Gesamtsystem. Leben zahlt für lokale Ordnung mit Energie und Abwärme.","beleg":"Werkstück C.1.2 (Kontext & Tiefe, Absatz „Das Leben selbst, einschließlich unseres Körpers …“)","status":"entwurf","scenario":"","kurz":"Der Körper ist kein abgeschlossenes System: Er nimmt Energie auf und gibt Wärme ab, wodurch die Entropie der Umgebung stärker steigt, als sie im Körper sinkt. Der Fehler liegt darin, nur den Körper zu betrachten; ein Widerspruch zum Zweiten Hauptsatz entsteht nicht.","prueffrage":"Was geschieht mit der Ordnung eines Körpers, der wochenlang nichts zu essen bekommt?","rueckmeldung":[{"option":0,"text":"Überzeugendes Auftreten beweist tatsächlich nichts, und gegen Autoritätsargumente zu sein ist meist richtig. Hier trifft es aber nicht zu: Der Redner beruft sich auf keine Person oder Position, sondern auf eine Beobachtung, und der Fehler liegt im Schluss daraus."},{"option":1,"text":"Ein Zirkelschluss setzt voraus, dass die Lebenskraft schon am Anfang angenommen wird. Der Redner geht aber von der Ordnung des Körpers aus und folgert daraus einen Widerspruch zum Hauptsatz. Der Schluss trägt nicht, aber nicht, weil er sich im Kreis dreht."},{"option":2,"text":"Eine voreilige Verallgemeinerung wäre es, vom Menschen auf alle Lebewesen zu schließen. Der Redner spricht aber ausdrücklich nur vom menschlichen Körper. Dass Pflanzen und Pilze anders gebaut sind, ist richtig, ändert aber nichts an der Lücke in seinem Schluss."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"e73fd72512dd9f11"}},{"id":"qx-c1-008","clusterId":"C","werkstueckRef":"C.1.2","stufe":4,"question":"Welche Überlegung prüft den Kern dieser Werbebehauptung am besten?","options":["Man fragt, was Leber und Nieren ohnehin laufend abbauen und ausscheiden; der Anbieter müsste erklären, welche zusätzliche Leistung sein Saft darüber hinaus erbringt.","Man fragt, was der Anbieter am Verkauf des Safts verdient; sein finanzielles Interesse ist ein Grund, den Werbetext über die „Schlacken“ besonders kritisch zu lesen.","Man vergleicht den Preis des Safts mit dem anderer Säfte; ist er bei ähnlichen Zutaten deutlich höher, verspricht der Anbieter wohl mehr, als er halten kann.","Man liest, was andere Käufer des Safts berichten; viele übereinstimmende Berichte über ein besseres Körpergefühl zeigen, ob die Werbung hält, was sie verspricht."],"correctIndex":0,"explanation":"Die Behauptung unterstellt, der Körper werde „Schlacken“ allein nicht los. Abbau und Ausscheidung leisten aber laufend vor allem Leber und Nieren, deshalb müsste der Anbieter erklären, was sein Saft darüber hinaus bewirkt; hinzu kommt, dass „Schlacke“ kein medizinisch definierter Stoff ist und der Werbetext offenlässt, was sich ansammeln soll. Die anderen Überlegungen sind in vielen Fällen nützlich, treffen den Kern hier aber nicht: Das finanzielle Interesse des Anbieters ist ein Grund zur Vorsicht, sagt aber nichts darüber, ob die Behauptung stimmt. Auch der Preis zeigt nicht, ob der Körper wirklich auf Hilfe beim Ausleiten angewiesen ist. Und Erfahrungsberichte spiegeln oft Erwartung und Zufall; sie ersetzen keine Erklärung, wie der Saft wirken soll.","coreRule":"⚡ Behauptungen über ein „Ausleiten“ durch Spezialprodukte prüft man am Körper als entropie-bekämpfendem System: Leber und Nieren leisten diese Arbeit bereits laufend und ohne teure Säfte.","beleg":"Werkstück C.1.2 (Anwendung & Relevanz, „In der Pseudomedizin (‚Detox‘)“)","status":"entwurf","scenario":"Im Werbetext eines Saftanbieters steht: „Dein Körper ist voller Schlacken, die er allein nie wieder loswird. Nur unser Saft leitet sie zuverlässig aus.“ Eine Freundin überlegt, ob sie den Saft bestellen soll.","kurz":"Der Körper baut und scheidet laufend über Leber und Nieren aus, und „Schlacke“ ist kein definierter Stoff. Prüfen heißt daher zu fragen, was der Saft darüber hinaus leisten soll, statt nur auf Interesse, Preis oder Berichte zu schauen.","prueffrage":"Was genau sollen diese „Schlacken“ sein, und hat sie schon jemand im Blut oder Urin nachgewiesen?","rueckmeldung":[{"option":1,"text":"Das Verkaufsinteresse ist ein guter Grund, Werbung genau zu lesen. Es zeigt aber nur, dass der Text einseitig sein kann, nicht dass die Behauptung über „Schlacken“ falsch ist; dafür müsste man sie selbst prüfen."},{"option":2,"text":"Der Preis wirkt wie ein Warnsignal, sagt aber nichts über den Kern: Ob der Körper beim Ausleiten Hilfe braucht, hängt nicht davon ab, ob der Saft teuer oder günstig ist. Auch ein billiger Saft könnte dasselbe Versprechen machen."},{"option":3,"text":"Berichte über ein besseres Körpergefühl wirken überzeugend, spiegeln aber oft Erwartung und Zufall. Sie zeigen nicht, dass irgendetwas ausgeleitet wurde, und erklären nicht, wie der Saft das leisten soll."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung?","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-ueberfluessig-oder-doch-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"73029fe3d491d585"}},{"id":"qx-c1-009","clusterId":"C","werkstueckRef":"C.1.3","stufe":1,"question":"Ein Sternenforscher erklärt: „Massereiche Sterne fusionieren Element für Element bis zum Eisen. Danach macht Fusion keinen Sinn mehr.“ Eine Studentin fragt nach: „Warum sollte genau Eisen das Ende der Kette sein?“ Welche Antwort erklärt es am besten?","options":["Ab dem Eisen wächst die elektrische Abstoßung der Kerne so stark, dass selbst die Hitze im Kern eines massereichen Sterns für weitere Fusionen nicht mehr ausreicht.","Ab dem Eisen hält der Entartungsdruck der Elektronen den Kern des massereichen Sterns stabil, sodass er sich nicht weiter verdichtet und keine höhere Brennstufe zündet.","Ab dem Eisen verbraucht Fusion mehr Energie, als sie erzeugt; der Kern des massereichen Sterns verliert seine Energiequelle und kollabiert unter der eigenen Schwerkraft.","Ab dem Eisen entweicht so viel Energie als Neutrinos aus dem Kern des massereichen Sterns, dass er sich abkühlt und die Fusion nicht mehr in Gang bleibt."],"correctIndex":2,"explanation":"Entscheidend ist die Energiebilanz: Bis zum Eisen setzt jede Fusion Energie frei und hält den Stern am Leben. Bei Eisen kehrt sich das um: Weitere Fusion würde mehr Energie kosten, als sie liefert, der Kern verliert seine Energiequelle und kollabiert unter seiner eigenen Schwerkraft, was meist in einer Supernova endet. Schwerere Elemente sind dennoch nicht unmöglich: Gold und Uran existieren, sie entstehen nur nicht durch Fusion im Sternkern, sondern in der Supernova, zum Teil in aufgeblähten Roten Riesen und nach heutigem Wissen wohl großenteils beim Zusammenstoß von Neutronensternen. Die anderen Gründe klingen nach echter Sternphysik, erklären aber nicht, warum gerade Eisen die Grenze ist: Die elektrische Abstoßung der Kerne wächst mit jeder Stufe stetig und hat bei Eisen keinen Knick. Der Entartungsdruck der Elektronen hält Sterne geringer Masse auf, versagt bei den Eisenkernen massereicher Sterne aber gerade, sodass der Kern kollabiert. Neutrinoverluste beschleunigen die späten Brennstufen, setzen aber an keiner bestimmten Stelle der Elementfolge ein Ende.","coreRule":"⚡ Bei jeder Erklärung fragen: Was ist die Energiebilanz? Bis zum Eisen liefert Fusion Energie, danach kostet sie welche, und der Stern stirbt.","beleg":"Werkstück C.1.3 (Die erste Ernte; Fn gl-c-nukleosynthese: Tyson/Gott/Strauss 2022, Schwedt 2014)","status":"entwurf","scenario":"","kurz":"Bis zum Eisen setzt jede Fusion Energie frei, danach kostet sie mehr, als sie liefert. Der Kern verliert seine Energiequelle und kollabiert. Wer auf Abstoßung, Druck oder Neutrinos verweist, nennt Nebenschauplätze ohne Knick bei Eisen.","prueffrage":"Was hält einen Stern davon ab, unter seinem eigenen Gewicht zusammenzufallen, solange er Elemente verschmilzt?","rueckmeldung":[{"option":0,"text":"Die Abstoßung der Kerne wächst tatsächlich mit jeder Stufe und erschwert die Fusion. Sie wächst aber stetig und ohne Knick bei Eisen, kann also nicht erklären, warum gerade dort Schluss ist. Hitze überwindet sie in späten Brennstufen immer wieder."},{"option":1,"text":"Entartungsdruck stabilisiert tatsächlich Sterne geringer Masse. Im Eisenkern eines massereichen Sterns reicht er aber nicht mehr aus: Der Kern kollabiert, statt stabil zu bleiben. Die Antwort beschreibt also gerade das Gegenteil des Geschehens."},{"option":3,"text":"Neutrinos tragen im späten Stern viel Energie davon und beschleunigen die letzten Brennstufen. Sie setzen aber an keiner festen Stelle der Elementfolge ein Ende und erklären darum nicht, warum gerade bei Eisen Schluss ist."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"97e3f81178c2ab11"}},{"id":"qx-c1-010","clusterId":"C","werkstueckRef":"C.1.3","stufe":2,"question":"Welche Überlegung prüft die Behauptung am besten und führt zu einem begründeten Urteil?","scenario":"In einem Artikel über Schmuck steht: „Gold ist so alt wie das Universum selbst. Es entstand beim Urknall und sammelte sich später in den Planeten.“ Du trägst einen goldenen Ehering und willst prüfen, ob die Aussage stimmt.","options":["Im frühen Universum bestand fast alles aus Wasserstoff und Helium. Schwere Elemente wie Gold brauchen extreme Prozesse in oder nach dem Tod von Sternen. Die Behauptung ist deshalb sehr unwahrscheinlich.","Der Artikel nennt weder Quelle noch Messung, und Schmuckwerbung erzählt gern schöne Herkunftsgeschichten. Über das Alter des Goldes im Ehering lässt sich deshalb erst nach einer Rückfrage beim Autor urteilen.","Gold im Ehering rostet nicht und verändert sich über Milliarden Jahre kaum. Was so lange unverändert bleibt, kann auch seit dem Urknall bestehen. Die Behauptung ist deshalb plausibel.","Im Urknall verschmolzen Wasserstoff und Helium in den ersten Minuten bei extremer Hitze auch zu schweren Elementen wie Gold, die Planeten sammelten sie später auf. Die Behauptung ist deshalb plausibel."],"correctIndex":0,"explanation":"Eine Behauptung über Herkunft lässt sich mit dem prüfen, was über die Anfangsbedingungen bekannt ist. Das frühe Universum bestand zu rund 75 % aus Wasserstoff und zu rund 25 % aus Helium, schwerere Elemente gab es praktisch nicht. Elemente jenseits des Eisens entstehen teils in der Hitze von Supernovae, teils durch langsamen Neutroneneinfang in aufgeblähten Roten Riesen. Gold und Uran entstehen nach heutigem Wissen großenteils beim Zusammenstoß zweier ausgebrannter Neutronensterne. Das Gold in deinem Ring entstand also erst, nachdem Sterne entstanden und gestorben waren, in einem Prozess wie einer Sternkatastrophe, nicht beim Urknall. Eine Behauptung ohne Quelle bleibt zwar ungeprüft, aber die Prüfung gegen bekanntes Wissen spricht klar dagegen.","coreRule":"⚡ Prüfe Herkunftsbehauptungen an den Anfangsbedingungen: Was es am Anfang nicht gab, musste später entstehen, und zwar durch einen Prozess, der es erzeugen kann.","beleg":"Werkstück C.1.3; Fn. gl-c-nukleosynthese (Tyson/Gott/Strauss 2022, S. 64–65; Schwedt 2014, S. 197)","status":"entwurf","kurz":"Das frühe Universum bestand fast nur aus Wasserstoff und Helium, schwere Elemente wie Gold brauchen Sternkatastrophen. Eine fehlende Quelle macht die Aussage nur ungeprüft, nicht falsch; hier genügt aber bekanntes Wissen für ein klares Urteil.","prueffrage":"Wird Gold mit der Zeit verbraucht, und was verrät seine Seltenheit dann über sein Alter?","rueckmeldung":[{"option":1,"text":"Dass eine Quelle fehlt und Schmuckwerbung gern erzählt, ist ein berechtigter Grund zur Vorsicht. Das Urteil hängt aber nicht an einer Rückfrage: Die Behauptung lässt sich schon mit bekanntem Wissen über das frühe Universum prüfen."},{"option":2,"text":"Gold ist tatsächlich sehr beständig und rostet nicht. Das sagt aber nur etwas über seine Haltbarkeit, nicht über seine Entstehung: Auch Beständiges muss irgendwann einmal entstanden sein, und zwar später als der Urknall."},{"option":3,"text":"Im Urknall liefen tatsächlich Kernfusionen ab, nur reichten sie nicht weit. Das junge Universum kühlte binnen Minuten ab, sodass nur die leichtesten Kerne entstanden und Gold erst viel später in Sternen und ihren Katastrophen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis. In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tyson, N. deG.; Gott, J. R.; Strauss, M. A. (2022): Das Universum für die Hosentasche, S. 64–65 (laut Landkarte-Fn gl-c-nukleosynthese)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"888f4925688f5f95"}},{"id":"qx-c1-011","clusterId":"C","werkstueckRef":"C.1.3","stufe":3,"question":"Du liest die Behauptung: „Das Eisen in deinem Blut stammt aus dem Eisenkern massereicher Sterne, den die Supernova beim Sterben ins All schleudert.“ Welche Prüffrage deckt am besten auf, ob das stimmen kann?","options":["Wird der kollabierte Eisenkern ins All geschleudert, oder bleibt er als dichter Sternrest zurück?","Stammt das Eisen im Blut überhaupt aus Sternen, oder ist es erst später auf der Erde entstanden?","Nennt der Artikel Quellen für den Satz „Wir sind aus Sternenstoff gemacht“, und wer hat ihn verfasst?","Wie viele Supernovae sind nötig, bis genug Eisen für einen Planeten wie die Erde zusammengekommen ist?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Dinge: das Eisen im Kern eines massereichen Sterns und das Eisen, das tatsächlich ins All gelangt. Wenn der Eisenkern kollabiert, bleibt er als Neutronenstern oder Schwarzes Loch zurück, statt ausgeschleudert zu werden. Die Frage nach dem Schicksal des Kerns trifft deshalb genau die Stelle, an der das Argument bricht. Das Eisen, das ins All gelangt, entsteht erst bei Explosionen: zum Teil in der Kernkollaps-Supernova selbst, in Schichten außerhalb des Kerns, zu einem großen Teil in Supernovae vom Typ Ia, bei denen ein Weißer Zwerg in einem engen Doppelsternsystem explodiert. In beiden Fällen entsteht zunächst Nickel, das über Kobalt zu Eisen zerfällt. Die anderen Fragen sind sinnvoll, entscheiden aber nicht über die Behauptung: Dass das Eisen im Blut aus Sternen stammt, ist unstrittig und sagt nichts darüber, ob es aus dem Eisenkern kommt. Die Frage nach Quellen und Autor ist nützlich, ersetzt aber nicht die Prüfung des Inhalts. Und wie viele Supernovae es braucht, ändert nichts daran, woher ihr Eisen stammt.","coreRule":"⚡ Prüfe bei einer Herkunftsbehauptung, wo das Material entsteht und auf welchem Weg es tatsächlich nach außen gelangt: Das meiste Eisen stammt aus Supernovae vom Typ Ia, der Eisenkern massereicher Sterne bleibt zurück.","beleg":"Werkstück C.1.3 (Kontext & Tiefe, Supernova); Fn. gl-c-eisen (Langer 1995, S. 96; Schneider 2007, S. 49–50); Fn. gl-c-elementherkunft (Kobayashi/Karakas/Lugaro 2020, S. 3 und S. 26)","status":"entwurf","scenario":"In einem Online-Artikel über „Sternenstaub im Körper“ steht der Satz „Wir sind aus Sternenstoff gemacht“ als selbstverständliche Tatsache. Dazu heißt es, bei Eisen sei die Fusion im Sterneninneren an ihr Ende gekommen, weil eine weitere Fusion mehr Energie verbrauchen als freisetzen würde. Danach kollabiere der Kern des Sterns unter der eigenen Schwerkraft.","kurz":"Der Eisenkern kollabiert und bleibt als Neutronenstern oder Schwarzes Loch zurück, er wird nicht ausgeschleudert. Der Fehler: Eisen im Kern wird mit Eisen verwechselt, das ins All gelangt. Das entsteht erst bei Explosionen.","prueffrage":"Was muss mit dem Eisen eines Sterns geschehen, bevor es in einem Planeten und schließlich in deinem Blut landen kann?","rueckmeldung":[{"option":1,"text":"Dass Eisen aus Sternen stammt, ist unstrittig und wird im Artikel ohnehin vorausgesetzt. Dadurch ist aber noch nicht geklärt, ob es gerade aus dem Eisenkern kommt, und genau dort liegt die schwache Stelle der Behauptung."},{"option":2,"text":"Nach Quellen und Autor zu fragen ist ein sinnvoller Reflex. Sie sagen aber nichts darüber, ob die Aussage zum Eisenkern stimmt; dafür musst du den Inhalt selbst prüfen."},{"option":3,"text":"Die Zahl der Supernovae wäre eine reine Mengenfrage. Sie ändert nichts daran, woher das Eisen dieser Explosionen stammt, und trifft die Behauptung deshalb nicht."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Langer, N. (1995): Leben und Sterben der Sterne. München: C. H. Beck (laut Landkarte-Fn gl-c-eisen S. 96)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"639b37fcec201013"}},{"id":"qx-c1-012","clusterId":"C","werkstueckRef":"C.1.3","stufe":4,"question":"Wie bewertest du die beiden Teile ihrer Begründung, die Herkunft aus Sternenstaub und den Schluss auf deinen Charakter?","options":["Den ersten Teil verwirfst du, denn „Sternenstaub“ ist bloß eine dichterische Metapher ohne Befund; den Schluss auf deinen Charakter damit ebenfalls.","Den ersten Teil lässt du gelten, denn die Atome deines Körpers außer Wasserstoff entstanden in Sternen; den Schluss auch, denn diese Herkunft verbindet dich mit ihnen.","Den ersten Teil lässt du gelten, denn die Atome deines Körpers außer Wasserstoff entstanden in Sternen; den Schluss nicht, denn Herkunft ist keine Wirkung.","Den ersten Teil lässt du gelten, denn die Atome deines Körpers außer Wasserstoff entstanden in Sternen; den Schluss auch, denn ihre Karteien zeigen Muster."],"correctIndex":2,"explanation":"Die Behauptung einer „Verbindung zu den Sternen“ wird erst prüfbar, wenn du fragst, welche Art von Verbindung gemeint ist. Die Herkunftsverbindung ist real und gut belegt: Nach dem Urknall gab es fast nur Wasserstoff und Helium, Kohlenstoff, Sauerstoff, Eisen und die übrigen schwereren Elemente wurden später durch Kernfusion in Sternen sowie in Supernovae und bei Kollisionen ausgebrannter Sternreste erzeugt. Dass dein Körper aus diesen Elementen besteht, ist ein beobachtbarer Befund und mehr als Poesie. Ein Einfluss auf deinen Charakter folgt daraus aber nicht: Die Herkunft des Materials ist etwas anderes als eine Wirkung auf dein Verhalten, und für einen solchen Einfluss gibt es keinen Beleg. „Sternenstaub“ als bloße Metapher abzutun, klingt kritisch, übersieht aber den belegten Befund auf der Tafel. Aus der stofflichen Herkunft eine fortwirkende Verbindung zum Charakter abzuleiten, vermischt Herkunft und Wirkung. Und Muster, die man findet, wenn man nur lange genug sucht, sind kein Nachweis, sondern Ausdruck der Haltung, nach Bestätigung zu suchen.","coreRule":"⚡ Prüfe, welche Art von Verbindung behauptet wird: Eine stoffliche Herkunft aus den Sternen ist belegt, ein Einfluss auf Charakter oder Zukunft folgt daraus nicht.","beleg":"Werkstück C.1.3 (Anwendung & Relevanz, „Gegen die Esoterik & Astrologie“; Kernidee)","status":"entwurf","scenario":"Im Planetarium liest du auf einer Tafel: Nach dem Urknall gab es fast nur Wasserstoff und Helium. Kohlenstoff, Sauerstoff, Eisen und die übrigen schwereren Elemente entstanden später durch Kernfusion in Sternen, in Supernovae und bei Kollisionen ausgebrannter Sternreste; die Atome deines Körpers außer Wasserstoff stammen also aus Sternen. Am Ausgang spricht dich eine Astrologin an: „Du bist aus Sternenstaub gemacht, deshalb prägen die Sterne deiner Geburtsstunde deinen Charakter. In meinen Karteien finde ich dafür immer Muster, wenn ich nur lange genug suche.“","quote":"","quoteLabel":"","kurz":"Die stoffliche Herkunft aus Sternen ist belegt, der Schluss auf deinen Charakter nicht. Woher das Material stammt, ist etwas anderes als eine Wirkung auf dein Verhalten, und für einen solchen Einfluss gibt es keinen Beleg.","prueffrage":"Was genau soll nach ihrer Aussage von den Sternen zu dir führen: nur der Ursprung des Materials oder auch etwas, das heute noch wirkt?","rueckmeldung":[{"option":0,"text":"Skepsis gegenüber dem Schluss ist berechtigt, aber „Sternenstaub“ ist hier mehr als Poesie: Die Tafel beschreibt die Herkunft der Elemente deines Körpers als beobachtbaren Befund. Verworfen werden muss nur der Schluss auf den Charakter."},{"option":1,"text":"Dass du aus Sternenmaterial bestehst, stimmt. Daraus folgt aber keine Wirkung auf dein Verhalten: Die Herkunft des Materials ist eine Aussage über die Vergangenheit, und für einen Einfluss auf den Charakter gibt es keinen Beleg."},{"option":3,"text":"Die Herkunft des Materials stimmt, die Begründung für den Schluss nicht. Wer lange genug sucht, findet fast immer Muster. Ohne Prüfung, wie viele auch ohne Zusammenhang zu erwarten wären, zeigt das nur, dass nach Bestätigung gesucht wurde."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis. In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? JCS 10(6–7), 175–198 (Archivfassung der Autoren)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"7bfda890c8073950"}},{"id":"qx-c1-013","clusterId":"C","werkstueckRef":"C.1.4","stufe":1,"question":"Mit welcher Vergleichszahl müsst ihr den nachgeschlagenen Massenfaktor vergleichen, damit euer Urteil stimmt?","options":["Mit rund 1,1 · 10¹¹: 55 Milliarden Meter durch 0,5 Meter ergibt das Abstandsverhältnis, und um diesen Faktor sinkt die Kraft.","Mit rund 1,2 · 10¹⁶: 55 Millionen Kilometer durch 0,5 Meter ergibt 1,1 · 10⁸, und dieses Abstandsverhältnis geht im Quadrat ein.","Mit rund 1,2 · 10²²: 55 Milliarden Meter durch 0,5 Meter ergibt 1,1 · 10¹¹, und dieses Abstandsverhältnis geht im Quadrat ein.","Mit rund 3 · 10²¹: 55 Milliarden Meter im Quadrat ergeben die Abschwächung, denn der halbe Meter fällt dagegen nicht ins Gewicht."],"correctIndex":2,"explanation":"Die Schwerkraft ist proportional zur Masse und zu 1/r²: Verzehnfachst du den Abstand, sinkt die Kraft auf ein Hundertstel. Entscheidend ist deshalb das Verhältnis der beiden Abstände, und zwar im Quadrat: 55 Millionen Kilometer sind 55 Milliarden Meter, geteilt durch einen halben Meter rund 1,1 · 10¹¹, im Quadrat gut 1,2 · 10²². Erst ein Massenfaktor oberhalb dieser Zahl ließe den Mars gewinnen; tatsächlich zieht die Hebamme selbst bei der größten Annäherung des Mars nicht schwächer und bei größerem Marsabstand meist um ein Vielfaches stärker. Die Annahme, Größe zähle mehr als Nähe, ist ein Denkfehler, weil der Abstand mit der zweiten Potenz einfließt; auch ohne Messung am Kind lässt sich die Kraft aus Masse und Abstand berechnen. Wer das Abstandsverhältnis nicht quadriert, unterschätzt die Abschwächung um rund elf Zehnerpotenzen. Wer Kilometer durch Meter teilt, ohne umzurechnen, verliert vor dem Quadrieren den Faktor tausend und danach eine Million. Wer nur die Marsentfernung quadriert, übersieht, dass der halbe Meter der Hebamme nicht vernachlässigbar ist: Durch 0,5² geteilt wird ihre Kraft vervierfacht, und die Vergleichszahl steigt entsprechend.","coreRule":"⚡ Kraft ~ Masse / Abstand²: Doppelter Abstand heißt ein Viertel der Kraft, zehnfacher Abstand ein Hundertstel. Nähe schlägt Größe, wenn der Abstand groß genug ist.","quote":"Wenn du die Entfernung verdoppelst, sinkt seine Kraft auf ein Viertel (1/2²).","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.4 (Kontext & Tiefe, Formel und Konsequenz)","status":"entwurf","scenario":"Eine Freundin liest ihr Horoskop und meint, bei ihrer Geburt habe der Mars stärker an ihr gezogen als die Hebamme, weil er so riesig ist. Der Mars war selbst bei seiner größten Annäherung rund 55 Millionen Kilometer entfernt, die Hebamme stand etwa einen halben Meter neben ihr. Die Schwerkraft wächst im gleichen Verhältnis wie die Masse und sinkt mit dem Quadrat der Entfernung. Ihr wollt nachschlagen, wie viel mal mehr Masse der Mars hat als die Hebamme: Ist dieser Massenfaktor größer als die Abschwächung durch die größere Entfernung, zog der Mars stärker, sonst die Hebamme.","kurz":"Entscheidend ist das Verhältnis der Abstände, und zwar im Quadrat: 55 Milliarden Meter durch 0,5 Meter ergibt 1,1 · 10¹¹, im Quadrat gut 1,2 · 10²². Große Masse wirkt eindrucksvoll, doch der Abstand fließt mit der zweiten Potenz ein und überwiegt hier bei Weitem.","prueffrage":"Um welchen Faktor ändert sich die Kraft, wenn du den Abstand zum Körper verdoppelst oder verzehnfachst?","rueckmeldung":[{"option":0,"text":"Das Abstandsverhältnis von 1,1 · 10¹¹ ist richtig gebildet, und auch die Umrechnung in Meter stimmt. Die Kraft sinkt aber nicht im gleichen Maß wie der Abstand wächst, sondern mit dessen Quadrat. Ohne Quadrieren wird die Abschwächung um rund elf Zehnerpotenzen unterschätzt."},{"option":1,"text":"Quadrieren des Abstandsverhältnisses ist der richtige Ansatz. Doch 55 Millionen Kilometer wurden ohne Umrechnung durch 0,5 Meter geteilt. Das Verhältnis ist dann um den Faktor tausend zu klein, nach dem Quadrieren fehlt eine Million."},{"option":3,"text":"Dass der Abstand quadratisch eingeht, ist richtig berücksichtigt, und auch Meter wurden sauber verwendet. Aber der halbe Meter der Hebamme steht im Vergleich im Nenner und lässt sich nicht weglassen: Ihre Kraft wächst dadurch auf das Vierfache, und die Vergleichszahl steigt entsprechend."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6126d214bc72506f"}},{"id":"qx-c1-014","clusterId":"C","werkstueckRef":"C.1.4","stufe":2,"question":"Welche Einschätzung der Behauptung hält einer Nachrechnung stand?","options":["Der Mars zieht weit stärker: Das Massenverhältnis von 9 Trilliarden übertrifft das Abstandsverhältnis von rund 110 Milliarden, das die Kraft im selben Maß schwächt, um ein Vielfaches.","Der Mars zieht weit stärker: Das Abstandsverhältnis von 55 Millionen zu 0,5 beträgt 110 Millionen, quadriert rund 12 Billiarden, und das bleibt weit unter 9 Trilliarden.","Die Hebamme zieht etwas stärker: Das Abstandsverhältnis von rund 110 Milliarden zählt quadriert, also rund 12 Trilliarden, und übertrifft so das Massenverhältnis von 9 Trilliarden.","Die Hebamme zieht ungleich stärker: Das Abstandsverhältnis von rund 110 Milliarden zählt quadriert, und dagegen spielt die Masse des Planeten bei solchen Entfernungen kaum eine Rolle."],"correctIndex":2,"explanation":"Die Anziehungskraft hängt von zwei Größen zugleich ab: Sie wächst mit der Masse und sinkt mit dem Quadrat der Entfernung; verzehnfachst du den Abstand, bleibt nur ein Hundertstel der Kraft. Hier ist der Mars rund 9 Trilliarden-mal so schwer wie die Hebamme, aber 55 Millionen Kilometer sind 55 Milliarden Meter, also rund 110 Milliarden-mal so weit wie ein halber Meter; quadriert ergibt das rund 12 Trilliarden. Die riesige Masse gleicht den Abstand also nicht aus: Eine Hebamme von etwa 70 Kilogramm zieht selbst bei der größten Annäherung des Mars noch etwas stärker als er, bei üblichem Abstand meist um ein Vielfaches stärker. Umgekehrt ziehen Mond und Sonne wegen ihrer enormen Masse trotz großer Entfernung viel stärker als die Hebamme (der Mond rund 1.800-mal, die Sonne rund 300.000-mal so stark). Wie stark ein Körper zieht, folgt allein aus Masse und Abstand, nicht aus der Bedeutung, die ihm eine Lehre zuschreibt. Wer den Abstand nicht quadriert, landet beim übermächtigen Mars, und wer Kilometer mit Metern vergleicht, macht den Abstandsfaktor tausendmal zu klein. Wer dagegen nur auf den Abstand schaut und die Masse übergeht, macht aus dem knappen Vorsprung der Hebamme einen gewaltigen.","coreRule":"⚡ Bei Fernwirkungen immer Masse und Abstand zusammen prüfen: Größe allein entscheidet nichts.","beleg":"Werkstück C.1.4 (Das Härten im Feuer, Schmiede-Übung „Die Einfluss-Hierarchie“; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Astrologin sagt dir: „Bei deiner Geburt hat der riesige Mars viel stärker an dir gezogen als die Hebamme neben dir.“ Du weißt: Die Anziehungskraft wächst im gleichen Maß wie die Masse und sinkt mit dem Quadrat des Abstands. Der Mars ist rund 9 Trilliarden-mal so schwer wie eine Hebamme von 70 Kilogramm. Bei seiner größten Annäherung ist er 55 Millionen Kilometer entfernt, die Hebamme einen halben Meter.","kurz":"Die Kraft wächst mit der Masse, sinkt aber mit dem Quadrat des Abstands. Quadriert, ergeben die 110 Milliarden-fache Entfernung rund 12 Trilliarden und übertreffen die 9 Trilliarden Masse knapp: Die Hebamme zieht etwas stärker.","prueffrage":"Um welchen Faktor ist der Mars weiter weg als die Hebamme, und was geschieht mit der Kraft, wenn du diesen Faktor einsetzt?","rueckmeldung":[{"option":0,"text":"Das Massenverhältnis stimmt, und auch die 110 Milliarden für den Abstand sind richtig gerechnet. Die Kraft sinkt aber mit dem Quadrat des Abstands, nicht im selben Maß; erst quadriert ergibt sich rund 12 Trilliarden, mehr als die Masse ausgleicht."},{"option":1,"text":"Das Quadrieren ist hier richtig angesetzt, aber der Abstand ist falsch bestimmt: 55 Millionen Kilometer sind 55 Milliarden Meter, also 110 Milliarden-mal so weit, nicht 110 Millionen. Der Faktor wird so tausendmal zu klein und der Mars scheinbar übermächtig."},{"option":3,"text":"Dass der Abstand quadriert zählt, stimmt. Die Masse zählt aber voll mit: Mond und Sonne ziehen trotz großer Entfernung viel stärker als die Hebamme. Hier reicht der Abstand nur knapp, 12 gegen 9 Trilliarden, die Hebamme zieht nur etwas stärker."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5f65a5f242a6099b"}},{"id":"qx-c1-015","clusterId":"C","werkstueckRef":"C.1.4","stufe":3,"question":"Der Astrologe räumt ein: „Die Gravitation der Planeten ist tatsächlich zu schwach, aber es wirkt eine andere, noch unbekannte Kraft.“ Wie lässt sich seine Behauptung am besten prüfen?","options":["Man prüft die behauptete Wirkung selbst, etwa ob Astrologen Geburtshoroskope Menschen besser zuordnen, als der Zufall erwarten lässt, egal welche Kraft dahintersteht.","Man bittet den Astrologen, die unbekannte Kraft zuerst zu beschreiben: Solange unklar ist, wie sie wirkt, lässt sich auch ihre Wirkung auf Geburten nicht prüfen.","Man befragt Menschen, die sich von ihrem Horoskop treffend beschrieben fühlen, und zählt, wie viele Bestätigungen zusammenkommen; viele Treffer sprächen für die Kraft.","Man wendet Ockhams Rasiermesser an: Eine unbekannte Kraft neben der schwachen Schwerkraft des Mars ist eine unnötige Annahme, und damit gilt die Behauptung als geprüft."],"correctIndex":0,"explanation":"Der Verweis auf eine unbekannte Kraft ist ein Argument aus Unwissenheit: Er lässt sich nicht widerlegen, weil sich über das Unbekannte nichts sagen lässt. Prüfbar ist aber die behauptete Wirkung selbst, ganz gleich, durch welche Kraft sie entstehen soll. Genau das wurde getestet: In mehr als vierzig kontrollierten Versuchen ordneten Astrologen Geburtshoroskope nicht besser zu, als der Zufall erwarten lässt. Und gut 2.000 Londoner, die im März 1958 nur Minuten nacheinander zur Welt kamen, glichen einander nicht stärker als beliebige andere. Außerdem liegt die Beweislast bei dem, der die Wirkung behauptet; niemand muss die Nichtexistenz einer unbekannten Kraft beweisen.","coreRule":"⚡ Wer eine Wirkung behauptet, muss sie zeigen – egal, durch welche Kraft sie angeblich entsteht.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei der Astrologie“; Belege unter F.2.1 und Band II, Sektion II.8.1)","status":"entwurf","scenario":"Du hast einem Astrologen vorgerechnet, dass der Mars bei einer Geburt nicht stärker an dem Kind zieht als die anwesende Hebamme.","kurz":"Eine unbekannte Kraft lässt sich nicht widerlegen, aber ihre behauptete Wirkung lässt sich testen, etwa ob Astrologen Horoskope besser zuordnen als der Zufall. Der naheliegende Fehler ist, am Mechanismus zu hängen, statt die Wirkung zu prüfen.","prueffrage":"Was ließe sich über eine Kraft, von der nichts bekannt ist, überhaupt berechnen oder widerlegen?","rueckmeldung":[{"option":1,"text":"Eine Beschreibung der Kraft wäre schön, wirkt gründlich und trifft einen echten Mangel. Doch eine Wirkung lässt sich auch prüfen, bevor man ihren Mechanismus kennt; das Warten darauf verzögert die Prüfung nur."},{"option":2,"text":"Viele Bestätigungen fühlen sich wie Belege an, denn Menschen erkennen sich oft in Beschreibungen wieder. Gezählt wird aber nur, wer zufrieden ist; ob die Treffer über den Zufall hinausgehen, zeigt das nicht."},{"option":3,"text":"Ockhams Rasiermesser hilft, überflüssige Annahmen niedrig zu gewichten, und die unbekannte Kraft ist eine zusätzliche Annahme. Es ist aber ein Gewichtungsprinzip und kein Test: Geprüft ist die Behauptung damit nicht."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? JCS 10(6–7), 175–198 (Archivfassung der Autoren)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e7cc22d727ecb528"}},{"id":"qx-c1-016","clusterId":"C","werkstueckRef":"C.1.4","stufe":4,"question":"Eine „Fernheilerin“ behauptet, ihre Wirkung sei aus 8.000 Kilometern Entfernung genauso stark wie am Bett. Welche Frage prüft diese Behauptung am besten?","options":["Wie viel Masse die Heilerin besitzt, denn bei großem Abstand wirken nur sehr massereiche Objekte überhaupt noch auf einen Menschen.","Wie schnell die Wirkung eintrifft, denn nur zu langsam ankommende Kräfte lassen sich mit physikalischen Gesetzen infrage stellen.","Keine, denn die Gravitation reicht unendlich weit; also darf jede andere Wirkung ebenfalls beliebig weit tragen, ohne zu schwinden.","Welche Kraft das leisten soll, denn jede Kraft aus so weiter Ferne müsste erklären, warum sie nicht mit der Entfernung abnimmt."],"correctIndex":3,"explanation":"Bekannte langreichweitige Kräfte wie Gravitation und Elektromagnetismus nehmen mit dem Quadrat der Entfernung ab: Bei zehnfachem Abstand bleibt nur ein Hundertstel, bei 8.000 Kilometern statt einem Meter ist die Wirkung nach dieser Regel um viele Größenordnungen geschwunden. Unendliche Reichweite heißt nicht gleichbleibende Stärke. Wer eine Wirkung aus großer Ferne behauptet, die am Bett genauso stark sein soll wie in 8.000 Kilometern, muss deshalb erklären, welcher Mechanismus das Abnehmen mit der Entfernung umgeht. Antwortet jemand darauf nur mit vagen, mystischen Begriffen statt mit überprüfbaren Angaben, ist das ein Warnsignal. Die Frage nach der Masse der Heilerin oder der Geschwindigkeit der Wirkung trifft den Kern nicht, und die Behauptung, Reichweite bedeute gleiche Stärke, ist schlicht falsch.","coreRule":"⚡ Wer eine Fernwirkung behauptet, muss erklären, warum sie mit der Entfernung nicht schwindet.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei anderen esoterischen Behauptungen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkung aus 8.000 Kilometern müsste erklären, warum sie nicht schwächer wird, denn bekannte Kräfte nehmen mit dem Quadrat der Entfernung ab. Der naheliegende Fehler: „unendlich weit“ mit „gleich stark“ zu verwechseln.","prueffrage":"Reicht die Schwerkraft der Erde bis zum Mond, und ist sie dort noch so stark wie an der Erdoberfläche?","rueckmeldung":[{"option":0,"text":"Bei der Gravitation zählt die Masse tatsächlich, doch auch dort schwindet die Wirkung mit dem Abstand. Die Masse der Heilerin erklärt also nicht, warum die Wirkung in 8.000 Kilometern so stark sein soll wie am Bett."},{"option":1,"text":"Die Frage nach dem Tempo wirkt messbar und damit wissenschaftlich. Physikalische Gesetze gelten aber nicht nur für langsame Kräfte: Entscheidend ist, warum die Wirkung mit der Entfernung nicht abnehmen soll, ganz gleich, wie schnell sie ankommt."},{"option":2,"text":"Gravitation reicht tatsächlich unendlich weit, aber ihre Stärke nimmt mit dem Quadrat der Entfernung ab. Unendliche Reichweite heißt nicht gleichbleibende Stärke, und daraus lässt sich keine beliebig weit tragende Wirkung ableiten."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"url","kurz":"CERN: The Standard Model","oeffentlich":true,"url":"https://home.cern/science/physics/standard-model","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"33c8ff7042a2f80b"}},{"id":"qx-c1-017","clusterId":"C","werkstueckRef":"C.1.5","stufe":1,"question":"Welche Schlussfolgerung ist mit diesen Messwerten am besten vereinbar?","scenario":"Am Rand des Grand Canyon sagt ein Besucher: „Eine so riesige Schlucht kann nur eine einzige gewaltige Flut in kurzer Zeit in den Fels geschnitten haben.“ Datierte Ablagerungen in Höhlen der Canyonwände zeigen, dass sich der Colorado River im Mittel nur um Bruchteile eines Millimeters pro Jahr eingegraben hat, also langsamer, als ein Fingernagel wächst.","options":["Der Canyon ist in kurzer Zeit entstanden, weil der Mittelwert einzelne gewaltige Fluten verdeckt, die in wenigen Tagen sehr viel Fels abtrugen.","Der Canyon ist in einigen Zehntausend Jahren entstanden, weil sich Bruchteile eines Millimeters pro Jahr zu Hunderten Metern summieren.","Der Canyon ist vor allem von Gletschern ausgeschürft worden, weil Eis schneller vertieft, als der Colorado mit Bruchteilen eines Millimeters pro Jahr es kann.","Der Canyon ist über sehr lange Zeit entstanden, weil ein meist unspektakulärer Fluss sich nur langsam, aber stetig eingegraben hat."],"correctIndex":3,"explanation":"Rate mal Zeit ergibt die Tiefe: Wer eine gemessene Einschneiderate von nur Bruchteilen eines Millimeters pro Jahr kennt, kann die Entstehung einer so gewaltigen Schlucht nicht in Wochen oder wenigen Jahrtausenden erklären. Er braucht unvorstellbar lange Zeiträume, in denen winzige Schritte sich summieren. Die genannte Größenordnung stammt aus der Datierung von Höhlenablagerungen (Polyak u. a. 2008): Der Grundwasserspiegel sank um rund 0,05 bis 0,4 mm pro Jahr. Vorbehalt: Umstritten ist unter anderem, ob sich Absenkung des Grundwasserspiegels und Einschneiden gleichsetzen lassen, nicht aber die Größenordnung der Rate. Dass man sich langsame Prozesse über riesige Zeiträume schwer vorstellen kann, ist kein Argument gegen sie.","coreRule":"⚡ Rate mal Zeit ergibt das Ergebnis: Auch winzige, stetige Veränderungen schaffen über genug Zeit riesige Formen. Prüfe immer, ob die Zeitskala der Erklärung zur gemessenen Rate passt.","beleg":"Werkstück C.1.5 (Der Fingernagel am Grand Canyon); Fn. gl-c-grandcanyon (Polyak/Hill/Asmerom 2008, Science 319, S. 1377–1380)","status":"entwurf","kurz":"Aus Tiefe geteilt durch Rate folgt: Bei so winzigen Schritten pro Jahr braucht eine Schlucht dieser Tiefe ungeheuer lange. Der Denkfehler liegt darin, den Zeitraum zu „fühlen“, statt nachzurechnen, was die gemessene Rate hergibt.","prueffrage":"Wie tief wird eine Schlucht, wenn sich ein Fluss 1.000 Jahre lang um 0,1 Millimeter pro Jahr eingräbt, und wie tief nach einer Million Jahren?","rueckmeldung":[{"option":0,"text":"Fluten tragen tatsächlich viel Fels ab, und das macht den Gedanken plausibel. Der gemessene Mittelwert enthält sie aber schon: Er sagt, wie schnell der Fluss im Schnitt einschneidet, und daraus ergibt sich, wie lange die ganze Tiefe braucht."},{"option":1,"text":"Dass sich kleine Beträge summieren, stimmt, und die Richtung ist richtig. Die Größenordnung aber nicht: Einige Zehntausend Jahre ergeben bei dieser Rate nur einige Dutzend Meter, nicht eine Schlucht von mehr als einem Kilometer Tiefe."},{"option":2,"text":"Gletscher können Täler tatsächlich schnell vertiefen, deshalb wirkt das als Ausweg aus der langsamen Rate. Die Messwerte beschreiben aber das Einschneiden des Flusses selbst, und von Eis ist im Szenario nirgends die Rede."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Polyak, V.; Hill, C.; Asmerom, Y. (2008): Age and Evolution of the Grand Canyon Revealed by U-Pb Dating of Water Table-Type Speleothems. Science 319, 1377–1380","oeffentlich":false,"doi":"10.1126/science.1151248"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"187fea286199a68b"}},{"id":"qx-c1-018","clusterId":"C","werkstueckRef":"C.1.5","stufe":2,"question":"Wie weit vor dem Ziel würde der Mensch auf dieser Strecke auftauchen?","options":["Etwa 15 Meter vor dem Ziel, also ungefähr dort, wo auch die Dinosaurier ausgestorben sind.","Etwa 4 bis 7 Zentimeter vor dem Ziel, also weniger als eine Handbreit vor der Ziellinie.","Etwa 45 bis 65 Zentimeter vor dem Ziel, also noch ungefähr eine Armlänge vor der Ziellinie.","Etwa 4 bis 7 Millimeter vor dem Ziel, also nur ungefähr ein Reiskorn vor der Ziellinie."],"correctIndex":1,"explanation":"Die Rechnung ist ein einfacher Dreisatz: 200.000 bis 300.000 Jahre geteilt durch 4,54 Milliarden Jahre ergibt rund 0,004 bis 0,007 Prozent der Erdgeschichte. Auf 1.000 Metern sind das etwa 4 bis 7 Zentimeter. Zur Gegenprobe: Das Aussterben der Dinosaurier läge bei Meter 985, also etwa 15 Meter vor dem Ziel; der Mensch kommt erst etwa 4 bis 7 Zentimeter vor dem Ziel. Zwischen dem Aussterben der Dinosaurier und dem Auftauchen des Menschen liegt also fast die gesamte letzte Strecke. Die Menschheit ist ein geologischer Wimpernschlag am Ende der Strecke. Unsere Intuition ist für Tage und Lebenszeiten gemacht und überfordert sich bei Milliarden von Jahren, deshalb hilft es, die Größenordnung durch eine Verhältnisrechnung zu prüfen.","coreRule":"⚡ Schätze Größenordnungen durch ein Verhältnis, nicht nach dem Gefühl: Auf der Zeitleiste der Erde sind wir ein Wimpernschlag am Ende.","beleg":"Werkstück C.1.5 (Die Schmiede-Übung „Der Zeit-Spaziergang“; Kontext & Tiefe); Fn. gl-c-erdalter (Dalrymple 2001, S. 205, 213, 217–219)","status":"entwurf","scenario":"Ein Freund sagt: „Den modernen Menschen gibt es doch schon ewig – dass die Dinosaurier lange vor uns ausgestorben sind, ist ein kleiner Unterschied.“ Um ihm die Größenordnung greifbar zu machen, überträgst du die gesamte Erdgeschichte (4,54 Milliarden Jahre) auf einen Kilometer Wegstrecke: Der Start steht für die Entstehung der Erde, das Ziel für heute. Der moderne Mensch existiert seit etwa 200.000 bis 300.000 Jahren, die Dinosaurier starben vor etwa 66 Millionen Jahren aus.","kurz":"Der Mensch macht nur rund 0,004 bis 0,007 Prozent der Erdgeschichte aus, auf einem Kilometer also etwa 4 bis 7 Zentimeter. Das Gefühl für Milliarden Jahre trügt; erst die Verhältnisrechnung macht die Größenordnung greifbar.","prueffrage":"Wie viele Meter der Strecke entsprechen einem Zehntel Prozent der gesamten Erdgeschichte, und passen die Zeitspannen der Menschheit darunter oder darüber?","rueckmeldung":[{"option":0,"text":"Die 15 Meter markieren auf der Strecke das Aussterben der Dinosaurier vor 66 Millionen Jahren. Der Mensch taucht erst viel später auf, nämlich nur wenige Zentimeter vor dem Ziel."},{"option":2,"text":"Eine Armlänge klingt plausibel, ist aber zehnmal zu viel. Wer 0,004 bis 0,007 Prozent von 1.000 Metern nachrechnet, kommt auf 4 bis 7 Zentimeter, nicht auf 45 bis 65."},{"option":3,"text":"Ein Reiskorn passt gut zum Bild vom Wimpernschlag, ist aber zehnmal zu wenig. Aus 0,004 bis 0,007 Prozent von 1.000 Metern ergeben sich 4 bis 7 Zentimeter, nicht Millimeter."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS: Geologic Time – Age of the Earth","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/age.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dalrymple, G. B. (2001): The age of the Earth in the twentieth century: a problem (mostly) solved. Geol. Soc. London Spec. Publ. 190, 205–221","oeffentlich":false,"doi":"10.1144/GSL.SP.2001.190.01.14"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"553a85a2877ca048"}},{"id":"qx-c1-019","clusterId":"C","werkstueckRef":"C.1.5","stufe":3,"question":"Ein Gesprächspartner zeigt dir das Fossil eines Meerestiers, das auf einem hohen Berg gefunden wurde, und sagt: „Das beweist eine weltweite Sintflut vor wenigen tausend Jahren.“ Welche Erwiderung nimmt den Fund ernst und erklärt ihn am sparsamsten, ohne die Tatsache selbst zu bestreiten?","options":["Der Meeresspiegel stieg im Wechsel von Warm- und Eiszeiten um viele Dutzend Meter, sodass Meerestiere zeitweise bis in die Alpen gelangten und dort liegen blieben.","Tsunamis spülen Muscheln und Seelilien tatsächlich weit landeinwärts, wo sie liegen bleiben und mit der Zeit in Sedimenten eingebettet werden.","Ehemaliger Meeresboden wurde durch die Bewegung der Erdplatten über Millionen Jahre langsam zu Hochgebirgen wie den Alpen aufgefaltet.","Gletscher haben Gesteinsbrocken mit eingeschlossenen Meerestieren aus fernen Küstenregionen herbeigeschoben und in den Alpen abgelegt."],"correctIndex":2,"explanation":"Der Fund selbst ist echt: Meerestiere lebten dort, wo heute Berge stehen. Offen ist nur, wie er dorthin kam. Die sparsamste Erklärung nimmt Prozesse, die sich heute noch beobachten lassen: Erdplatten bewegen sich, und ehemaliger Meeresboden wird über Millionen Jahre langsam zu Hochgebirgen aufgefaltet. Die radiometrische Datierung und die Abfolge der Gesteinsschichten belegen so lange Zeiträume (Tiefenzeit). Gegen den Sintflut-Einwand hilft das Konzept der Tiefenzeit: Es bietet die langsame, aber mächtigere Erklärung.","coreRule":"⚡ Wenn ein Fund zu einer einzigen großen Katastrophe passt, prüfe, ob langsame, heute beobachtbare Prozesse über sehr lange Zeit denselben Befund sparsamer erklären.","beleg":"Werkstück C.1.5 (Werkbank-Frage; Red Flags, „Sintflut“)","status":"entwurf","scenario":"Auf einer Wanderung in den Alpen entdeckst du in einer Felswand Versteinerungen von Muscheln und Seelilien. Dein Begleiter hält sie für den Beweis einer einzigen großen Überflutung vor wenigen tausend Jahren.","quote":"","quoteLabel":"","kurz":"Der Fund ist echt, offen ist nur, wie er dorthin kam. Am sparsamsten erklären ihn heute noch beobachtbare Prozesse: Bewegte Erdplatten falten Meeresboden über Millionen Jahre zu Gebirgen auf. Eine einzige junge Flut ist dafür kein Muss.","prueffrage":"Stecken die Versteinerungen in einer einzigen Schicht oder in vielen übereinanderliegenden Gesteinsschichten der Felswand?","rueckmeldung":[{"option":0,"text":"Der Meeresspiegel schwankte wirklich um viele Dutzend Meter. Das hebt aber keine Meeresablagerungen auf Gebirgshöhe, und die Alpen liegen weit oberhalb jedes solchen Pegels."},{"option":1,"text":"Tsunamis tragen Tiere tatsächlich weit ins Land, wo sie eingebettet werden können. Eine Felswand aus Meeresgestein in großer Höhe erklärt das aber nicht, denn das Gestein selbst müsste erst gehoben werden."},{"option":3,"text":"Gletscher schieben Gesteinsbrocken samt Fossilien wirklich über weite Strecken. Sie legen aber lose Blöcke ab, während hier eine Felswand vorliegt, die Schicht für Schicht im Meer entstand."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS, This Dynamic Earth: The Himalayas – Two continents collide","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/dynamic/himalaya.html","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS: Geologic Time – radiometrische Zeitskala","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/radiometric.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"18f8ca74412b114f"}},{"id":"qx-c1-020","clusterId":"C","werkstueckRef":"C.1.5","stufe":4,"question":"Jemand sagt: „Das Klima hat sich schon immer verändert – heute ist nichts Besonderes.“ Du hast Daten aus Eisbohrkernen vor dir, die das Klima über rund 800.000 Jahre rekonstruieren. Welche Frage an diese Daten prüft die Behauptung am besten?","options":["Wie schnell stieg die CO₂-Konzentration in den früheren Phasen, die die Eisbohrkerne zeigen, im Vergleich zum heutigen Anstieg?","Stimmen Eisbohrkerne aus verschiedenen Regionen im Verlauf der CO₂-Konzentration überein, sodass die Messdaten verlässlich sind?","Wie genau lässt sich die Zusammensetzung der Luftbläschen im Labor messen, und mit welchen Messfehlern ist dabei zu rechnen?","Gingen in den früheren Phasen die Temperaturänderungen den CO₂-Änderungen voraus, oder folgten sie ihnen erst mit zeitlichem Abstand?"],"correctIndex":0,"explanation":"Der Satz „Das Klima hat sich schon immer verändert“ ist richtig, beweist aber wenig: Auch wenn Veränderung früher vorkam, sagt das nichts darüber, ob die heutige Veränderung vergleichbar ist. Entscheidend ist die Rate, also wie schnell sich etwas ändert, und nicht nur, ob. Genau das lässt sich mit langen Datenreihen prüfen. Die heutige CO₂-Konzentration liegt höher als in mindestens zwei Millionen Jahren; laut IPCC (2021) ist ihr Anstieg seit 1850 in den letzten 800.000 Jahren ohne Beispiel. Zudem hat sich die Erde seit 1970 schneller erwärmt als in jedem anderen Fünfzigjahreszeitraum der letzten zweitausend Jahre. Auch die schnellsten CO₂-Änderungsraten der letzten 56 Millionen Jahre lagen mindestens um den Faktor vier darunter (geringe Konfidenz). Wer nur fragt, ob es früher Veränderungen gab, übersieht den Kern: Eine wahre Aussage („Klima änderte sich immer“) kann trotzdem in die Irre führen, wenn sie das Tempo ausblendet. Ob Bohrkerne übereinstimmen und wie genau im Labor gemessen wird, sind sinnvolle Fragen zur Verlässlichkeit der Daten, sagen aber nicht, ob das heutige Tempo ungewöhnlich ist. Die zeitliche Reihenfolge von Temperatur und CO₂ betrifft die Ursache früherer Schwankungen, nicht den Vergleich der Geschwindigkeiten. Die Daten liegen hier ohnehin vor; entscheidend ist, was man sie fragt.","coreRule":"⚡ „Das Klima änderte sich immer“ stimmt – aber die Frage ist, wie schnell. Prüfe die Änderungsrate, nicht nur das Vorkommen von Veränderung.","beleg":"Werkstück C.1.5 (Anwendung & Relevanz, „Im Kontext des Klimawandels (C.5.1)“); Fn. gl-c-ipcc-tempo (IPCC 2021, SPM A.2.1 und A.2.2, S. 8; Technical Summary S. 69)","status":"entwurf","scenario":"Eisbohrkerne enthalten eingeschlossene Luftbläschen aus vergangenen Zeiten. Aus ihnen lässt sich ablesen, wie hoch die CO₂-Konzentration in der Atmosphäre früher war und wie schnell sie sich änderte.","quote":"","quoteLabel":"","kurz":"Die Behauptung blendet das Tempo aus: Dass sich das Klima früher änderte, sagt nichts darüber, ob die heutige Änderung vergleichbar schnell ist. Erst der Vergleich der Änderungsraten in den langen Datenreihen prüft sie.","prueffrage":"Würden Eisbohrkerne auch dann frühere CO₂-Schwankungen zeigen, wenn die heutige Änderung völlig neuartig wäre?","rueckmeldung":[{"option":1,"text":"Dass Kerne aus verschiedenen Regionen übereinstimmen, spricht für verlässliche Daten. Das klärt aber nur, ob man den Daten trauen kann, nicht, ob das heutige Tempo ungewöhnlich ist."},{"option":2,"text":"Messgenauigkeit und Messfehler sind eine berechtigte Frage an Daten. Sie sagt dir aber nichts darüber, wie schnell sich CO₂ früher und heute änderte; die Daten liegen hier ohnehin vor."},{"option":3,"text":"Die Reihenfolge von Temperatur und CO₂ betrifft die Ursache früherer Schwankungen. Die Behauptung dreht sich aber um das Ausmaß der heutigen Veränderung, und dafür zählt das Tempo."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis (AR6 WGI), Abschn. A.2.1–A.2.2","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","abruf":"2026-10-04"},{"typ":"doi","kurz":"Arias, P. A. u. a. (2021): Technical Summary. In: Climate Change 2021 (AR6 WGI)","oeffentlich":false,"doi":"10.1017/9781009157896.002"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c471fba82bb254d4"}},{"id":"qx-c1-021","clusterId":"C","werkstueckRef":"C.1.6","stufe":1,"question":"Jemand sagt: „In ein paar tausend Jahren haben wir einfach bessere Antriebe, dann fliegen wir mit Lichtgeschwindigkeit zu den Nachbarsternen.“ Welcher Einwand trifft den Kern dieser Annahme am besten?","options":["Je schneller ein Schiff zwischen den Sternen fliegt, desto zerstörerischer treffen es Staub und Gasteilchen; bei Lichttempo würde es unterwegs zerstört.","Je näher ein Objekt mit Masse dem Lichttempo kommt, desto mehr Energie braucht es; für das Erreichen selbst wäre unendlich viel nötig.","Je näher ein Schiff dem Lichttempo kommt, desto langsamer vergeht an Bord die Zeit; bei Lichttempo stünde sie still, die Reise ließe sich nie zu Ende erleben.","Je stärker ein Schiff beschleunigt, desto größer die Belastung für die Besatzung; bis zum Lichttempo müsste sie mehr aushalten, als Menschen vertragen."],"correctIndex":1,"explanation":"Die Annahme übersieht, dass es hier nicht um einen Mangel an Technik geht, sondern um ein Prinzip: Für alles mit Masse wächst der Energiebedarf bei Annäherung an die Lichtgeschwindigkeit (ca. 300.000 km/s) immer weiter an und würde für das Erreichen selbst gegen unendlich gehen. Bessere Antriebe können diese Schwelle also nicht abschaffen, höchstens den Weg dorthin effizienter machen. Wer „es braucht nur bessere Technik“ sagt, behauptet daher etwas, das die Physik nicht hergibt, und müsste einen konkreten Mechanismus nennen, der die Energieschranke umgeht. Das Argument „irgendwie wird sich das lösen“ ersetzt keinen solchen Beleg.","coreRule":"⚡ Für alles mit Masse ist die Lichtgeschwindigkeit eine Schwelle, die unendlich viel Energie kosten würde: Das ist ein Prinzip, kein Technikproblem.","beleg":"Werkstück C.1.6 (Kontext & Tiefe, „Die kosmische Temposchwelle“)","status":"entwurf","scenario":"In einer Diskussion über Reisen zu anderen Sternen wird argumentiert, es sei nur eine Frage der Antriebstechnik, bis Raumschiffe mit Masse die Lichtgeschwindigkeit erreichen.","kurz":"Es geht nicht um fehlende Technik, sondern um ein Prinzip: Für alles mit Masse würde der Energiebedarf beim Erreichen der Lichtgeschwindigkeit gegen unendlich gehen. Bessere Antriebe können das nicht abschaffen. „Irgendwie lösen wir das“ ersetzt keinen Mechanismus.","prueffrage":"Welcher konkrete Mechanismus soll nach dieser Aussage das Hindernis aus dem Weg räumen, und nennt sie einen?","rueckmeldung":[{"option":0,"text":"Staub und Gas können ein sehr schnelles Schiff tatsächlich beschädigen. Das ist aber ein technisches Hindernis, das sich etwa durch Abschirmung mindern ließe, und keine Grenze, die für jede Technik gilt."},{"option":2,"text":"Die Zeitdehnung an Bord ist real. Sie verkürzt aber die erlebte Reise, statt sie zu verhindern, und sie senkt den nötigen Energieaufwand nicht. Die eigentliche Hürde bleibt dieselbe."},{"option":3,"text":"Starke Beschleunigung belastet Menschen, das stimmt. Mit längerem, sanfterem Beschleunigen lässt sich das aber mildern, die Energieschranke bliebe trotzdem. Die Belastung ist ein Nebenproblem, nicht der Kern der Annahme."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"35c302f15445590d"}},{"id":"qx-c1-022","clusterId":"C","werkstueckRef":"C.1.6","stufe":2,"question":"Du willst die Behauptung mit einer Überschlagsrechnung prüfen: Wie lange bräuchte die schnellste Sonde der Menschheit für den Hinflug zum nächsten Stern etwa?","scenario":"Ein Mann behauptet im Gespräch: „Außerirdische können uns ganz leicht besuchen. Unsere schnellste Raumsonde fliegt doch schon mit rund 700.000 km/h, da ist der nächste Stern praktisch um die Ecke.“ Der nächste Stern, Proxima Centauri, ist etwa 4,2 Lichtjahre entfernt, das sind rund 40 Billionen Kilometer. Ein Lichtjahr ist die Strecke, die Licht in einem Jahr zurücklegt; Licht fliegt mit etwa 300.000 km/s, also rund 1,08 Milliarden km/h.","options":["Etwa 66 Jahre, kaum länger als ein langes Menschenleben, wenn das Höchsttempo gehalten wird.","Etwa 660 Jahre, mehr als zehn Menschenleben, aber noch im Bereich vorstellbarer Generationenschiffe.","Etwa 6.600 Jahre, selbst im Tempo der schnellsten Sonde dauert der Hinflug Jahrtausende.","Etwa 66.000 Jahre, so lange würde die Sonde bis zum nächsten Stern unterwegs sein."],"correctIndex":2,"explanation":"Die Sonde ist mit rund 700.000 km/h nur etwa 1/1.500 so schnell wie das Licht (700.000 geteilt durch 1,08 Milliarden). Licht braucht für 4,2 Lichtjahre 4,2 Jahre, die Sonde also rund 1.500-mal so lang: grob gerechnet 6.300 Jahre, mit genaueren Werten (4,24 Lichtjahre, rund 690.000 km/h) gut 6.600 Jahre. Entscheidend ist die Größenordnung: Jahrtausende, nicht Jahrzehnte oder Jahrhunderte, und das Tempo ist noch großzügig angesetzt, denn die Sonde erreicht es nur im Sturz auf die Sonne zu; Voyager 1 mit rund 17 km/s bräuchte etwa 75.000 Jahre. Dass der Stern „praktisch um die Ecke“ liege, hält der Rechnung also nicht stand. Wer „leichte“ Besuche behauptet, muss erklären, wie ein Fahrzeug um ein Vielfaches schneller sein soll als alles, was wir bauen können.","coreRule":"⚡ Ein beeindruckend klingendes Tempo sagt nichts, solange du es nicht mit der Entfernung vergleichst: Rechne die Größenordnung nach.","beleg":"Werkstück C.1.6 (Die unmögliche Reise); Fn. gl-c-proxima (Parker Solar Probe Ende 2024, rund 690.000 km/h; Voyager 1 rund 75.000 Jahre). Szenario auf Behauptungsprüfung umgebaut, Lichtgeschwindigkeit ca. 300.000 km/s aus der Analyse, Umrechnung in km/h Allgemeinwissen.","status":"entwurf","kurz":"Die Sonde fliegt nur mit etwa 1/1.500 der Lichtgeschwindigkeit und braucht also rund 1.500-mal so lange wie das Licht mit seinen 4,2 Jahren: etwa 6.300 bis 6.600 Jahre. „Praktisch um die Ecke“ täuscht, weil ein im Alltag riesiges Tempo an Sternentfernungen gemessen winzig ist.","prueffrage":"Wie oft passt die Sondengeschwindigkeit in die Geschwindigkeit des Lichts, und was bedeutet das für die Reisezeit im Vergleich zu den 4,2 Jahren, die Licht braucht?","rueckmeldung":[{"option":0,"text":"Ein Menschenleben als Reisedauer klingt beinahe machbar, weil die Zahl 700.000 km/h so groß wirkt. Gegen das Licht gerechnet ist die Sonde aber nur etwa 1/1.500 so schnell, die Zeit wird also nicht zu 66 Jahren, sondern zu Jahrtausenden."},{"option":1,"text":"660 Jahre klingen schon nach einer gewaltigen Reise, deshalb wirkt der Wert vorsichtig genug. Mit 4,2 Jahren Lichtlaufzeit mal etwa 1.500 kommt man aber auf Jahrtausende; 660 Jahre sind rund zehnmal zu wenig."},{"option":3,"text":"Wer die riesigen Entfernungen ernst nimmt, greift leicht zur größten Zahl. Die Überschlagsrechnung ergibt für die schnellste Sonde aber rund 6.600 Jahre, ein Zehntel davon; Zehntausende Jahre bräuchte erst eine langsamere Sonde wie Voyager 1."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: The Nearest Neighbor Star","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/features/cosmic/nearest_star_info.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c098eb035d38d45f"}},{"id":"qx-c1-023","clusterId":"C","werkstueckRef":"C.1.6","stufe":3,"question":"Drei Personen äußern sich zu Außerirdischen. Wer überschreitet die Grenze von legitimer Spekulation zur Pseudowissenschaft?","options":["Person A, denn sie schließt aus der Zahl der Sterne auf Leben und sucht dann nur noch nach Signalen, die ihre Erwartung bestätigen.","Person B, denn sie stellt einen Besuch der Außerirdischen als Tatsache hin und ersetzt Belege und Mechanismus durch „sicher irgendwie“.","Person C, denn sie hält Warp-Antriebe für denkbar, obwohl es keinen Beleg gibt, und gibt ein bloßes Gedankenspiel als Wissen aus.","Person A und Person C, denn beide behaupten etwas ohne Beleg: A fremdes Leben bei vielen Sternen, C funktionierende Warp-Antriebe."],"correctIndex":1,"explanation":"Eine offene Frage zu stellen und danach zu suchen, ist legitim: Person A behauptet nichts als Tatsache, sondern prüft, und auch Person C kennzeichnet ihr Gedankenexperiment offen als Spekulation ohne Beleg. Person B dagegen behauptet einen Besuch als Faktum, obwohl die Hürden gewaltig sind: Selbst mit der Geschwindigkeit der schnellsten Sonde (Parker Solar Probe) bräuchte man rund 6.600 Jahre bis zum nächsten Stern, und nichts mit Masse erreicht Lichtgeschwindigkeit. „Sicher irgendwie gelöst“ bietet keinen plausiblen Mechanismus und ist ein klassisches Warnsignal (Argument aus Unwissenheit). Die Grenze verläuft also nicht beim Thema, sondern bei der Art, wie mit Belegen umgegangen wird.","coreRule":"⚡ Suchen und Fragen ist Wissenschaft, Behaupten ohne Beleg ist Pseudowissenschaft.","beleg":"Werkstück C.1.6 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"A: „Es wäre überraschend, wenn bei Hunderten Milliarden Sternen nur wir Leben hervorgebracht hätten. Deshalb suche ich mit Radioteleskopen nach Signalen.“ B: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat die Entfernungen sicher irgendwie überwunden. Also waren Außerirdische hier und haben die Pyramiden gebaut.“ C: „Warp-Antriebe sind bisher reine Science-Fiction. Als Gedankenexperiment finde ich sie trotzdem spannend, auch wenn es keinen Beleg gibt.“","quote":"","quoteLabel":"","kurz":"Die Grenze liegt nicht beim Thema, sondern beim Umgang mit Belegen: B gibt einen Besuch als Tatsache aus und ersetzt den Mechanismus durch „sicher irgendwie“. A fragt und sucht offen, C kennzeichnet ihr Gedankenspiel als Spekulation.","prueffrage":"Was genau behauptet Person A über außerirdisches Leben, und was tut sie, um es herauszufinden?","rueckmeldung":[{"option":0,"text":"Wer nur nach Bestätigung sucht, macht tatsächlich einen Fehler. Person A formuliert aber nur eine Erwartung („wäre überraschend“) und lässt offen, was die Suche ergibt. Sie behauptet keinen Beweis, also überschreitet sie die Grenze nicht."},{"option":2,"text":"Etwas zu erwägen, wofür es keinen Beleg gibt, ist noch keine Pseudowissenschaft. Person C nennt Warp-Antriebe selbst „reine Science-Fiction“ und ein Gedankenexperiment. Sie gibt es also gerade nicht als Wissen aus."},{"option":3,"text":"Dass beide etwas ohne Beleg sagen, klingt nach einem gemeinsamen Maßstab. Entscheidend ist aber, ob man es als Tatsache ausgibt: A äußert nur eine Erwartung und sucht, C kennzeichnet ihr Gedankenspiel offen. Keine der beiden behauptet etwas als gesichert."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bbbb13c04f5f8b16"}},{"id":"qx-c1-024","clusterId":"C","werkstueckRef":"C.1.6","stufe":4,"question":"Ein Gesprächspartner hält dagegen, dass interstellare Besuche physikalisch kaum plausibel sind. Er sagt: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat Technik wie Magie – unsere Physik gilt für sie vielleicht gar nicht.“ Welche Antwort ist die stärkste?","options":["Du bestreitest nicht, dass es solche Technik geben könnte, fragst aber, wer für die Behauptung Belege liefern muss und welche Erklärung weniger unbelegte Annahmen braucht.","Du räumst ein, dass die Wissenschaft schon Unmögliches bestätigt hat, und hältst beide Möglichkeiten für gleich wahrscheinlich, solange niemand das Gegenteil gezeigt hat.","Du fragst, welche Belege er für Technik hat, die Naturgesetze außer Kraft setzt, und hältst den Einwand für widerlegt, sobald er keine nennen kann.","Du betonst, dass die bekannten Naturgesetze durch unzählige Experimente bestätigt sind, und folgerst, dass sich eine solche Technik ausschließen lässt."],"correctIndex":0,"explanation":"Der Einwand schließt jede Gegenprobe im Voraus aus: Gilt die bekannte Physik „vielleicht gar nicht“, lässt sich mit nichts mehr argumentieren. Zwei Werkzeuge greifen hier. Erstens die Beweislast: Wer eine außergewöhnliche Behauptung aufstellt, muss sie belegen, und ein Gegner muss nicht das Unmögliche widerlegen. Zweitens Ockhams Rasiermesser: Solange keine außergewöhnlichen Beweise vorliegen, ist die Erklärung vorzuziehen, die mit weniger unbelegten Annahmen auskommt. „Menschen haben es selbst gebaut“ braucht keine zusätzliche, unbelegte Wundertechnik. Dass sich schon manches Unmögliche bestätigt hat, stimmt, doch daraus folgt keine Gleichwertigkeit beider Seiten: Wer die Behauptung aufstellt, muss sie belegen. Belege zu fordern ist richtig, aber fehlt der Beleg, ist die Behauptung unbelegt und nicht widerlegt. Dass die bekannten Naturgesetze gut belegt sind, spricht gegen Wundertechnik, schließt sie aber nicht aus, denn auch „unmöglich“ ist eine Behauptung, die sich nicht belegen lässt.","coreRule":"⚡ Wer „Magie-Technik“ behauptet, trägt die Beweislast – und bis Belege kommen, gewinnt die Erklärung mit den wenigsten unbelegten Annahmen.","beleg":"Werkstück C.1.6 (Werkbank-Frage; verlinkt auf Werkstück A.4 Beweislast und A.1.1 Ockhams Rasiermesser)","status":"entwurf","scenario":"In einer Diskussion über angebliche Besuche Außerirdischer weist jemand auf Sternentfernungen und die Lichtgeschwindigkeit hin.","kurz":"Der Einwand entzieht sich jeder Gegenprobe. Daher zählt, wer die Behauptung belegen muss und welche Erklärung mit weniger unbelegten Annahmen auskommt. Wer fehlende Belege schon für eine Widerlegung hält, macht aus „unbelegt“ ein „widerlegt“.","prueffrage":"Ließe sich der Einwand „unsere Physik gilt vielleicht gar nicht“ durch irgendeine Beobachtung je widerlegen?","rueckmeldung":[{"option":1,"text":"Dass die Wissenschaft schon manches Unmögliche bestätigt hat, stimmt. Daraus folgt aber keine Gleichwertigkeit: Wer eine Behauptung aufstellt, muss sie belegen, und ein fehlender Gegenbeweis macht sie nicht wahrscheinlicher."},{"option":2,"text":"Belege zu fordern ist richtig. Fehlt der Beleg, ist die Behauptung aber unbelegt und nicht widerlegt. Außerdem bleibt offen, welche Erklärung mit weniger unbelegten Annahmen auskommt."},{"option":3,"text":"Gut belegte Naturgesetze sprechen tatsächlich gegen Wundertechnik. Ausschließen können sie sie nicht, denn auch „unmöglich“ ist eine Behauptung, die sich nicht belegen lässt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (2004, überarb. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024), Abschn. 3.6","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"16ca3806f83ddc2f"}},{"id":"qx-c1-025","clusterId":"C","werkstueckRef":"C.2.1","stufe":1,"question":"Mit welchem Einwand lässt sich die Behauptung des Verkäufers am besten prüfen?","options":["Stoffe bestehen aus einzelnen Teilchen. Nach genügend Verdünnungsschritten ist statistisch kein Teilchen des Wirkstoffs mehr enthalten, und was fehlt, kann nicht wirken.","Je stärker man verdünnt, desto gleichmäßiger verteilen sich die Teilchen im Lösungsmittel. Die Menge sinkt, aber die Wirkung des Stoffes bleibt dabei erhalten.","Je stärker man verdünnt, desto weniger Teilchen sind noch enthalten. Dafür entfaltet jedes einzelne Teilchen eine größere Wirkung als in der Ausgangslösung.","Eine Verdünnung wirkt nur dann, wenn sie in einem sauberen Labor erfolgt ist. Verunreinigungen schwächen die Wirkung des Wirkstoffs sonst deutlich ab."],"correctIndex":0,"explanation":"Materie ist nicht unendlich teilbar: Man kann einen Zuckerwürfel nicht beliebig oft halbieren, irgendwann bleibt ein einzelnes Zuckermolekül. Weil jeder Verdünnungsschritt die Teilchenzahl senkt, ist irgendwann im Schnitt weniger als ein Teilchen übrig; bei Schritten von 1 zu 100 ist diese Grenze schon nach etwa zwölf Schritten erreicht (Verdünnung 1 zu 10²⁴). Bei 30 Schritten (Verdünnung 1 zu 10⁶⁰) ist sie weit überschritten: Selbst bei einer Ausgangslösung von einem Mol pro Liter, also rund 6 × 10²³ Molekülen, blieben im Mittel nur etwa 6 × 10⁻³⁷ Moleküle pro Liter. Die Behauptung „je verdünnter, desto stärker“ kehrt die Dosis-Wirkungs-Beziehung um und ist ein klares Warnsignal. Wer sie trotzdem aufrechterhält, muss eine nicht stoffliche Ursache behaupten und dafür eigene Belege liefern.","coreRule":"⚡ Materie besteht aus Teilchen. Wer immer weiter verdünnt, landet irgendwann bei null Teilchen – und was nicht mehr enthalten ist, kann nicht wirken.","beleg":"Werkstück C.2.1 (Kernidee; Avogadro-Grenze; Red Flags; Fußnoten gl-c-avogadro, gl-c-c30). Frage zur Denkaufgabe umgebaut: Behauptung prüfen statt Definition abfragen.","status":"entwurf","scenario":"Ein Verkäufer bietet ein Mittel an, bei dem ein Wirkstoff 30-mal hintereinander im Verhältnis 1 zu 100 verdünnt wurde. Er sagt: „Je öfter man verdünnt, desto stärker wirkt es. Verdünnen kann man schließlich unendlich weit.“","kurz":"Stoffe bestehen aus Teilchen, und jede Verdünnung senkt deren Zahl. Bei 30 Schritten im Verhältnis 1 zu 100 ist im Schnitt kein einziges Teilchen mehr übrig. Der Fehler liegt darin, Verdünnung wie ein stufenloses Verteilen zu denken, das nie endet.","prueffrage":"Wie viele Teilchen des Wirkstoffs wären nach 30 solchen Schritten im Mittel in einem Liter noch enthalten?","rueckmeldung":[{"option":1,"text":"Gleichmäßiges Verteilen klingt, als bliebe vom Stoff überall ein wenig erhalten. Mit jedem Schritt sinkt aber die Zahl der Teilchen, bis im Mittel keines mehr übrig ist, und was fehlt, kann nicht wirken."},{"option":2,"text":"Dass die Teilchenzahl sinkt, stimmt. Ein einzelnes Molekül bleibt aber dasselbe, ob viel oder wenig Wasser es umgibt; weniger Stoff bedeutet in der Regel weniger Wirkung, nicht mehr."},{"option":3,"text":"Saubere Arbeit ist sinnvoll, trifft hier aber nicht den Kern. Selbst im reinsten Labor ist nach so vielen Schritten vom Wirkstoff nichts mehr übrig; die Frage ist die Teilchenzahl, nicht Verunreinigung."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"},{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7b2f10a28e0d2157"}},{"id":"qx-c1-026","clusterId":"C","werkstueckRef":"C.2.1","stufe":2,"question":"Ein Anbieter wirbt: „Unser Mittel in C30 enthält die volle Kraft der Ausgangssubstanz.“ C30 bedeutet: 30 Verdünnungsschritte im Verhältnis 1 zu 100, also insgesamt 1 zu 10⁶⁰. Ein Mol (ca. 6 × 10²³ Moleküle) der Ausgangssubstanz steckt in einem Liter Urtinktur. Du prüfst das Versprechen mit einer Überschlagsrechnung: Wie viel Lösung müsstest du einnehmen, um mit etwa 50 % Chance ein einziges Molekül der Ausgangssubstanz zu erwischen?","options":["Ein großes Schwimmbecken mit einigen Millionen Litern – die Verdünnung beträgt nur 10³⁰, danach steckt im Schnitt ein Molekül in dieser Menge.","Schon ein einziger Tropfen – 30 Schritte im Verhältnis 1 zu 100 verdünnen nur 30 × 100 = 3000-fach, also bleiben unzählige Moleküle übrig.","Eine Kugel mit mehreren hundert Lichtjahren Radius – bei einer Verdünnung von 10⁶⁰ braucht man für ein Molekül ebenso viele Liter Lösung.","Eine Kugel mit dem Durchmesser des Abstands Erde–Sonne, also rund 150 Millionen Kilometer – unvorstellbar viel Lösung für ein einzelnes Molekül."],"correctIndex":3,"explanation":"Rechne in Größenordnungen: Ein Liter Urtinktur enthält etwa 6 × 10²³ Moleküle. Nach der Verdünnung um den Faktor 10⁶⁰ bleiben im Mittel rund 6 × 10⁻³⁷ Moleküle pro Liter. Für ein einziges erwartetes Molekül brauchst du also etwa 1,7 × 10³⁶ Liter, das ist eine Kugel mit rund 1,5 × 10¹¹ Metern Durchmesser, ungefähr der Abstand zwischen Erde und Sonne. Für eine 50-Prozent-Chance genügt etwas weniger, rund das 0,9-Fache dieses Durchmessers; bei einer schwächeren Urtinktur würde die Kugel noch größer. Der Denkfehler dahinter ist, sich bei Verdünnungen von 10⁶⁰ Vorstellbares einzureden, statt nachzurechnen. Die Rechnung zeigt: In einer üblichen Dosis ist nichts von der Ursubstanz zu erwarten, das Werbeversprechen von der „vollen Kraft“ ist stofflich leer.","coreRule":"⚡ Bei extremen Verdünnungen gilt: erst die Teilchenzahl überschlagen, dann über die Wirkung reden. Ab etwa 1 zu 10²⁴ ist pro Mol statistisch nur noch rund ein Molekül der Ausgangssubstanz zu erwarten; darüber praktisch keines mehr.","beleg":"Werkstück C.2.1 (Kontext & Tiefe, „Die mathematische Realität der Homöopathie“); Fn. gl-c-c30 (Überschlag für eine einmolare Urtinktur)","status":"entwurf","scenario":"","kurz":"Nach 10⁶⁰-facher Verdünnung bleiben von etwa 6 × 10²³ Molekülen pro Liter nur noch rund 6 × 10⁻³⁷ übrig. Für ein einziges Molekül bräuchte man eine Lösungskugel von Erde–Sonne-Größe. Schätzen ohne Nachrechnen führt hier in die Irre.","prueffrage":"Wie viele Moleküle bleiben im Mittel in einem Liter, wenn 6 × 10²³ Moleküle um den Faktor 10⁶⁰ verdünnt werden?","rueckmeldung":[{"option":0,"text":"Die Überlegung „im Schnitt ein Molekül“ stimmt, doch der Exponent nicht: 30 Schritte zu je 1 zu 100 ergeben 10⁶⁰, nicht 10³⁰. Mit der richtigen Verdünnung wird die nötige Menge um ein Vielfaches größer als ein Schwimmbecken."},{"option":1,"text":"Die Schritte zu addieren, liegt nahe, wenn man an „30 mal etwas tun“ denkt. Jeder Schritt verdünnt aber den Rest erneut um den Faktor 100, die Faktoren multiplizieren sich zu 10⁶⁰. Deshalb bleiben keineswegs unzählige Moleküle übrig."},{"option":2,"text":"Die Verdünnung von 10⁶⁰ und die riesige Menge sind richtig erkannt. Es fehlt der Ausgangswert: Schon ein Liter Urtinktur enthält rund 6 × 10²³ Moleküle. Rechnet man das gegen, schrumpft die nötige Kugel auf etwa Erde–Sonne-Größe."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"09abc702e39fbc19"}},{"id":"qx-c1-027","clusterId":"C","werkstueckRef":"C.2.1","stufe":3,"question":"Ein Homöopath sagt: „Du denkst zu materialistisch – es geht um eine geistartige Information, die beim Potenzieren auf den Trägerstoff übergeht.“ Du willst im Gespräch bleiben und nichts behaupten, was du selbst nicht belegen kannst. Welche Antwort ist am sinnvollsten?","options":["Du fragst ihn, mit welchem Messgerät sich die Information im Trägerstoff nachweisen lässt, und hältst sie ohne Nachweis für nicht existent.","Du fragst ihn, wie sich die Wirkung dieser Information von der Wirkung des bloßen Glaubens daran unterscheiden ließe.","Du fragst ihn, wie viele Patienten nach der Behandlung beschwerdefrei sind, und nimmst diese Zahl als Maß für die Wirkung.","Du verweist darauf, dass die Fachwelt seine Sicht mehrheitlich ablehnt, und bittest ihn, zuerst deren Einwände zu widerlegen."],"correctIndex":1,"explanation":"Am sinnvollsten ist es, nicht die Existenz der „geistartigen Information“ zu widerlegen, sondern zu fragen, wie sich ihre Wirkung von der reinen Wirkung des Glaubens daran unterscheiden lässt. Dafür dienen der Placebo-Effekt und die Hierarchie der Evidenz: Eine behauptete Wirkung zählt erst, wenn sie sich vom Glauben daran trennen lässt. So gibst du dem Gegenüber die Chance, seine Behauptung testbar zu machen, und das Gespräch bleibt offen. Dass eine Wirkung nicht über den Glauben hinausgeht, folgt aus einem Test, nicht aus einer Vorannahme. Die Frage nach einem Messgerät klingt methodisch, doch wer ohne Nachweis die Existenz bestreitet, behauptet selbst etwas, das er nicht belegen kann. Dass sich Patienten besser fühlen, lässt sich auch durch Erwartung und natürlichen Verlauf erklären und trennt die Wirkung nicht vom Glauben. Die Meinung der Mehrheit der Fachleute kann ein Hinweis sein, ist aber kein Test seiner Behauptung.","coreRule":"⚡ Frag nicht „Beweise, dass es sie nicht gibt“, sondern „Woran würden wir eine Wirkung erkennen, und wie unterscheiden wir sie vom Glauben daran?“","beleg":"Werkstück C.2.1 (Werkbank-Frage; Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“)","status":"entwurf","scenario":"","kurz":"Fruchtbar ist die Frage, wie sich die Wirkung der „Information“ von der des bloßen Glaubens daran trennen ließe. Sie macht die Behauptung testbar, ohne ihre Existenz zu bestreiten, und hält das Gespräch offen.","prueffrage":"Könnte irgendeine Beobachtung den Homöopathen davon überzeugen, dass es die „geistartige Information“ nicht gibt?","rueckmeldung":[{"option":0,"text":"Die Frage nach einem Nachweis ist berechtigt. Wer aber ohne Nachweis die Existenz bestreitet, behauptet selbst etwas, das er nicht belegen kann, und beendet damit eher das Gespräch, als die Aussage prüfbar zu machen."},{"option":2,"text":"Beschwerdefreiheit ist ein sinnvoller Ergebnisparameter. Eine Zahl allein trennt aber nicht, ob die Information, die Erwartung der Patienten oder der natürliche Verlauf besser gemacht hat. Ohne Vergleich sagt sie über die Wirkung der Information wenig."},{"option":3,"text":"Dass viele Fachleute seine Sicht ablehnen, kann ein Hinweis sein. Seine Behauptung testet das aber nicht, und ihn zuerst alle Einwände widerlegen zu lassen, verschiebt das Gespräch von prüfbaren Aussagen zu Autorität."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices: assessing the evidence and ensuring consistency in regulating medical claims in the EU","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5efda413d175602b"}},{"id":"qx-c1-028","clusterId":"C","werkstueckRef":"C.2.1","stufe":4,"question":"Ein Anbieter verspricht Heilung durch „digital übertragene Schwingungsinformationen“, ganz ohne Wirkstoff. Mit welchem Einwand kannst du diese Behauptung am besten prüfen?","options":["Dass etwas natürlich ist, macht es noch nicht heilsam, denn der Verweis auf Natürlichkeit ist kein Beleg für eine Wirkung.","Eine Behauptung, die sich jeder Beobachtung nachträglich anpassen lässt, ist nicht widerlegbar und damit wertlos als Erklärung.","Information braucht einen physikalischen Träger, und ohne Teilchen der Substanz im Wasser gibt es nichts, was wirken könnte.","Wer ein Gerät verkauft, hat ein Geschäftsinteresse an der Wirkung, deshalb ist seine Behauptung mit besonderer Vorsicht zu behandeln."],"correctIndex":2,"explanation":"Information braucht einen physikalischen Träger. Eine Behauptung, die Wirkung ohne jeden Wirkstoff verspricht, muss deshalb erklären können, was genau übertragen wird und woran es im Wasser steckt. Ohne Moleküle der Substanz im Wasser gibt es keinen Träger, der etwas übertragen könnte. Hier soll nach der Werbung selbst nicht einmal eine verdünnte Spur der Substanz ins Wasser gelangen: Es bleibt also nichts übrig, was wirken könnte. Wer „Information“ ohne Träger behauptet, verschiebt die Frage nur, statt sie zu beantworten. Dass Natürliches nicht automatisch heilsam ist, stimmt zwar, doch die Werbung beruft sich gar nicht auf Natürlichkeit, sondern auf eine technische Übertragung. Dass sich unwiderlegbare Behauptungen nicht prüfen lassen, stimmt ebenfalls, trifft hier aber nicht zu, denn die Werbung nennt einen konkreten Weg und passt sich keiner Beobachtung nachträglich an. Das Geschäftsinteresse des Anbieters ist ein Grund für Vorsicht, prüft aber die Behauptung selbst nicht.","coreRule":"⚡ Ohne Träger keine Information, ohne Teilchen keine Wirkung.","beleg":"Werkstück C.2.1 (Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“; Red Flags)","status":"entwurf","scenario":"In der Werbung heißt es: „Unser Gerät überträgt die Heilinformation der Substanz digital auf Ihr Trinkwasser. Es ist kein Wirkstoff nötig, die Information genügt.“","kurz":"Information braucht einen physikalischen Träger. Ohne Moleküle der Substanz im Wasser fehlt, was etwas übertragen könnte. Der Fehler wäre, bei „digital“ und „Information“ nicht nachzufragen, woran sie im Wasser eigentlich steckt.","prueffrage":"Würde sich am Wasser etwas ändern, wenn das Gerät statt der Heilinformation eine leere Datei überträgt, und wie ließe sich das prüfen?","rueckmeldung":[{"option":0,"text":"Dass Natürliches nicht automatisch heilsam ist, stimmt. Die Werbung beruft sich aber gar nicht auf Natürlichkeit, sondern auf eine technische Übertragung. Der Einwand trifft die Behauptung daher nicht."},{"option":1,"text":"Unwiderlegbare Behauptungen sind tatsächlich als Erklärung wertlos. Hier trifft das aber nicht zu: Die Werbung nennt einen konkreten Weg und biegt sich nicht nachträglich jeder Beobachtung zurecht. Der Einwand führt an der Behauptung vorbei."},{"option":3,"text":"Geschäftsinteresse ist ein guter Grund zur Vorsicht. Es sagt aber nur etwas über die Quelle und prüft die Behauptung selbst nicht: Ob etwas wirken kann, ließe sich auch bei einem Anbieter ohne Eigeninteresse fragen."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"092d70fa2c2d7271"}},{"id":"qx-c1-029","clusterId":"C","werkstueckRef":"C.2.2","stufe":1,"question":"Was ist an der Aussage der Mitbewohnerin fehlerhaft, und was ist chemisch tatsächlich passiert?","scenario":"Jemand toastet eine Scheibe Brot zu lange. Sie wird schwarz und knusprig, es steigt Rauch auf, und die verkohlte Scheibe wiegt deutlich weniger als vorher. Eine Mitbewohnerin meint: „Beim Verbrennen wird Materie zerstört, sonst müsste die Scheibe ja gleich viel wiegen.“","options":["Die Hitze hat nur das Wasser aus dem Brot verdampft, und die schwarze Kruste ist unverändertes Brot, das lediglich dunkler wurde; das Fehlende ist allein das verdunstete Wasser.","Die Hitze hat die Atome des Brots teilweise in neue Elemente verwandelt: Die schwarze Kruste besteht jetzt aus anderen Atomen als vorher, und der Rest ist als Rauch entwichen.","Die Hitze hat die Moleküle des Brots nur auseinandergetrieben, ein Teil ist als Rauch entwichen; beim Abkühlen ordnen sich die übrigen wieder an, es war ein rein physikalischer Vorgang.","Die Bindungen im Brot sind aufgebrochen und dieselben Atome haben sich neu angeordnet, zum Teil zu Kruste, zum Teil zu Gasen wie CO₂ und Wasserdampf, die entwichen sind."],"correctIndex":3,"explanation":"Die Mitbewohnerin schließt vom Gewichtsverlust auf zerstörte Materie. Dieser Schluss trägt nicht: Die Scheibe wiegt weniger, weil Wasserdampf, Kohlendioxid und andere Gase im Rauch entweichen. Die Hitze bricht die Bindungen der Kohlenhydrat-Moleküle auf, und die Atome ordnen sich neu an: Ein Großteil des Kohlenstoffs bleibt als schwarze Kruste zurück, Wasserstoff, Sauerstoff und ein Teil des Kohlenstoffs entweichen als Gase; Sauerstoff steckt dafür schon reichlich in den Kohlenhydraten, ein Teil kann auch aus der Luft kommen. Bei einer chemischen Reaktion gehen keine Atome verloren und es kommen keine hinzu, nur ihre Anordnung ändert sich; Elemente wandeln sich erst bei Kernreaktionen um.","coreRule":"⚡ Chemie ordnet Atome neu an: Atome entstehen nicht und verschwinden nicht. Fehlt Masse, sucht man die unsichtbaren Produkte, statt Zerstörung anzunehmen.","beleg":"Werkstück C.2.2 (Das verbrannte Brot; Kernidee; Kontext & Tiefe, „Materie bleibt erhalten“)","status":"entwurf","kurz":"Die Scheibe wiegt weniger, weil Gase wie Wasserdampf und CO₂ entweichen. Bei der Reaktion ordnen sich dieselben Atome neu an, es geht keine Materie verloren. Wer vom Gewichtsverlust auf zerstörte Materie schließt, übersieht die Gase im Rauch.","prueffrage":"Was geschieht mit allem, was beim Toasten als Rauch oder Dampf aufsteigt, und wo würdest du es mitwiegen?","rueckmeldung":[{"option":0,"text":"Dass Wasser verdunstet, stimmt und trägt zum Gewichtsverlust bei. Es erklärt aber weder die schwarze, spröde Kruste noch den Rauch; beides deutet auf neue Stoffe hin, nicht auf bloß getrocknetes Brot."},{"option":1,"text":"Dass die Kruste anders aussieht und ein Teil als Rauch entweicht, stimmt. Neue Elemente entstehen aber erst bei Kernreaktionen; die Kruste besteht größtenteils aus Kohlenstoff, der schon im Brot steckte."},{"option":2,"text":"Ein Teil entweicht tatsächlich als Rauch. Rein physikalisch ist der Vorgang aber nicht: Verdampfen ließe sich beim Abkühlen umkehren, verkohltes Brot wird jedoch nie wieder zu Brot, weil neue Stoffe entstanden sind."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax (Flowers u. a.): Chemistry 2e, Abschnitt 2.1 „Early Ideas in Atomic Theory“","oeffentlich":true,"url":"https://openstax.org/books/chemistry-2e/pages/2-1-early-ideas-in-atomic-theory","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9b50c4e4c82e8abc"}},{"id":"qx-c1-030","clusterId":"C","werkstueckRef":"C.2.2","stufe":2,"question":"Welche Schlussfolgerung ist die sparsamste?","options":["Die Atome sind in beiden Stoffen unterschiedlich angeordnet; diese Anordnung bestimmt die Eigenschaften, ein Widerspruch entsteht nicht.","Die Atome sind unterschiedliche Isotope des Kohlenstoffs; ihre verschiedenen Massen bestimmen die Eigenschaften, ein Widerspruch entsteht nicht.","Graphit enthält wie in Bleistiftminen Beimengungen von Ton; dieser Anteil bestimmt die Härte, ein Widerspruch entsteht nicht.","Der Druck bei der Entstehung des Diamanten macht seine Atome selbst härter; diese Härte der Atome bestimmt die Eigenschaften, ein Widerspruch entsteht nicht."],"correctIndex":0,"explanation":"Der scheinbare Widerspruch entsteht nur durch die versteckte Annahme, dass dieselben Atome immer dieselben Eigenschaften ergeben müssten. Doch Graphit und Diamant bestehen beide aus reinem Kohlenstoff, und weil die Atome unterschiedlich angeordnet sind, ist das eine ein weiches Schmiermittel und das andere eines der härtesten bekannten Materialien. Die Erklärung kommt ohne zusätzliche Annahmen aus.","coreRule":"⚡ Nicht nur woraus ein Stoff besteht, sondern wie die Atome angeordnet sind, entscheidet über seine Eigenschaften.","beleg":"Werkstück C.2.2 (Kontext & Tiefe, „Struktur bestimmt Funktion“)","status":"entwurf","scenario":"Eine Chemikerin sagt: „Graphit und Diamant bestehen beide aus reinem Kohlenstoff. Trotzdem ist der eine ein weiches Schmiermittel, der andere eines der härtesten bekannten Materialien.“ Ein Zuhörer meint, das sei ein Widerspruch.","kurz":"Beide Stoffe bestehen aus reinem Kohlenstoff, die Atome sind aber verschieden angeordnet. Der scheinbare Widerspruch beruht auf der Annahme, gleiche Atome müssten stets gleiche Eigenschaften ergeben, und die braucht niemand.","prueffrage":"Was ist über beide Stoffe gesichert, und wie viel muss man darüber hinaus annehmen, um ihren Unterschied zu erklären?","rueckmeldung":[{"option":1,"text":"Isotope gibt es wirklich, sie unterscheiden sich aber nur in der Zahl der Neutronen und verhalten sich chemisch nahezu gleich. Ein so großer Härteunterschied lässt sich damit nicht erklären."},{"option":2,"text":"Beimengungen wie Ton verändern Eigenschaften tatsächlich, und Bleistiftminen sind ein bekanntes Beispiel. Die Chemikerin spricht aber ausdrücklich von reinem Kohlenstoff, die Erklärung bräuchte also eine Annahme, die der Aussage widerspricht."},{"option":3,"text":"Der Druck bei der Entstehung spielt beim Diamanten tatsächlich eine Rolle. Er bestimmt aber, wie sich die Atome anordnen, und macht die Atome selbst nicht härter: Die sind in beiden Stoffen gleich."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"LibreTexts Chemistry: „14.04: Allotropes of Carbon“ (Map: Inorganic Chemistry, Housecroft)","oeffentlich":true,"url":"https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Map:_Inorganic_Chemistry_(Housecroft)/14:_The_Group_14_Elements/14.04:_Allotropes_of_Carbon","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"01374e4769b148de"}},{"id":"qx-c1-031","clusterId":"C","werkstueckRef":"C.2.2","stufe":3,"question":"Welchen Denkfehler macht diese Person?","options":["Die Person vergleicht Herkunft statt Struktur: Glutamat kommt als Aminosäure in Tomaten und Parmesan natürlich vor, und identische Moleküle reagieren im Körper gleich.","Die Person folgt der Mehrheit statt den Belegen: Weil viele MSG für schädlich und Tomaten und Parmesan für gesund halten, übernimmt sie beides, ohne die Stoffe selbst zu prüfen.","Die Person schließt von der zeitlichen Folge auf die Ursache: Weil sie sich nach Tomaten und Parmesan wohlfühlt und nach MSG-haltigem Essen nicht, macht sie die Stoffe dafür verantwortlich.","Die Person bekämpft ein Zerrbild der Gegenseite: Sie tut so, als hielten MSG-Befürworter jeden Zusatzstoff für harmlos, und widerlegt das mit Tomaten und Parmesan als Beispielen."],"correctIndex":0,"explanation":"„Natürlich“ und „synthetisch“ beschreiben die Herkunft eines Stoffes, nicht das Molekül selbst. Glutamat ist eine Aminosäure, die in reifen Tomaten und in Parmesan reichlich frei vorkommt und dort für den Umami-Geschmack sorgt. MSG ist das Natriumsalz der Glutaminsäure: Gelöst in Wasser oder Speichel liegt dasselbe Glutamat vor wie in der Tomate, dazu Natrium wie aus Kochsalz. Für die Wirkung im Körper zählt die Struktur, nicht die Herkunft, ähnlich wie bei Vitamin C aus der Orange und aus dem Labor. Wer das eine meidet und das andere genießt, urteilt nach dem Etikett statt nach dem Stoff. Sich nach der Mehrheit zu richten klingt vernünftig, doch die Person nennt weder eine Mehrheit noch Fachleute, ihr Maßstab ist allein das Wort „natürlich“. Von der zeitlichen Folge auf die Ursache zu schließen ist ein verbreiteter Fehler, aber von einem eigenen Erlebnis nach dem Essen ist hier keine Rede. Ein Zerrbild der Gegenseite wäre ebenfalls ein Fehler, doch eine Gegenseite, deren Position sie verzerren könnte, kommt in ihrer Aussage nicht vor.","coreRule":"⚡ „Natürlich“ oder „synthetisch“ sagt nichts über das Molekül – seine Struktur zählt.","beleg":"Werkstück C.2.2 (Werkbank-Frage; Anwendung & Relevanz, „Natürlich vs. Chemisch/Synthetisch“)","status":"entwurf","scenario":"Jemand sagt: „Ich vermeide Mononatriumglutamat (MSG) in meinem Essen, weil es unnatürlich und schädlich ist. Dafür esse ich gern Tomaten und Parmesan, denn die sind natürlich und gesund.“","quote":"","quoteLabel":"","kurz":"Entscheidend ist der Stoff, nicht das Etikett: Glutamat aus Tomate oder Parmesan ist dasselbe Molekül wie in MSG und wirkt im Körper gleich. Die Person urteilt nach der Herkunft („natürlich“), obwohl die Struktur zählt.","prueffrage":"Was steckt in einer reifen Tomate oder im Parmesan chemisch alles drin, und worauf geht ihr herzhafter Geschmack zurück?","rueckmeldung":[{"option":1,"text":"Sich nach der Mehrheit zu richten, wäre ein möglicher Fehler. Hier nennt die Person aber weder eine Mehrheit noch Fachleute. Ihr einziger Maßstab ist das Wort „natürlich“, und genau das trägt nicht."},{"option":2,"text":"Von der zeitlichen Folge auf die Ursache zu schließen, ist ein verbreiteter Fehler. Von einem Erlebnis nach dem Essen ist in der Aussage aber keine Rede. Sie begründet ihr Urteil allein mit „natürlich“ und „unnatürlich“."},{"option":3,"text":"Ein Zerrbild setzt eine Gegenseite voraus, deren Position verzerrt wird. In der Aussage spricht die Person nur über ihr eigenes Essen, niemand widerspricht ihr. Tomaten und Parmesan dienen ihr als Beispiele für Gesundes, nicht als Widerlegung."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration: „Questions and Answers on Monosodium glutamate (MSG)“","oeffentlich":true,"url":"https://www.fda.gov/food/food-additives-petitions/questions-and-answers-monosodium-glutamate-msg","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b00ca5f064ec3bb6"}},{"id":"qx-c1-032","clusterId":"C","werkstueckRef":"C.2.2","stufe":4,"question":"Ein Anbieter behauptet, nicht näher benannte „Toxine“ lagerten sich im Körper ab, sein Präparat „ziehe sie heraus“. Welche Gegenfrage prüft diese Behauptung am besten?","options":["Welche Stoffe genau gemeint sind und welche chemische Reaktion im Körper ablaufen soll, denn jede Wirkbehauptung braucht beides.","Ob das Präparat natürlichen Ursprungs ist, denn natürliche Stoffe reagieren im Körper anders als im Labor hergestellte.","Wie viel Energie das Präparat enthält, denn nur Energie kann die Stoffe aus dem Körper austreiben.","Ob Kunden von einer Besserung berichten, denn Erfahrungsberichte gelten als sicherer Beleg für die Wirkung des Präparats."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist erst prüfbar, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion abläuft. „Toxine“ oder „Schlacken“ ohne Stoffbenennung lassen sich weder nachweisen noch widerlegen und sind ein Warnsignal. Der Körper wandelt außerdem selbst unzählige potenziell schädliche Stoffe um: Die Leber macht sie wasserlöslich, damit sie ausgeschieden werden können. Die Herkunft („natürlich“) sagt nichts über die Reaktion, denn ein Molekül mit gleicher Struktur reagiert gleich, egal woher es stammt. Und Zufriedenheitsberichte benennen weder Stoffe noch Reaktion und beantworten deshalb nicht die Frage nach dem Wirkmechanismus.","coreRule":"⚡ Frag nach den „Lego-Steinen“: Welche Stoffe, welche Reaktion?","beleg":"Werkstück C.2.2 (Aktivierungs-Frage; Anwendung & Relevanz, „Gegen die ‚Detox‘-Mythen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkbehauptung lässt sich erst prüfen, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion ablaufen soll. „Toxine“ ohne Namen kann man weder nachweisen noch widerlegen. Gerade das macht die Behauptung verdächtig.","prueffrage":"Lässt sich die Behauptung so, wie sie dasteht, überhaupt nachmessen, und woran würdest du das festmachen?","rueckmeldung":[{"option":1,"text":"Die Herkunft eines Stoffes sagt nichts darüber, wie er im Körper reagiert: Ein Molekül mit gleicher Struktur verhält sich gleich, egal woher es stammt. Außerdem bleibt offen, welche Stoffe gemeint sind und was passieren soll."},{"option":2,"text":"Der Energiegehalt hat mit dem Entfernen von Stoffen aus dem Körper nichts zu tun, und Energie allein treibt nichts heraus. Die Frage klärt weder, welche Stoffe gemeint sind, noch, welche Reaktion ablaufen soll."},{"option":3,"text":"Berichte über eine Besserung wirken überzeugend, weil sie konkret erlebt sind. Eine Besserung kann aber auch von Erwartung oder vom natürlichen Verlauf kommen, und die Berichte nennen weder Stoffe noch Reaktion."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): „Detox diets for toxin elimination and weight management: a critical review of the evidence“, J Hum Nutr Diet 28(6), 675–686","oeffentlich":true,"doi":"10.1111/jhn.12286","url":"https://pubmed.ncbi.nlm.nih.gov/25522674/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f319f80cf15ee322"}},{"id":"qx-c1-033","clusterId":"C","werkstueckRef":"C.2.3","stufe":1,"question":"Welche Einschätzung kannst du deiner Tante physikalisch begründet geben?","options":["Firma A verletzt nur die Energieerhaltung, denn wo keine Energie verloren gehen kann, fällt auch keine Abwärme an; die Angaben von Firma B sind physikalisch möglich.","Beide Firmen verletzen die Energieerhaltung: A erzeugt Strom aus dem Nichts, und bei B gehen 10 % der Energie als Wärme verloren, sind also endgültig vernichtet.","Beide Firmen sind physikalisch möglich: A arbeitet mit nahezu reibungsfreien Teilen ganz ohne Verluste, und B nutzt den Bach als Quelle, also verletzt keine ein Gesetz.","Firma A verletzt zweierlei: Strom ohne Quelle widerspricht der Energieerhaltung, ein Gehäuse ohne Abwärme dem Zweiten Hauptsatz; die Angaben von Firma B sind möglich."],"correctIndex":3,"explanation":"Die beiden Versprechen von Firma A sind zwei verschiedene Verstöße, wie bei einer Bank, die Geld aus dem Nichts auszahlt und jede Transaktion ohne Gebühren abwickelt. Strom ohne jede Energiequelle wäre Energie aus dem Nichts, und Energie kann weder erzeugt noch vernichtet werden (Erster Hauptsatz). Eine völlig verlustfreie Umwandlung gibt es ebenfalls nicht: Bei jedem realen Vorgang wird ein Teil der nutzbaren Energie zu Abwärme, die sich nicht vollständig zurück in Arbeit verwandeln lässt, die Entropie steigt (Zweiter Hauptsatz). Firma B dagegen nennt eine Quelle, das fließende Wasser, und räumt Abwärme ein; die 10 % sind nicht vernichtet, sondern in Wärme umgewandelt. Ein seriöser Prüfschritt fragt deshalb bei jedem Angebot: Woher kommt die Energie, und wohin geht die Abwärme? Dass Energie nicht verloren geht, erklärt allein noch nicht, warum immer ein Teil als Abwärme „verloren“ geht, deshalb reicht die Energieerhaltung für das kalte Gehäuse nicht aus. Abwärme ist umgewandelte, keine vernichtete Energie, und auch die beste Bauweise senkt die Verluste nie auf null und ersetzt keine fehlende Quelle.","coreRule":"⚡ Energie aus dem Nichts verbietet der Erste, verlustfreie Umwandlung der Zweite Hauptsatz.","beleg":"Werkstück C.2.3 (Die unmögliche Bank; Kontext & Tiefe)","status":"entwurf","scenario":"Deine Tante will Geld in eines von zwei Start-ups stecken und bittet dich um eine Einschätzung. Firma A bietet einen Kasten an, der ohne Brennstoff, Sonnenlicht, Wind oder Netzanschluss dauerhaft 2 Kilowatt Strom liefern soll, zu 100 % effizient, sodass sein Gehäuse nie warm wird. Firma B bietet einen Generator für ein Wasserrad an einem Bach an: Er setzt 90 % der Bewegungsenergie des Wassers in Strom um, der Rest erwärmt das Gehäuse.","kurz":"A verspricht zweierlei Unmögliches: Strom ohne jede Quelle und eine Umwandlung ganz ohne Abwärme. Dass Energie erhalten bleibt, erklärt das kalte Gehäuse noch nicht; dafür braucht es den Zweiten Hauptsatz. B nennt eine Quelle und räumt Wärme ein.","prueffrage":"Welche Energiequelle nennt jede Firma, und was geschieht laut ihren Angaben mit dem Anteil, der nicht als Strom ankommt?","rueckmeldung":[{"option":0,"text":"Dass B möglich ist und A die Energieerhaltung verletzt, stimmt. A verstößt aber nicht nur dagegen: Dass Energie erhalten bleibt, heißt nicht, dass nichts als Abwärme anfällt. Ein Gehäuse, das nie warm wird, widerspricht dem Zweiten Hauptsatz."},{"option":1,"text":"Bei A stimmt der Vorwurf: Strom ohne Quelle wäre Energie aus dem Nichts. Bei B geht aber nichts verloren, denn die 10 % sind nicht vernichtet, sondern in Wärme umgewandelt. Das ist mit der Energieerhaltung vereinbar."},{"option":2,"text":"B stimmt: Das Wasser ist eine Quelle, die Abwärme ist eingeräumt. Bei A trägt die Begründung nicht: Reibungsarme Teile senken Verluste, aber nie auf null, und sie ersetzen keine fehlende Energiequelle."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ef7881a4d43c6461"}},{"id":"qx-c1-034","clusterId":"C","werkstueckRef":"C.2.3","stufe":2,"question":"Eine Freundin sagt: „Wenn ich in meinem Kamin Holz verbrenne, erzeuge ich Wärme – das ist doch Energie, die aus dem Nichts entsteht.“ Welche Antwort trifft den Denkfehler am besten?","options":["Beim Verbrennen verschwindet kein Stoff, denn aus Holz und Sauerstoff werden Asche, Rauch und Gase mit zusammen gleicher Masse.","Die Energie war schon im Holz gespeichert, denn der Baum hat per Photosynthese Sonnenlicht in chemische Energie umgewandelt.","Wärme und Temperatur sind verschiedene Dinge, denn die Temperatur sagt nur, wie heiß etwas ist, nicht wie viel Energie darin steckt.","Bei jeder Umwandlung geht nutzbare Energie in Abwärme über, denn die Entropie eines abgeschlossenen Systems nimmt nie ab."],"correctIndex":1,"explanation":"Energie kann weder erzeugt noch vernichtet werden, sie wird nur umgewandelt. Auch das Feuer erschafft nichts neu, sondern setzt chemische Energie frei, die im Holz gespeichert war; die Pflanze hat sie per Photosynthese aus Sonnenlicht gewonnen. Mehr Energie, als vorher im Holz steckte, kann deshalb beim Verbrennen nicht frei werden. Die Behauptung „Energie aus dem Nichts“ scheitert an der Frage, woher die Energie vorher kam. Die anderen Gedanken sind für sich richtig, beantworten diese Frage aber nicht: Dass kein Stoff verschwindet, betrifft die Masse und nicht die Energie. Der Unterschied zwischen Wärme und Temperatur sagt nichts über die Herkunft der Energie. Und dass bei Umwandlungen nutzbare Energie zu Abwärme wird, regelt, wie viel davon nutzbar bleibt, nicht woher sie stammt.","coreRule":"⚡ Energie entsteht nie neu – frage immer: Woher kam sie vorher?","beleg":"Werkstück C.2.3 (Schmiede-Übung „Der persönliche Energie-Audit“; Kontext & Tiefe: Erster Hauptsatz)","status":"entwurf","scenario":"","kurz":"Das Feuer erschafft keine Energie, es setzt frei, was schon im Holz steckte: chemische Energie, die der Baum aus Sonnenlicht gewonnen hat. „Aus dem Nichts“ scheitert an der Frage, woher die Energie vorher kam.","prueffrage":"Was war mit dieser Energie, bevor das Holz im Kamin lag, und wo steckte sie dann?","rueckmeldung":[{"option":0,"text":"Dass bei der Verbrennung kein Stoff verschwindet, stimmt: Die Gesamtmasse bleibt gleich. Das betrifft aber die Masse, nicht die Energie, und sagt nichts darüber, woher die Wärme kommt."},{"option":2,"text":"Wärme und Temperatur sind tatsächlich verschiedene Größen, und die Temperatur allein verrät nicht, wie viel Energie in einem Körper steckt. Wo die Wärme im Kamin herkommt, klärt das aber nicht."},{"option":3,"text":"Dass bei Umwandlungen nutzbare Energie zu Abwärme wird, trifft zu. Der Gedanke regelt jedoch, wie viel Energie nutzbar bleibt, nicht, woher sie stammt, und auf diese Herkunft zielt die Aussage der Freundin."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c66515c4c052cbe3"}},{"id":"qx-c1-035","clusterId":"C","werkstueckRef":"C.2.3","stufe":3,"question":"Welche der folgenden Aussagen sollte dich am ehesten misstrauisch machen, weil hier ein Energie-Begriff als physikalische Tatsache verkauft wird und Menschen dadurch zu einer Entscheidung gedrängt werden?","options":["„Mein Gerät liefert dauerhaft mehr Strom, als es verbraucht, aus ‚Raumenergie‘ – investier jetzt in deine Unabhängigkeit.“","„Mein neuer Kühlschrank braucht laut Energielabel weniger Energie als der alte; das kannst du am Stromzähler selbst nachmessen.“","„Nur noch heute: Wer jetzt unterschreibt, sichert sich den Rabatt – morgen gilt wieder der volle Preis, überleg nicht zu lange.“","„Meine Kollegin hat eine Energie, die den ganzen Raum mitreißt, sobald sie ein Meeting beginnt, und bringt jede Diskussion in Gang.“"],"correctIndex":0,"explanation":"Die Aussage mit dem Gerät behauptet einen physikalischen Vorgang (mehr Strom heraus als hinein) und knüpft daran eine Geldforderung. Nach dem Ersten Hauptsatz kann Energie weder erzeugt noch vernichtet werden. Ein Gerät, das mehr abgibt, als es aufnimmt, wäre eine „Bank“, die Geld aus dem Nichts druckt. Der Zweite Hauptsatz kommt noch hinzu: Kein realer Vorgang läuft ohne Verlust ab, ein Teil der nutzbaren Energie wird immer zu Abwärme. Wer für eine solche Maschine Geld verlangt, verkauft eine Metapher oder ein Wort als Physik. Das Wort „Raumenergie“ ohne Maßeinheit und ohne benannte Quelle ist zusätzlich ein Warnsignal. Prüffrage: Woher kommt die Energie, in welcher Form fließt sie, und wohin geht die Abwärme? Die anderen Aussagen sind unauffällig, weil jeweils ein Teil fehlt: Der Kühlschrank-Satz nutzt Energie als messbare Größe, lässt sich nachprüfen und drängt niemanden. Der Rabatt-Satz setzt unter Druck, behauptet aber nichts über Energie. Und die Kollegin benutzt „Energie“ erkennbar als Bild für Ausstrahlung, ohne dass jemand etwas entscheiden soll.","coreRule":"⚡ Eine Metapher ist harmlos. Gefährlich wird sie, wenn jemand sie als Physik verkauft und daran eine Forderung knüpft.","beleg":"Werkstück C.2.3 (Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Hier wird ein physikalischer Vorgang behauptet (mehr Strom heraus als hinein) und mit einer Geldforderung verknüpft. Energie kann aber weder erzeugt noch vernichtet werden, und „Raumenergie“ ohne Quelle und Maßeinheit ist ein bloßes Wort, das als Physik verkauft wird.","prueffrage":"Was müsste man messen, um jede dieser Aussagen zu überprüfen, und wer hätte einen Schaden, wenn sie falsch wäre?","rueckmeldung":[{"option":1,"text":"Hier steht Energie für eine messbare Größe: Du kannst die Angabe am Stromzähler selbst nachprüfen, und niemand verlangt eine schnelle Entscheidung von dir. Es fehlen also beide Merkmale, die misstrauisch machen sollten."},{"option":2,"text":"Befristete Rabatte setzen dich unter Zeitdruck, und das ist ein Warnsignal. Der Satz behauptet aber nichts über Energie oder Physik. Gefragt war nach der Verbindung aus Druck und einer als Tatsache verkauften Energie-Behauptung."},{"option":3,"text":"Hier ist „Energie“ erkennbar ein Bild für Ausstrahlung und Elan, niemand hält es für eine physikalische Größe. Außerdem soll niemand etwas kaufen oder entscheiden, deshalb gibt es keinen Anlass zu Misstrauen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"86c34049e4c19f64"}},{"id":"qx-c1-036","clusterId":"C","werkstueckRef":"C.2.3","stufe":4,"question":"Ein Freund schwärmt von einer „Kristall-Klangschale“, die Wasser „energetisiere“ und ihm heilende Eigenschaften verleihe. Welche Reaktion bringt ihn am ehesten dazu, die Behauptung selbst zu prüfen, ohne dass das Gespräch zum Streit wird?","options":["Du fragst nach, welche Energieform gemeint ist und woher sie kommt.","Du erklärst ihm die Gesetze der Thermodynamik und stellst klar, dass die Schale nicht funktionieren kann.","Du sagst, „energetisiertes“ Wasser lasse sich nicht beweisen oder widerlegen, und wechselst das Thema.","Du behauptest, jeder Klang erzeuge nur Wärme, und eine Schale könne Wasser deshalb nicht verändern."],"correctIndex":0,"explanation":"Wer eine Wirkung behauptet, behauptet damit einen Energiefluss: Etwas Messbares muss von der Schale auf das Wasser übergehen. Offene, neugierige Fragen wie: Welche Energieform meinst du genau, Wärme oder Schall? Woher kommt mehr Energie, als ich beim Anschlagen hineingesteckt habe? lassen den Freund die Lücke in dieser Energie-Buchhaltung selbst bemerken. Eine Belehrung oder ein Verbot (es könne gar nicht funktionieren) lädt dagegen zur Verteidigung ein. Eine Behauptung ohne Energiebilanz unkommentiert stehen zu lassen, regt nicht zum Prüfen an. Und die Aussage, jeder Klang erzeuge nur Wärme und könne Wasser deshalb nicht verändern, ist überzogen und unbelegt: Sinnvoll ist stattdessen, die behauptete Energieform konkret zu benennen und ihre Messbarkeit zu klären.","coreRule":"⚡ Frag nach der Energie-Buchhaltung: Woher kommt die Energie, in welcher Form wird sie übertragen, wohin geht der Verlust? Der andere findet die Lücke am besten selbst.","beleg":"Werkstück C.2.3 (Werkbank-Frage; Aktivierungs-Frage)","status":"entwurf","scenario":"Du sitzt mit einem Freund beim Kaffee. Er erzählt begeistert, seine Klangschale „energetisiere“ Wasser. Er hat die Schale gekauft und will dich überzeugen.","kurz":"Wer fragt, welche Energieform gemeint ist und woher sie kommt, lässt den Freund die Lücke in seiner Behauptung selbst bemerken. Eine Belehrung oder ein Verbot („kann nicht funktionieren“) lädt dagegen zur Verteidigung ein.","prueffrage":"Was hat dein Freund in die Schale investiert, und wie dürfte er reagieren, wenn ihm jemand sagt, sie könne gar nicht wirken?","rueckmeldung":[{"option":1,"text":"Eine Energiebilanz ist das richtige Kriterium, um die Behauptung zu prüfen. Als Vortrag mit dem fertigen Urteil „kann nicht funktionieren“ lädt dieses Wissen den Freund aber zur Verteidigung ein, statt ihn selbst nachdenken zu lassen."},{"option":2,"text":"Ein Themenwechsel vermeidet zwar den Streit, aber auch das Prüfen. Die Behauptung ist durchaus prüfbar, sobald die behauptete Energieform benannt ist; unkommentiert stehen gelassen, regt sie niemanden zum Nachdenken an."},{"option":3,"text":"Skepsis ist berechtigt, und beim Anschlagen entsteht auch etwas Wärme. „Jeder Klang erzeugt nur Wärme“ ist aber überzogen und unbelegt; eine solche Gegenbehauptung lässt sich so leicht zurückweisen wie die Behauptung des Freundes."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"258761af65aef570"}},{"id":"qx-c1-037","clusterId":"C","werkstueckRef":"C.3.1","stufe":1,"question":"Was erwartest du in dieser Zelle, und mit welcher Begründung?","options":["Das Protein entsteht nicht: Die gesamte DNA müsste als Ganzes zu den Ribosomen wandern, um dort abgelesen zu werden, und genau dieser Weg ist hier versperrt.","Das Protein entsteht nicht: Das Gen wird im Kern zwar in eine RNA-Kopie umgeschrieben, doch diese Kopie erreicht die Ribosomen nicht, an denen die Kette entsteht.","Das Protein entsteht trotzdem: Die DNA wird im Kern direkt in eine Aminosäurekette übersetzt, die sich dort faltet; die Ribosomen draußen braucht es dafür nicht.","Das Protein entsteht trotzdem: Die Ribosomen setzen die passende Kette auch ohne Vorlage aus dem Kern aus vorhandenen Aminosäuren zusammen, sobald die Zelle sie braucht."],"correctIndex":1,"explanation":"Die DNA ist der robuste Informationsspeicher im Zellkern und dient als Master-Blaupause. Für ein bestimmtes Protein wird nur der passende Gen-Abschnitt in eine mobile Arbeitskopie (RNA) umgeschrieben; das nennt man Transkription. Diese Kopie verlässt normalerweise den Zellkern, wird an den Ribosomen gelesen und in eine Kette von Aminosäuren übersetzt, die sich zum funktionierenden Protein faltet (Translation). Im Gedankenexperiment kann die Transkription im Kern also noch stattfinden, aber die RNA-Kopie bleibt eingesperrt, und den Ribosomen fehlt die Vorlage: Das Protein entsteht nicht. Die Mitschülerin übersieht, dass die vollständige Anleitung in der DNA nichts nützt, weil die DNA den Kern nie verlässt und die Information nur über die RNA-Kopie zu den Ribosomen gelangt; zudem verwechselt sie Gen und gesamtes Erbgut, denn ein Gen ist nur ein Abschnitt der DNA. Dass das Protein ausbleibt, weil die ganze DNA nicht hinauskommt, trifft zwar das Ergebnis, aber die DNA wandert ohnehin nie zu den Ribosomen. Die Übersetzung in Aminosäuren findet nicht im Zellkern statt, sondern an den Ribosomen, und die Ribosomen bauen keine passende Kette ohne RNA-Vorlage.","coreRule":"⚡ DNA ist die Blaupause, RNA die Arbeitskopie, das Protein das fertige Bauteil: Die Information fließt vom Gen über die RNA zum Protein, nie wird dafür das Original verschickt.","beleg":"Werkstück C.3.1 (Kontext & Tiefe, „Vom Gen zum Protein“; Kernidee)","status":"entwurf","scenario":"Im Biologiekurs stellt die Lehrerin ein Gedankenexperiment: Eine Zelle soll ein bestimmtes Protein herstellen. Ein gedachter Stoff verhindert, dass irgendetwas aus dem Zellkern hinausgelangt; die DNA im Kern und die Ribosomen außerhalb des Kerns bleiben unversehrt. Eine Mitschülerin meint: „Kein Problem, die Bauanleitung steht ja vollständig in der DNA.“","quote":"","quoteLabel":"","kurz":"Im Kern entsteht zwar eine RNA-Kopie des Gens, sie kommt aber nicht zu den Ribosomen, und nur über sie gelangt die Information dorthin. Dass die Anleitung vollständig in der DNA steht, nützt nichts, solange die DNA den Kern nie verlässt.","prueffrage":"Welche Form der Information könnte den Kern überhaupt verlassen, und was davon liegt außerhalb bei den Ribosomen vor?","rueckmeldung":[{"option":0,"text":"Das Ergebnis stimmt: Das Protein entsteht nicht. Die Begründung nicht: Die gesamte DNA wandert ohnehin nie zu den Ribosomen, sondern nur die RNA-Kopie eines einzelnen Gens."},{"option":2,"text":"Es liegt nahe, die Übersetzung dorthin zu legen, wo die Information steckt. Die DNA wird aber nicht direkt in Aminosäuren übersetzt; das geschieht an den Ribosomen außerhalb des Kerns."},{"option":3,"text":"Ribosomen verknüpfen zwar Aminosäuren zu Ketten, aber nur nach einer RNA-Vorlage. Ohne diese Kopie aus dem Kern wissen sie nicht, welche Kette sie bauen sollen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „Transcription and Translation Lesson Plan“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/teaching-tools/transcription-translation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9df886710986d375"}},{"id":"qx-c1-038","clusterId":"C","werkstueckRef":"C.3.1","stufe":2,"question":"Wie sollte er die Folie am besten überarbeiten?","options":["Die Bananen-Zahl umformulieren, weil die Quelle von Gegenstücken einzelner Gene spricht, nicht von halber Sequenzgleichheit, und den Schimpansen auf rund 99 % korrigieren.","Die Bananen-Zahl stehen lassen, weil viele Gene mit Gegenstück eine etwa hälftige Sequenzgleichheit ergeben, und nur den Schimpansen auf rund 99 % korrigieren.","Die Bananen-Zahl umformulieren, weil die Quelle von Gegenstücken einzelner Gene spricht, und die Schimpansen-Hälfte stehen lassen, weil auch sie nur Gene zählt.","Beide Zahlen stehen lassen, weil die DNA aller Lebewesen aus denselben vier Basen besteht und eine hälftige Übereinstimmung deshalb überall zu erwarten ist."],"correctIndex":0,"explanation":"Die „50 % Banane“ vermischen zwei verschiedene Dinge: Dass viele unserer Gene ein Gegenstück in der Banane haben, ist plausibel, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt aber nicht, dass die DNA-Sequenz zur Hälfte übereinstimmt. Wo sich das Erbgut von Mensch und Schimpanse vergleichen lässt, stimmt es zu rund 99 % überein (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437): etwa 1,2 % Unterschied bei einzelnen Basen, einige Prozent, wenn Einfügungen und Verluste mitzählen. Die Folie wirft also Genverwandtschaft und Sequenzübereinstimmung durcheinander, und ihre Aussage zum Schimpansen widerspricht schon der eigenen Quelle; beides muss korrigiert werden. Viele Gene mit Gegenstück ergeben noch keine bestimmte Sequenzgleichheit, deshalb trägt die Bananen-Zahl nicht. Die Schimpansen-Hälfte lässt sich nicht als Genzählung retten, weil die Quelle ausdrücklich rund 99 % Sequenzübereinstimmung nennt, und dieselben vier Basen sagen nichts darüber, wie ähnlich die Abfolge ist.","coreRule":"⚡ Gemeinsame Gene heißen nicht gleiche Sequenzen: Verwandtschaft ist etwas anderes als Prozentzahlen aus dem Netz. Prüfe, was genau verglichen wurde, bevor du eine Zahl glaubst.","beleg":"Werkstück C.3.1 (Schmiede-Übung „Der Code-Vergleich“); Fn. gl-c-schimpanse (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437, S. 69–87)","status":"entwurf","kurz":"Dass viele Gene ein Gegenstück in der Banane haben, ist etwas anderes als halbe Sequenzgleichheit. Und die Schimpansen-Hälfte widerspricht der eigenen Quelle mit rund 99 %. Beide Zahlen brauchen eine Korrektur.","prueffrage":"Was genau wird bei der Banane gezählt und was beim Schimpansen: ganze Gene oder die Abfolge der Basen?","rueckmeldung":[{"option":1,"text":"Beim Schimpansen stimmt die Korrektur auf rund 99 %. Viele Gene mit Gegenstück sagen aber nichts darüber, wie ähnlich die Basenabfolge ist, eine hälftige Sequenzgleichheit lässt sich daraus nicht ableiten."},{"option":2,"text":"Die Bananen-Zahl richtig zu verstehen, ist der halbe Weg. Die Schimpansen-Hälfte hält als Genzählung aber nicht, denn die Quelle nennt ausdrücklich rund 99 % Übereinstimmung der Sequenzen."},{"option":3,"text":"Dass alle Lebewesen dieselben vier Basen nutzen, stimmt. Es sagt aber nichts darüber, wie ähnlich ihre Abfolge ist, und es macht die Schimpansen-Zahl nicht richtig, die der eigenen Quelle widerspricht."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Smithsonian National Museum of Natural History, Human Origins: „Genetics“","oeffentlich":true,"url":"https://humanorigins.si.edu/evidence/genetics","abruf":"2026-10-12"},{"typ":"doi","kurz":"The Chimpanzee Sequencing and Analysis Consortium (2005): „Initial sequence of the chimpanzee genome and comparison with the human genome“, Nature 437, 69–87 (Landkarte [^gl-c-schimpanse], im Belegregister bestätigt; Volltext nur mit Abo)","oeffentlich":false,"doi":"10.1038/nature04072"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"133fb252986dd33e"},"scenario":"Ein Freund zeigt dir eine Folie aus seinem Referat: „Wir teilen 50 % unserer DNA mit der Banane. Kein Wunder: Mit dem Schimpansen ist es ja auch nur etwa die Hälfte.“ In seinen eigenen Quellen steht: Viele Gene des Menschen haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Und: Wo sich das Erbgut von Mensch und Schimpanse vergleichen lässt, stimmen die Sequenzen zu rund 99 % überein."},{"id":"qx-c1-039","clusterId":"C","werkstueckRef":"C.3.1","stufe":3,"question":"Ein Coach verspricht: „Mit positiven Gedanken reprogrammierst du deine DNA – das beweist die Epigenetik.“ Welche Einordnung hält der Prüfung stand?","options":["Der Satz kehrt die Beweislast um: Der Coach fordert Zweifler auf, zu widerlegen, dass positive Gedanken die DNA umprogrammieren, statt den Mechanismus selbst zu belegen.","Der Satz begründet im Kreis: Dass positive Gedanken die DNA umprogrammieren, soll die Epigenetik beweisen, und dass die Epigenetik das beweist, wird nur mit dieser Umprogrammierung gestützt.","Der Satz verallgemeinert Einzelfälle: Aus Berichten einzelner Klienten, denen positives Denken geholfen hat, wird gefolgert, dass es bei jedem die DNA umprogrammiert, ohne Vergleichsgruppe.","Der Satz vermengt zwei Ebenen: Die Aktivität von Genen lässt sich beeinflussen, die Buchstabenfolge der DNA aber nicht durch bloße Absicht; die Epigenetik wird hier als „Beweis“ missbraucht."],"correctIndex":3,"explanation":"Der Satz des Coachs vermischt zwei verschiedene Dinge. Die Aktivität von Genen kann beeinflusst werden, das ist das Feld der Epigenetik. Die DNA dagegen ist ein bemerkenswert stabiles Molekül, und ihre Buchstabenfolge lässt sich nicht durch bloße Absicht verändern. Wer „DNA umprogrammieren“ verspricht, muss einen konkreten, experimentell belegten Mechanismus nennen, der die Sequenz verändert; ein Wort wie „Epigenetik“ ersetzt diesen Beleg nicht. Die Umkehr der Beweislast klingt naheliegend, doch der Coach fordert von niemandem, das Gegenteil zu widerlegen, er behauptet selbst, die Epigenetik beweise es. Ein Zirkelschluss wäre es, wenn die Epigenetik nur mit der Wirkung der Gedanken begründet würde, der Satz begründet aber nichts im Kreis. Eine Verallgemeinerung setzt Berichte einzelner Klienten voraus, von denen im Satz keine Rede ist.","coreRule":"⚡ Gene lassen sich steuern, die Buchstabenfolge nicht – wer „DNA umschreiben“ verspricht, braucht einen Mechanismus.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „In der Pseudomedizin“; Verbindungen; Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Epigenetik betrifft die Aktivität von Genen, nicht die Buchstabenfolge der DNA, und die ändert sich nicht durch bloße Absicht. Das Fachwort ersetzt keinen belegten Mechanismus, der die Sequenz tatsächlich verändert.","prueffrage":"Welcher konkrete, experimentell belegte Vorgang soll hier laut Coach etwas Bestimmtes in der Zelle verändern?","rueckmeldung":[{"option":0,"text":"Fehlende Belege fallen hier tatsächlich auf. Der Coach verlangt aber von niemandem, das Gegenteil zu widerlegen, sondern beruft sich selbst auf die Epigenetik. Das Problem liegt im Fachwort, das einen Beleg nur vortäuscht."},{"option":1,"text":"Ein Fachbegriff, der nur als Etikett dient, wirkt schnell wie ein Kreis aus Behauptung und Beweis. Im Satz stützt sich die Aussage aber auf die Epigenetik und nicht auf sich selbst. Falsch ist, dass dieses Gebiet etwas ganz anderes meint."},{"option":2,"text":"Bei Wirkversprechen steckt oft ein Schluss von Einzelfällen dahinter, und eine Vergleichsgruppe fehlt dann tatsächlich. Im Satz kommen aber gar keine Klientenberichte vor. Er verspricht eine Wirkung auf die DNA, ohne Fälle anzuführen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „Epigenomics Fact Sheet“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/fact-sheets/Epigenomics-Fact-Sheet","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"17bc36209798cbd0"}},{"id":"qx-c1-040","clusterId":"C","werkstueckRef":"C.3.1","stufe":4,"question":"Jemand sagt: „Gentechnisch veränderter Mais ist pures Gift, weil er ‚unnatürliche Gene‘ enthält.“ Welche Antwort widerlegt das Argument am besten?","options":["Das ist ein Zirkelschluss: Der Mais soll giftig sein, weil seine Gene unnatürlich sind, und die Gene sollen unnatürlich sein, weil sie den Mais giftig machen; ein unabhängiger Beleg fehlt.","Das ist eine Verallgemeinerung aus Einzelfällen: Weil bei einzelnen gentechnisch veränderten Pflanzen Bedenken aufkamen, wird jede Maissorte mit eingefügten Genen als pures Gift hingestellt, ohne sie zu prüfen.","Das ist ein Natürlichkeitsfehlschluss: Auch Züchtung verändert seit Jahrtausenden das Erbgut, nur zufällig; ob eine Pflanze sicher ist, zeigt ihr Ergebnis, nicht die Herkunft der Veränderung.","Das ist ein Fehlschluss aus Nichtwissen: Weil niemand die Unschädlichkeit des Mais bewiesen hat, wird er für pures Gift erklärt, und Skeptiker sollen das Gegenteil beweisen."],"correctIndex":2,"explanation":"Das Argument setzt „unnatürlich“ mit „giftig“ gleich, doch Herkunft oder Methode allein sagen nichts über Giftigkeit. Auch klassische Züchtung verändert seit etwa 10.000 Jahren das Erbgut, nur langsamer, zufälliger und unpräziser; Gentechnik wie CRISPR kann dagegen gezielt einzelne Gene verändern. Entscheidend für die Sicherheit ist das neue Merkmal der Pflanze, etwa ob sie ein Gift oder Allergen bildet, und genau das lässt sich prüfen. Ein Zirkelschluss wirkt naheliegend, weil „unnatürlich“ und „giftig“ so eng verknüpft werden, doch es wird nur in einer Richtung begründet. Die Verallgemeinerung klingt plausibel, weil es Bedenken gegen einzelne Pflanzen gab, im Argument wird aber gar kein Einzelfall genannt. Ein Fehlschluss aus Nichtwissen ist ein häufiges Streitmuster, doch der Sprecher beruft sich auf die Herkunft der Gene, nicht darauf, dass etwas unbewiesen sei.","coreRule":"⚡ Bewerte das Ergebnis, nicht die Methode: „Natürlich“ ist kein Sicherheitsurteil.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „Bei genetisch veränderten Organismen“; Werkbank-Frage; Red Flags)","status":"entwurf","kurz":"„Unnatürlich“ ist kein Maßstab für Giftigkeit: Auch Züchtung verändert das Erbgut seit Jahrtausenden, nur zufälliger. Ob Mais schadet, hängt vom neuen Merkmal ab, etwa einem Gift oder Allergen, und das lässt sich prüfen. Der Fehler: Herkunft mit Wirkung gleichzusetzen.","prueffrage":"Wie sah die Wildpflanze aus, von der unser heutiger Mais abstammt, und wie wurde daraus die Pflanze auf dem Feld?","rueckmeldung":[{"option":0,"text":"Die enge Verknüpfung von „unnatürlich“ und „giftig“ erweckt den Eindruck eines Kreises. Begründet wird aber nur in einer Richtung: giftig, weil unnatürlich. Die Gene gelten nicht als unnatürlich, weil sie giftig machen."},{"option":1,"text":"Dass es Bedenken gegen einzelne Pflanzen gab, macht die Deutung plausibel. Im Satz wird aber gar kein Einzelfall genannt: Er stützt sich allein auf die angeblich unnatürliche Herkunft der Gene."},{"option":3,"text":"Das Muster, Unbewiesenes als falsch oder gefährlich hinzustellen, ist in Debatten verbreitet. Hier wird aber nicht mit fehlendem Beweis argumentiert, sondern mit der Herkunft der Gene als vermeintlichem Grund für Giftigkeit."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"National Academies of Sciences, Engineering, and Medicine (2016): „Genetically Engineered Crops: Experiences and Prospects – New Report“ (Pressemitteilung)","oeffentlich":true,"url":"https://www.nationalacademies.org/news/2016/05/genetically-engineered-crops-experiences-and-prospects-new-report","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"89066b82dbf399de"}},{"id":"qx-c1-041","clusterId":"C","werkstueckRef":"C.3.3","stufe":1,"question":"In einer Diskussion sagt jemand: „Wenn der Mensch vom Affen abstammt, warum gibt es dann noch Affen? Also kann die Abstammung nicht stimmen.“ Was ist an diesem Schluss fehlerhaft?","options":["Er setzt voraus, dass eine Art nach der Entstehung einer neuen Art verschwinden muss; zwei Linien können aber aus einem gemeinsamen Vorfahren hervorgehen und nebeneinander weiterbestehen.","Er greift die Forscher an, die den Menschen mit Affen verwandt sehen, statt ihre Belege zu prüfen; der Wert eines Arguments hängt aber nicht davon ab, wer es vorbringt.","Er verweist auf eine Lücke im Fossilbericht: Weil kein Fund den Übergang vom Affen zum Menschen lückenlos zeigt, soll die Abstammung falsch sein; fehlende Belege widerlegen sie aber nicht.","Er argumentiert im Kreis: Die Abstammung soll falsch sein, weil es noch Affen gibt, und dass es noch Affen gibt, wird nur mit der angeblichen Falschheit der Abstammung gestützt."],"correctIndex":0,"explanation":"Der Schluss setzt stillschweigend voraus, dass eine Stammart verschwinden muss, sobald sich aus ihr eine andere Art entwickelt hat. Das ist nicht der Fall: Zwei Linien können sich von einem gemeinsamen Vorfahren aus getrennt weiterentwickeln, so wie du und dein Cousin beide von einem gemeinsamen Großvater abstammen. Dass dein Cousin noch lebt, widerlegt die Verwandtschaft nicht, und dass es heute noch Affen gibt, widerlegt die gemeinsame Abstammung ebenso wenig.","coreRule":"⚡ Wir stammen nicht von heutigen Affen ab, sondern teilen mit ihnen gemeinsame Vorfahren.","beleg":"Werkstück C.3.3 (Red Flags)","status":"entwurf","scenario":"","kurz":"Der Schluss unterstellt, dass eine Stammart verschwinden muss, sobald sich aus ihr eine neue entwickelt. Zwei Linien können aber aus einem gemeinsamen Vorfahren hervorgehen und beide weiterbestehen, so wie Cousins einen gemeinsamen Großvater haben.","prueffrage":"Leben heute verwandte Affenarten wie Schimpanse und Bonobo nebeneinander, und musste dafür eine die andere ablösen?","rueckmeldung":[{"option":1,"text":"Bei Streitgesprächen liegt der Verdacht auf einen persönlichen Angriff nahe. Hier greift aber niemand die Forscher an; es wird ein sachlicher Einwand vorgebracht, dessen Voraussetzung nicht trägt."},{"option":2,"text":"Fossillücken sind ein häufiges Argument gegen die Abstammung, und fehlende Belege widerlegen sie nicht. Die Person beruft sich hier aber gar nicht auf Funde, sondern allein darauf, dass es noch Affen gibt."},{"option":3,"text":"Ein Zirkelschluss setzt das Ergebnis schon in der Begründung voraus. Hier wird die Falschheit der Abstammung aus der Beobachtung heutiger Affen abgeleitet, nicht aus sich selbst. Der Fehler steckt in der versteckten Annahme, die Stammart müsse verschwinden."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Smithsonian National Museum of Natural History, Human Origins: „Genetics“","oeffentlich":true,"url":"https://humanorigins.si.edu/evidence/genetics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"80b7c772871d4aa8"}},{"id":"qx-c1-042","clusterId":"C","werkstueckRef":"C.3.3","stufe":2,"question":"Welche Erklärung trägt die Beobachtung am besten, dass nach massenhaftem Antibiotika-Einsatz fast nur noch resistente Keime übrig sind?","options":["Das Mittel tötet die empfindlichen Keime auf der Station, die wenigen zufällig resistenten überleben und vermehren sich, bis sie fast alle Keime stellen, die dort noch zu finden sind.","Die einzelnen Keime auf der Station haben sich über die Jahre an das Mittel gewöhnt und geben diese erworbene Unempfindlichkeit an ihre Nachkommen weiter, bis fast alle unempfindlich sind.","Durch reinen Zufall (Gendrift) sind auf der Station einzelne Varianten häufiger geworden, unabhängig vom Mittel, und es waren zufällig gerade die resistenten, bis fast nur noch sie übrig waren.","Eine kleine Gruppe resistenter Keime hat die Station zuerst besiedelt, und alle späteren Keime stammen von ihr ab; mit dem Einsatz des Mittels hat das nichts zu tun."],"correctIndex":0,"explanation":"Die Beobachtung lässt sich ohne Absicht und ohne „Lernen“ der Bakterien erklären: Zufällige Veränderungen im Erbgut entstehen ungerichtet, etwa durch Kopierfehler. Wo viel Antibiotikum eingesetzt wird, sterben die empfindlichen Keime, die wenigen zufällig resistenten überleben und vermehren sich, bis sie die Mehrheit stellen. Der Einsatz erzeugt also einen hohen Selektionsdruck, er verändert die Bakterien nicht gezielt. Die Variation ist zufällig, die Auswahl ist es nicht. Dieselbe Logik erklärt, warum schnell evolvierende Grippeviren jedes Jahr einen neuen Impfstoff nötig machen.","coreRule":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert, was zufällig schon resistent war.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Missverständnisse in der Medizin“; Kipppunkt)","status":"entwurf","scenario":"In einer Klinik wird beobachtet: Nach Jahren intensiven Antibiotika-Einsatzes sind die meisten Keime auf der Station gegen das Mittel resistent. Ein Kollege sagt: „Die Bakterien haben sich eben an das Medikament gewöhnt und angepasst.“ Du sollst beurteilen, welche Erklärung die Beobachtung am besten trägt.","kernregel":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert die zufällig resistenten Bakterien.","kurz":"Zufällige Veränderungen im Erbgut machen einzelne Keime resistent. Das Mittel tötet die empfindlichen, die resistenten vermehren sich. Der Denkfehler ist, die Anpassung für ein Gewöhnen der Keime zu halten, obwohl das Mittel nur auswählt, was schon vorhanden war.","prueffrage":"Gab es in der Bakterienmenge schon vor der Behandlung Unterschiede, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"„Gewöhnung“ klingt anschaulich, weil am Ende tatsächlich fast alle Keime unempfindlich sind. Erworbene Unempfindlichkeit wird aber nicht vererbt, und der Gedanke erklärt nicht, warum die empfindlichen Keime von der Station verschwunden sind."},{"option":2,"text":"Zufällige Verschiebungen der Häufigkeit gibt es wirklich. Sie hängen aber nicht vom Mittel ab und würden nicht ausgerechnet nach massivem Einsatz die Resistenten begünstigen. Der Zusammenhang mit dem Einsatz bliebe so unerklärt."},{"option":3,"text":"Eine frühe Besiedlung durch resistente Keime wäre denkbar. Davon steht im Szenario aber nichts, und die Erklärung bliebe die Antwort schuldig, warum die Resistenz nach Jahren intensiven Einsatzes so verbreitet ist."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte b1, a6)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b1ff07358039a4b5"}},{"id":"qx-c1-043","clusterId":"C","werkstueckRef":"C.3.3","stufe":3,"question":"Welche Antwort an den Influencer trifft seine Behauptung am besten?","options":["Deine Annahme stimmt: Zehntausend Jahre sind zu kurz für Veränderung, also muss die Milchverdauung Erwachsener schon in der Steinzeit verbreitet gewesen sein.","Deine Annahme stimmt nicht: Die Milchverdauung Erwachsener hat sich erst seit der Steinzeit ausgebreitet, die Evolution ging also weiter, ein fertiges Ideal gibt es nicht.","Deine Annahme stimmt, mit einer Ausnahme: Die Milchverdauung Erwachsener breitete sich rein zufällig aus, ohne dass die Ernährung der Menschen dabei eine Rolle spielte.","Deine Annahme stimmt nicht: Die Milchverdauung Erwachsener zeigt, dass wir heute perfekt an unsere Kost angepasst sind, also ist die heutige Ernährung das Ideal."],"correctIndex":1,"explanation":"Die Behauptung unterstellt, die Anpassung sei vor langer Zeit abgeschlossen worden und es gebe einen „natürlichen“ Idealzustand. Das ist doppelt falsch. Erstens hat die Evolution nicht aufgehört: In Populationen, deren Vorfahren Milch nutzten, hat sich die Fähigkeit ausgebreitet, auch als Erwachsene Milchzucker zu verdauen. Das ist eines der am stärksten selektierten Merkmale der letzten 10.000 Jahre. Die Selektion hängt mit dem Milchkonsum zusammen, dessen Stärke allein erklärt die Ausbreitung aber nicht; als zusätzliche Treiber werden Hungersnöte und Krankheiten vermutet. Zweitens ist Evolution nicht auf Perfektion ausgelegt, sondern auf „gut genug“ in der jeweiligen Umgebung. Es gibt deshalb nicht „den einen“ Zustand, an den wir perfekt angepasst sind, weder den steinzeitlichen noch den heutigen. Dass zehntausend Jahre zu kurz seien, widerlegt der Artikel selbst, denn die Ausbreitung fällt genau in diese Zeit. Rein zufällig war sie nicht, weil sie dort auftrat, wo Menschen Milch nutzten: Die Variation ist zufällig, die Auswahl durch die Umwelt nicht. Und wer daraus eine heutige perfekte Anpassung ableitet, ersetzt nur das alte Ideal durch ein neues.","coreRule":"⚡ Evolution ist nie fertig, und einen „natürlichen“ Idealzustand, an den wir perfekt angepasst wären, gibt es nicht.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen den Appell an die Natur in seiner ‚Paläo‘-Form“); Fn. gl-c-laktase (Evershed u. a. 2022, Nature 608, S. 336–345)","status":"entwurf","kurz":"Die Evolution ging nach der Steinzeit weiter: Die Milchverdauung Erwachsener breitete sich in den letzten 10.000 Jahren stark aus. Wer von einer abgeschlossenen Anpassung an ein „natürliches“ Ideal ausgeht, übersieht, dass Evolution auf „gut genug“ zielt.","prueffrage":"Wann in der Geschichte der Menschheit trat das Merkmal laut dem Fachartikel auf, und passt dieser Zeitraum zu der Behauptung?","rueckmeldung":[{"option":0,"text":"Die Annahme, zehntausend Jahre seien zu kurz, steckt in der Behauptung des Influencers, belegt ist sie nicht. Der Artikel widerlegt sie: Die Ausbreitung der Milchverdauung Erwachsener fällt genau in diese Zeit, das Merkmal war also nicht schon in der Steinzeit verbreitet."},{"option":2,"text":"Das Entstehen neuer Varianten ist tatsächlich zufällig, ihre Ausbreitung aber nicht. Sie trat dort auf, wo Menschen Milch nutzten, und wurde von der Umwelt begünstigt. Der Milchkonsum erklärt sie zwar nicht allein, aber „ohne Rolle der Ernährung“ trifft nicht zu."},{"option":3,"text":"Dass die Annahme des Influencers nicht stimmt, ist richtig. Der Schluss auf eine heutige perfekte Anpassung ersetzt aber nur das alte Ideal durch ein neues: Evolution zielt auf „gut genug“ in der jeweiligen Umgebung, nicht auf Perfektion, weder gestern noch heute."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Evershed, R. P. u. a. (2022): „Dairying, diseases and the evolution of lactase persistence in Europe“, Nature 608, 336–345 (frei in PMC7615474)","oeffentlich":true,"doi":"10.1038/s41586-022-05010-7","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7615474/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a8, b7)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ba091711a659edb6"},"scenario":"Ein Ernährungs-Influencer schreibt: „Unsere Körper sind seit der Steinzeit unverändert und genau an die damalige Kost angepasst. Iss deshalb wie unsere Vorfahren vor 10.000 Jahren.“ Du kennst einen Fachartikel, nach dem sich in Bevölkerungen, deren Vorfahren Milch nutzten, die Fähigkeit Erwachsener, Milchzucker zu verdauen, in den letzten 10.000 Jahren stark ausgebreitet hat."},{"id":"qx-c1-044","clusterId":"C","werkstueckRef":"C.3.3","stufe":4,"question":"Wie ist dieses Argument zu bewerten?","options":["Es ist stichhaltig: Bei so hoher Komplexität können Mutation und Selektion grundsätzlich nichts mehr erklären.","Es schließt von „ich kann mir keinen schrittweisen Weg vorstellen“ auf „es gab keinen“; komplexe Strukturen können schrittweise entstanden sein.","Es ist erst widerlegt, wenn jeder einzelne Zwischenschritt des Organs im Fossilbericht lückenlos belegt ist.","Es zeigt zu Recht, dass Zufall allein so etwas nicht hervorbringt; deshalb braucht es einen Plan."],"correctIndex":1,"explanation":"Das Argument schließt von der eigenen Ratlosigkeit auf die Wirklichkeit: Weil sich der Redner keinen schrittweisen Weg vorstellen kann, soll es keinen gegeben haben. Das ist ein Fehlschluss aus persönlichem Unglauben. Dass ein Organ heute ohne ein Teil nicht mehr funktioniert, sagt nichts über seine Entstehung: Komplexe Strukturen konnten schrittweise entstehen. Proto-Flügel dienten etwa vielleicht erst der Isolierung oder Balz, bevor sie beim Gleiten nützlich wurden. Außerdem ist Evolution kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Auch muss nicht jeder Zwischenschritt lückenlos fossil belegt sein: Der Fossilienbestand ist naturgemäß lückenhaft.","coreRule":"⚡ „Das kann ich mir nicht vorstellen“ ist kein Argument gegen eine Erklärung, sondern eine Aussage über die eigene Vorstellungskraft.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Kreationismus & ‚Intelligent Design‘“; Red Flags)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"7c6d328b4853f9ac","vermerk":"Prüfpult"},"scenario":"Ein Redner behauptet: „Dieses Organ ist ‚irreduzibel komplex‘: Nimmt man ein einziges Teil weg, funktioniert es nicht mehr. Also muss ein Designer es geschaffen haben.“","kurz":"Aus „ich kann mir keinen schrittweisen Weg vorstellen“ folgt nicht, dass es keinen gab. Dass heute kein Teil fehlen darf, sagt nichts über die Entstehung: Teile konnten früher andere Aufgaben erfüllen.","prueffrage":"Was wurde an dem Organ tatsächlich beobachtet, und was davon sagt etwas über seine Entstehung?","rueckmeldung":[{"option":0,"text":"Hohe Komplexität wirkt, als überfordere sie jeden schrittweisen Prozess. Doch Selektion wählt nicht-zufällig aus, und Teile können früher anderen Zwecken gedient haben. Aus fehlender Vorstellung folgt kein „grundsätzlich unmöglich“."},{"option":2,"text":"Lückenlose Belege wären schön, sind aber keine Bedingung: Der Fossilienbestand ist naturgemäß lückenhaft. Entscheidend ist, dass das Argument selbst nicht trägt, weil es aus Unvorstellbarkeit auf Unmöglichkeit schließt."},{"option":3,"text":"Reiner Zufall würde komplexe Strukturen tatsächlich nicht hervorbringen. Evolution ist aber kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Daraus, dass „Zufall allein“ nicht reicht, folgt daher noch kein Plan."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a2, e4)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7c6d328b4853f9ac"}},{"id":"qx-c1-045","clusterId":"C","werkstueckRef":"C.3.4","stufe":1,"question":"Eine Bekannte erzählt begeistert: „Im Wald hinter dem Dorf lebt ein einzelnes, riesiges Tier, das noch nie jemand eingefangen hat. Es ist vermutlich schon seit Jahrhunderten dort.“ Welcher Einwand trifft den Kern des Problems am besten?","options":["Über Jahrhunderte hält sich in der Regel nur eine Population, kein Einzeltier, und kleine Gruppen sterben durch Inzucht, Krankheiten oder eine Katastrophe leicht aus.","Die Bekannte beruft sich auf Leute aus dem Dorf, die das Tier gesehen haben wollen; doch Zeugenberichte ohne Foto oder Spuren ersetzen keinen Beleg und tragen die Behauptung nicht.","Die Bekannte schließt von diesem einen Wald hinter dem Dorf auf alle Wälder der Gegend und verallgemeinert voreilig; ein einzelner Wald begründet aber noch keine Regel.","Die Bekannte lässt nur die Wahl zwischen einem riesigen Tier und einem Märchen und blendet jede dritte Möglichkeit aus, etwa eine Verwechslung; das ist ein falsches Dilemma."],"correctIndex":0,"explanation":"Die Behauptung verwechselt ein einzelnes Tier mit einer Art. Damit etwas über Jahrhunderte besteht, braucht es eine Population, die sich fortpflanzt. Sehr kleine Gruppen sind stark gefährdet: Inzucht und Gendefekte schwächen den Nachwuchs, Krankheiten und zufällige Ereignisse wie ein Waldbrand können alle auf einmal treffen. Für große Säugetiere schätzen Wissenschaftler die minimal überlebensfähige Population auf mehrere hundert bis einige tausend Individuen, die miteinander in Kontakt stehen (Frankham, Bradshaw und Brook 2014; Jamieson und Allendorf 2012). Die genauen Zahlen schwanken je nach Studie, die Größenordnung bleibt aber gleich: weit mehr als ein Pärchen. Wer von „einem Tier“ spricht, muss also die ganze Population mitdenken, samt Nahrungsbedarf, Spuren und Kadavern.","coreRule":"⚡ Wer von „einem Monster“ spricht, muss von einer ganzen Population sprechen.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Die minimal überlebensfähige Population“); Fn. gl-c-mvp (Frankham/Bradshaw/Brook 2014, S. 61; Jamieson/Allendorf 2012, S. 582 f.)","status":"entwurf","scenario":"","kurz":"Über Jahrhunderte besteht nur eine fortpflanzungsfähige Population, nie ein Einzeltier. Der Denkfehler liegt darin, ein einzelnes Tier mit einer Art zu verwechseln: Kleine Gruppen sterben durch Inzucht, Krankheit oder Zufall leicht aus.","prueffrage":"Wie alt werden große Waldtiere wie Bären oder Elche höchstens, und wie oft passt das in einige Jahrhunderte?","rueckmeldung":[{"option":1,"text":"Zeugenberichte ohne Foto oder Spuren wären tatsächlich dünn. In der Erzählung kommen aber gar keine Zeugen vor, die Bekannte berichtet nur. Der Einwand geht deshalb am Kern vorbei: Ein Einzeltier kann Jahrhunderte nicht überdauern."},{"option":2,"text":"Voreilige Verallgemeinerung ist ein echter Denkfehler, nur steckt er hier nicht drin: Die Bekannte spricht ausdrücklich von diesem einen Wald und schließt nicht auf andere. Der Einwand unterstellt einen Schluss, der gar nicht gezogen wird."},{"option":3,"text":"Ein falsches Dilemma setzt voraus, dass nur zwei Möglichkeiten zugelassen werden. Die Bekannte stellt aber keine Wahl zwischen Riesentier und Märchen auf, sie behauptet ein Einzeltier. Das Problem liegt in dieser Behauptung selbst."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size: A meta-analysis of 30 years of published estimates“, Biological Conservation 139, 159–166, doi:10.1016/j.biocon.2007.06.011 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Frankham, R.; Bradshaw, C. J. A.; Brook, B. W. (2014): „Genetics in conservation management: Revised recommendations for the 50/500 rules …“, Biological Conservation 170, 56–63 (Landkarte [^gl-c-mvp])","oeffentlich":false,"doi":"10.1016/j.biocon.2013.12.036","seite":"61"},{"typ":"doi","kurz":"Jamieson, I. G.; Allendorf, F. W. (2012): „How does the 50/500 rule apply to MVPs?“, Trends in Ecology & Evolution 27(10), 578–584 (Landkarte [^gl-c-mvp])","oeffentlich":false,"doi":"10.1016/j.tree.2012.07.001","seite":"582 f."}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b55c4ef7cbe4a3bb"}},{"id":"qx-c1-046","clusterId":"C","werkstueckRef":"C.3.4","stufe":2,"question":"Ein Bigfoot-Anhänger sagt: „Die Tiere sind eben scheu und hinterlassen keine Spuren.“ Welche Überlegung stellt diesen Einwand am stärksten infrage?","options":["Eine Population von einigen Tausend großen Primaten bräuchte täglich Tonnen Nahrung und ließe Tausende Spuren, Kothaufen, Nester und im Lauf der Zeit auch Kadaver zurück.","Einzelne Sichtungen sind unzuverlässig, weil Menschen im Wald Bären oder Schatten leicht für aufrechte Gestalten halten und ihre Erinnerung daran später oft ausschmücken.","Große Tiere, die Menschen meiden, sind oft nachtaktiv und halten sich abseits von Wegen und Siedlungen auf, sodass sie nur selten gesehen oder fotografiert werden.","Man sollte den Anhänger nicht persönlich angreifen, sondern sein Argument prüfen, denn wie glaubwürdig jemand wirkt, sagt nichts darüber, ob seine Aussage stimmt."],"correctIndex":0,"explanation":"Scheu mag erklären, warum man ein einzelnes Tier selten sieht, aber nicht, warum eine ganze Population keine Spuren hinterlässt. Damit sich eine große Tierart über Generationen hält, braucht sie meist mehrere hundert bis einige tausend Tiere; die bräuchten täglich Tonnen an Nahrung und hinterließen Fußspuren, Kothaufen mit DNA, Schlafnester und irgendwann Knochen und Kadaver. Bestätigt wurde bis heute weder ein Körper noch ein Knochen eines solchen Wesens, und genetisch untersuchte Haarproben stammten von bekannten Tieren wie Bären, Pferden oder Menschen. Dass einzelne Sichtungen unzuverlässig sind, stimmt, betrifft aber Zeugenberichte und nicht die Frage nach den Spuren. Nachtaktivität und Menschenscheu erklären wenige Sichtungen, aber keine Tausende Spuren, Nester und Kadaver. Und die Glaubwürdigkeit des Anhängers ist für die Sache unerheblich, geprüft wird das Argument.","coreRule":"⚡ Scheu erklärt, warum Einzeltiere selten auffallen, nicht das Fehlen von Kot, Spuren und Knochen einer ganzen Population.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Der ökologische Fußabdruck“); Fn. gl-c-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, 20140161; Lan u. a. 2017)","status":"entwurf","scenario":"","kurz":"Scheu erklärt, warum man ein einzelnes Tier selten sieht, nicht aber, warum eine ganze Population nichts hinterlässt. Eine Art, die Generationen überdauert, bräuchte täglich Tonnen Nahrung und ließe Spuren, Kot, Nester und irgendwann Kadaver zurück.","prueffrage":"Was hinterlassen scheue Waldtiere wie Bären oder Luchse, obwohl man sie selbst kaum zu Gesicht bekommt?","rueckmeldung":[{"option":1,"text":"Dass Sichtungen unzuverlässig sind, stimmt: Bären, Schatten und ausgeschmückte Erinnerungen spielen eine Rolle. Der Einwand des Anhängers betrifft aber die fehlenden Spuren, und dazu sagt die Kritik an Zeugenberichten nichts."},{"option":2,"text":"Nachtaktivität und Menschenscheu erklären durchaus, warum solche Tiere selten gesehen oder fotografiert werden. Tausende Spuren, Nester und Kadaver einer ganzen Population ließen sich damit aber nicht verbergen; Sichtbarkeit und Spuren sind zweierlei."},{"option":3,"text":"Als Regel stimmt das: Man prüft ein Argument, nicht die Person, die es vorbringt. Die Frage zielt aber auf die Sache selbst, und dazu, was eine Population hinterlassen müsste, sagt diese Antwort nichts."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): „Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates“, Proc. R. Soc. B 281, 20140161 (frei in PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4100498/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"29ae55721dacdbcf"}},{"id":"qx-c1-047","clusterId":"C","werkstueckRef":"C.3.4","stufe":3,"question":"Welche Nachfrage bringt die Prüfung seiner Behauptung am ehesten voran?","options":["Du bittest um ein schärferes Bild desselben Wesens, denn wenn es darauf deutlich zu erkennen ist, wäre die Existenz einer ganzen Art damit belegt.","Du fragst nach weiteren Zeugen der Sichtung, denn wenn mehrere Leute das Wesen unabhängig gesehen haben, wäre die Existenz einer ganzen Art damit belegt.","Du forderst ein Gutachten zur Echtheit des Fotos, denn wenn niemand eine Fälschung nachweisen kann, wäre die Existenz einer ganzen Art damit belegt.","Du fragst nach Spuren einer Population, denn wer seit über hundert Jahren dort lebt, müsste Kot mit DNA, Schlafnester, Knochen oder Kadaver hinterlassen."],"correctIndex":3,"explanation":"Ein einzelnes Foto, selbst ein echtes, belegt höchstens ein Einzeltier. Eine Art kann aber nicht von einem Einzeltier oder einem Pärchen leben: Bei großen Säugetieren braucht es nach Schätzungen mehrere hundert bis einige tausend Individuen, die in Kontakt stehen, damit Inzucht, Gendefekte und Zufallskatastrophen die Gruppe nicht auslöschen. Sollen solche Wesen dort seit über hundert Jahren leben, müsste eine so große Population über viele Generationen jeden Tag messbare Spuren hinterlassen: Fußabdrücke, Kot (eine Fundgrube für DNA-Analysen), Schlafnester und Spuren in der Vegetation. Sie würde außerdem sterben und Kadaver, Knochen oder Fossilien hinterlassen. Bis heute wurde jedoch kein einziger Körper und kein junges Fossil eines solchen Wesens wissenschaftlich bestätigt, und keine der genetisch untersuchten Haarproben ließ sich einer unbekannten Primatenart zuordnen. Die Frage lautet also nicht „Ist auf dem Foto etwas Echtes zu sehen?“, sondern „Wo sind die Belege für eine ganze Population?“. Ein schärferes Bild zeigt weiterhin nur ein Tier, und mehr Zeugen für dieselbe Sichtung ersetzen weder Kadaver noch DNA. Auch ein fehlender Fälschungsnachweis führt nicht weiter, denn die Prüfung setzt bei den Belegen an, die eine ganze Population hinterlassen müsste, nicht beim Foto.","coreRule":"⚡ Ein Foto belegt höchstens ein Tier, eine Art braucht eine Population – mit Kadavern, Knochen und DNA.","beleg":"Werkstück C.3.4 (Werkbank-Frage; Red Flags; MVP-Abschnitt; Fußnote gl-c-mvp)","status":"entwurf","scenario":"Ein Bekannter zeigt dir ein unscharfes Foto: Am Rand eines nordamerikanischen Waldes ist eine aufrecht gehende Gestalt zu sehen. Er sagt: „Das ist der Beweis für einen unentdeckten Riesenprimaten. In dieser Gegend werden solche Wesen seit über hundert Jahren gesichtet.“ Du willst das Foto nicht einfach als Fälschung abtun.","kurz":"Ein einzelnes Foto, selbst ein echtes, zeigt höchstens ein Einzeltier. Eine Art, die seit über hundert Jahren dort lebt, müsste aber als große Population Kot, Nester, Knochen oder Kadaver hinterlassen. Danach zu fragen prüft die Behauptung.","prueffrage":"Was alles müsste in dieser Gegend vorhanden sein, wenn dort über Generationen hinweg viele solcher Wesen leben?","rueckmeldung":[{"option":0,"text":"Ein schärferes Bild würde zeigen, ob da wirklich etwas Besonderes steht. Doch selbst dann wäre es ein einzelnes Tier auf einem Foto, und eine Art lebt nicht von einem Einzeltier. Für eine ganze Population reicht ein Bild nicht, wie scharf es auch ist."},{"option":1,"text":"Mehr Zeugen für dieselbe Sichtung klingen nach stärkerer Absicherung. Sie bestätigen aber bestenfalls, dass jemand etwas gesehen hat, nicht dass dort eine ganze Population lebt. Kadaver, Kot mit DNA oder Nester ersetzen sie nicht."},{"option":2,"text":"Ein Gutachten klärt, ob das Foto manipuliert wurde, und das ist eine berechtigte Frage. Selbst ein echtes Foto belegt aber höchstens ein Einzeltier, und „nicht als Fälschung entlarvt“ ist noch kein Beleg. Die Prüfung muss bei dem ansetzen, was eine ganze Population hinterlassen müsste."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): „Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates“, Proc. R. Soc. B 281, 20140161 (frei in PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4100498/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5d2eb04f2f74d2b0"}},{"id":"qx-c1-048","clusterId":"C","werkstueckRef":"C.3.4","stufe":4,"question":"Ein Reiseführer am Loch Ness behauptet, in dem See lebe seit der Dinosaurier-Zeit eine Population von Plesiosauriern. Welche Fragen prüfen diese Behauptung am besten?","options":["Wie viele Tiere es für das Überleben der Art bräuchten, wovon sie sich im See ernähren würden und wo die Kadaver blieben.","Wie lang ein Plesiosaurier werden konnte, ob er Flossen oder Beine hatte und auf welche Weise er seine Beute fing.","Wer die Behauptung zuerst aufgestellt hat, welche Absicht dahinterstand und ob der Reiseführer vom Tourismus am See lebt.","Seit wann die Legende erzählt wird, welche Geschichten es in der Gegend früher gab und wie sie sich verbreitet haben."],"correctIndex":0,"explanation":"Eine Art überlebt nicht als Einzeltier, sondern nur als Population, die groß genug für einen gesunden Genpool ist; bei großen Wirbeltieren schätzt man dafür meist mehrere hundert bis einige tausend Individuen. Eine solche Population bräuchte täglich viel Nahrung, würde den Fischbestand spürbar verändern und hinterließe Kadaver und Knochen, und ein begrenzter, gut erforschter See könnte sie kaum ernähren. Eine gezielte Umwelt-DNA-Suche in Loch Ness fand denn auch keine Reptilien-DNA. Dazu kommt: Das Tal war in der letzten Eiszeit von Gletschern bedeckt, den See gibt es erst seit rund 10.000 Jahren, also nicht seit der Zeit der Dinosaurier. Wie ein Plesiosaurier aussah und jagte, beschreibt das Tier, beantwortet aber nicht, ob eine überlebensfähige Population dort bestehen kann. Wer die Behauptung aufgestellt hat und wovon er lebt, ist eine sinnvolle Quellenfrage, sagt aber nichts über die Möglichkeit eines solchen Bestands. Die Geschichte der Legende erklärt, woher die Erzählung kommt, nicht, ob sie biologisch möglich ist.","coreRule":"⚡ Prüfe die Herde, nicht das einzelne Wesen: Populationsgröße, Nahrung, Kadaver.","beleg":"Werkstück C.3.4 (Anwendung & Relevanz, „Bei Mythen über ‚überlebende Dinosaurier‘“; Aktivierungs-Frage; Red Flags)","status":"entwurf","scenario":"","kurz":"Eine Art überlebt nur als Population mit vielen Tieren. Die bräuchte täglich viel Nahrung und hinterließe Kadaver; im begrenzten See ist beides kaum denkbar. Wie so ein Tier aussah, sagt dazu nichts.","prueffrage":"Ließe sich die Behauptung auch prüfen, ohne dass je jemand eines der Tiere sieht oder ortet?","rueckmeldung":[{"option":1,"text":"Zu wissen, wie ein Plesiosaurier gebaut war und jagte, hilft, sich das Tier vorzustellen. Es beschreibt aber nur das Tier und klärt nicht, ob im See überhaupt eine überlebensfähige Gruppe davon bestehen könnte."},{"option":2,"text":"Wer etwas behauptet und wovon er lebt, ist eine sinnvolle Quellenfrage. Sie sagt aber nichts darüber, ob ein solcher Bestand im See möglich wäre; das lässt sich unabhängig von der Person prüfen."},{"option":3,"text":"Die Herkunft der Legende erklärt, warum man sich die Geschichte erzählt. Ob ein solcher Bestand im See biologisch möglich wäre, folgt daraus nicht, denn auch alte, weit verbreitete Erzählungen können falsch sein."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"url","kurz":"phys.org (AFP, 2019): „Could the Loch Ness monster be a giant eel?“","oeffentlich":true,"url":"https://phys.org/news/2019-09-loch-ness-monster-giant-eel.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f35753a46eb1cfc5"}},{"id":"qx-c1-049","clusterId":"C","werkstueckRef":"C.3.6","stufe":1,"question":"Welche Antwort an Jonas ist nach deiner Recherche am besten begründet?","options":["Seine Prämisse fällt, denn das Schneidesystem stammt aus der Abwehr von Bakterien; zu prüfen bleibt nur noch, ob die Umprogrammierung im Labor sauber gelang.","Seine Prämisse fällt, denn das Schneidesystem stammt aus der Abwehr von Bakterien; je weiter ein Einsatz vom natürlichen Zweck abweicht, desto strenger prüft man ihn.","Seine Prämisse fällt, denn das Schneidesystem stammt aus der Abwehr von Bakterien; ob eine bestimmte Anwendung sicher ist, muss man trotzdem an ihr selbst prüfen.","Seine Prämisse hält, denn erst im Labor lernte das System, jede gewünschte Stelle zu schneiden; vor jedem Einsatz muss man es daher als neuen Eingriff prüfen."],"correctIndex":2,"explanation":"Jonas verwechselt die Umprogrammierung eines Werkzeugs mit seiner Entstehung. Bakterien speichern Bruchstücke der DNA früherer Angreifer als eine Art Fahndungsfoto-Archiv und zerschneiden bei erneutem Angriff mithilfe dieses Archivs und der Cas-Proteine die virale DNA, bei manchen Bakterien mit Cas9. Das System ist also ein uraltes natürliches Abwehrsystem; 2012 zeigten Doudna und Charpentier, dass man ihm eine beliebige „Adresse“ mitgeben kann, sodass es jede gewünschte Sequenz schneidet, und erhielten dafür 2020 den Nobelpreis für Chemie. Die natürliche Herkunft widerlegt Jonas’ Prämisse, sagt aber noch nichts darüber, ob eine Anwendung sicher oder ethisch vertretbar ist: „Natürlich“ ist kein Gütesiegel und „künstlich“ kein Makel, geprüft werden muss die konkrete Anwendung nach Nutzen und Risiko. Nur noch die saubere Umprogrammierung zu prüfen, behandelt die natürliche Herkunft doch als Gütesiegel. Die Prüfstrenge am Abstand zum natürlichen Zweck auszurichten, bewertet wieder nach dem Etikett statt nach dem Risiko der Anwendung. Dass das System erst im Labor jede Stelle schneiden lernte, stimmt zwar, macht aus der Umprogrammierung aber keinen Ursprung, also hält die Prämisse nicht.","coreRule":"⚡ Prüfe die Herkunft einer Sache, bevor du sie als „völlig neu“ oder „unnatürlich“ bewertest. Und bewerte die Anwendung nach Nutzen und Risiko, nicht nach dem Etikett „natürlich“ oder „künstlich“.","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Woher das Werkzeug kommt“); Fn. gl-c-crispr-immun (Doudna/Sternberg 2017); Fn. gl-c-crispr-nobel (Jinek u. a. 2012, Science 337, S. 816–821)","status":"entwurf","scenario":"In einer Diskussion über Gentechnik sagt Jonas: „CRISPR ist ein rein künstliches Laborprodukt. Die Natur hat damit nichts zu tun, deshalb ist es ein unkontrollierbarer Eingriff in etwas, das es vorher nie gab.“ Du schlägst nach und findest: Bakterien speichern Bruchstücke der DNA früherer Virenangreifer und zerschneiden damit bei einem neuen Angriff die Virus-DNA. 2012 zeigten Forscherinnen, dass man diesem Schneidesystem eine beliebige „Adresse“ mitgeben kann, sodass es jede gewünschte DNA-Stelle schneidet.","kurz":"Die Herkunft aus der Bakterienabwehr widerlegt Jonas' Prämisse: Umprogrammiert wurde ein bestehendes Werkzeug, nicht ein neues erfunden. Das beweist aber keine Sicherheit, denn „natürlich“ ist kein Gütesiegel; geprüft wird jede Anwendung selbst.","prueffrage":"Was genau wurde 2012 neu geschaffen, und was gab es davor schon?","rueckmeldung":[{"option":0,"text":"Dass die Herkunft Jonas' Prämisse widerlegt, stimmt. Aber auch eine saubere Umprogrammierung sagt nichts über Nutzen und Risiko der Anwendung: Natürlicher Ursprung und technisches Gelingen ersetzen die Prüfung der konkreten Anwendung nicht."},{"option":1,"text":"Dass man Anwendungen prüfen muss, stimmt. Der Maßstab trägt aber nicht: Wie nah ein Einsatz am natürlichen Zweck liegt, sagt wenig über sein Risiko. Entscheidend sind Nutzen und Risiko der Anwendung selbst, nicht das Etikett „natürlich“ oder „künstlich“."},{"option":3,"text":"Dass das System erst im Labor jede gewünschte Stelle schneiden lernte, stimmt. Das System selbst ist aber ein natürliches Abwehrsystem von Bakterien, und die Umprogrammierung macht daraus keinen Ursprung. Prüfbedarf entsteht aus Nutzen und Risiko, nicht aus dem Etikett „neu“."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Jinek, M.; Chylinski, K.; Fonfara, I.; Hauer, M.; Doudna, J. A.; Charpentier, E. (2012): „A programmable dual-RNA-guided DNA endonuclease in adaptive bacterial immunity“, Science 337, 816–821 (frei in PMC6286148)","oeffentlich":true,"doi":"10.1126/science.1225829","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6286148/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Doudna, J. A.; Sternberg, S. H. (2017): A Crack in Creation, Kap. „Cracking the Code“ (Landkarte [^gl-c-crispr-immun], E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"7ce6dc5a5059eaf3"}},{"id":"qx-c1-050","clusterId":"C","werkstueckRef":"C.3.6","stufe":2,"question":"Welche Antwort begründet am besten, warum der erste Fall unstrittig als medizinischer Fortschritt gilt, der zweite aber nicht?","options":["Bei Meldung 1 ist die Veränderung auf den behandelten Menschen beschränkt, er kann zustimmen, und die Anwendung ist geprüft und zugelassen; bei Meldung 2 trifft all das nicht zu.","Bei Meldung 1 wird ein bewährtes Werkzeug an Blutstammzellen eingesetzt, bei Meldung 2 ein neues am Embryo, und nur langjährig erprobte Werkzeuge gelten am Menschen als vertretbar.","Bei Meldung 2 droht ein Weg hin zu Designerbabys, bei der Behandlung der Blutstammzellen in Meldung 1 nicht, und Eingriffe gelten als verwerflich, wenn sie zu weiteren Eingriffen führen könnten.","Bei Meldung 1 wird ein natürlicher Vorgang unterstützt, nämlich die Neubildung von Blut, bei Meldung 2 gegen die Natur gehandelt, und Eingriffe gegen die Natur gelten als verwerflich."],"correctIndex":0,"explanation":"Beide Meldungen nutzen dasselbe Werkzeug, der Unterschied liegt woanders. Bei der zugelassenen Therapie wird nur der behandelte Mensch verändert (somatisch, nicht vererbbar), er ist einwilligungsfähig, die Krankheit ist schwer und gut verstanden, und Behörden haben die Anwendung nach klinischer Prüfung zugelassen (Großbritannien im November 2023, USA im Dezember 2023). Beim Embryo-Eingriff wird dagegen das Erbgut aller künftigen Generationen verändert, ohne dass diese je zustimmen konnten. Die Folgen lassen sich nicht zurücknehmen, und der Eingriff erfolgte an gesunden Embryonen zur Vorbeugung statt zur Heilung. Wer beides unter „Gentechnik“ in einen Topf wirft, übersieht genau die Fragen, auf die es ankommt: Welche Zellen sind betroffen, wer stimmt zu, wird geheilt oder „verbessert“, ist die Anwendung geprüft? Der Unterschied im Werkzeug klingt nach einem Maßstab, scheidet aber aus, weil in beiden Meldungen CRISPR genutzt wird. Die Sorge vor Designerbabys ist ernst zu nehmen, betrifft aber eine Vermutung über die Zukunft und erklärt nicht, was die beiden Fälle heute trennt. „Natürlich“ klingt nach einem einfachen Maßstab, taugt aber nicht, denn in beiden Fällen wird das Erbgut mit demselben Werkzeug verändert.","coreRule":"⚡ Bei Gentechnik zählt nicht das Werkzeug, sondern: Welche Zellen werden verändert, wer stimmt zu, wird geheilt oder verbessert, und ist die Anwendung geprüft?","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Wo CRISPR heute bereits legal Leben rettet“; Kipppunkt); Fn. gl-c-casgevy (MHRA 16.11.2023; FDA 8.12.2023)","status":"entwurf","scenario":"Zwei Meldungen zur Genschere CRISPR:\\n\\nMeldung 1: Eine Therapie gegen die Sichelzellkrankheit wurde von mehreren Zulassungsbehörden genehmigt. Dabei werden einem jugendlichen oder erwachsenen Patienten Blutstammzellen entnommen, außerhalb des Körpers gezielt editiert und zurückgegeben.\\n\\nMeldung 2: Ein Forscher verkündet, er habe Embryonen gesunder Eltern editiert, um die Kinder gegen eine Infektion zu schützen. Die Veränderung wird an alle späteren Nachkommen weitergegeben.","kurz":"Entscheidend ist nicht das Werkzeug, denn beide Male kommt CRISPR zum Einsatz. Es kommt darauf an, wessen Zellen verändert werden, wer zustimmen kann, ob geheilt wird und ob die Anwendung geprüft ist.","prueffrage":"Welche Angaben machen die beiden Meldungen zu Werkzeug, behandelter Person und Weitergabe der Veränderung, und wo unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Dass eine Anwendung geprüft sein muss, ist ein wichtiger Gesichtspunkt. Das Werkzeug unterscheidet die Fälle aber nicht, denn beide Meldungen nutzen CRISPR. Entscheidend ist, was damit geschieht und wie es zugelassen wurde."},{"option":2,"text":"Die Sorge vor Designerbabys ist ernst zu nehmen, sie betrifft aber eine Vermutung über die Zukunft. Was die beiden Fälle heute trennt, erklärt sie nicht, und dass ein Eingriff zu weiteren führen könnte, macht ihn noch nicht verwerflich."},{"option":3,"text":"„Natürlich“ klingt nach einem einfachen Maßstab, taugt aber nicht: In beiden Fällen wird das Erbgut mit demselben Werkzeug verändert. Ob ein Eingriff natürlich ist, sagt noch nichts darüber, ob er vertretbar ist."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"},{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"},{"typ":"url","kurz":"MIT Technology Review (30.12.2019): „He Jiankui sentenced to three years in prison for CRISPR babies“","oeffentlich":true,"url":"https://www.technologyreview.com/2019/12/30/131061/he-jiankui-sentenced-to-three-years-in-prison-for-crispr-babies","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aae8149599f08eec"}},{"id":"qx-c1-051","clusterId":"C","werkstueckRef":"C.3.6","stufe":3,"question":"Eine Kommentatorin schreibt zu einem Gentechnik-Skandal: „Das Problem war das Werkzeug. Wer CRISPR benutzt, spielt mit dem Feuer – wer es einsetzt, hat die Grenze schon überschritten.“ Tatsächlich wird CRISPR in Laboren weltweit routinemäßig genutzt, und eine CRISPR-basierte Therapie ist bei Sichelzellkrankheit zugelassen. Welche Frage trennt den Skandalfall am besten von dieser legalen Anwendung?","options":["Welche Zellen wurden verändert, wer konnte zustimmen und wurde eine bestehende Krankheit behandelt oder ein gesunder Mensch verändert?","Welches Werkzeug wurde jeweils eingesetzt, arbeitet es in beiden Fällen nach demselben Prinzip, und wie lange gibt es das Verfahren schon?","Wie zuverlässig arbeitet die Genschere, wie oft schneidet sie an der falschen Stelle, und wie lässt sich das im Labor jeweils messen?","Wer hat die Entwicklung der Genschere bezahlt, welche Firmen verdienen an der zugelassenen Therapie, und wie unabhängig sind die Gutachter?"],"correctIndex":0,"explanation":"Wenn dasselbe Werkzeug in einem Fall verurteilt und im anderen zugelassen wird, kann das Werkzeug den Unterschied nicht erklären. Er muss in den Umständen der Anwendung liegen. Hier gab es zwei Grenzüberschreitungen zugleich: Gesunden Embryonen wurde ein Gen ausgeschaltet, um sie später vor einer HIV-Infektion zu schützen – eine Vorbeugung, keine Heilung einer bestehenden Krankheit. Und die Veränderung betrifft die Keimbahn und wird an alle Nachkommen weitergegeben, die nie zustimmen konnten. Bei der zugelassenen Sichelzell-Therapie werden dagegen Blutstammzellen eines einwilligungsfähigen Patienten außerhalb des Körpers editiert. Das betrifft nur diese Person, und die Krankheit besteht bereits. Die Frage nach Zellart, Zustimmung und Behandlungsziel trennt beide Fälle sauber.","coreRule":"⚡ Wenn dasselbe Werkzeug mal verurteilt, mal zugelassen wird, liegt der Unterschied in der Anwendung: Welche Zellen, wer stimmt zu, Heilung oder Verbesserung?","beleg":"Werkstück C.3.6 (Der Tag, an dem die Grenze verschwand; Kipppunkt; Wo CRISPR heute bereits legal Leben rettet); Fn. gl-c-hejiankui (Verurteilung in Shenzhen, Dezember 2019); Fn. gl-c-casgevy (Zulassung MHRA/FDA 2023)","status":"entwurf","scenario":"Ein Forscher hat 2018 mit CRISPR ein Gen im Erbgut von Embryonen ausgeschaltet, um die später geborenen Kinder gegen eine Virusinfektion zu schützen. Die Kinder waren gesund. Fachwelt und Behörden verurteilten das Experiment, der Forscher wurde 2019 zu drei Jahren Haft verurteilt. Dieselbe Technik wird in anderen Fällen als zugelassene Therapie eingesetzt.","kurz":"Verurteilt und zugelassen wurde dasselbe Werkzeug, also muss der Unterschied in den Umständen liegen: welche Zellen verändert wurden, wer zustimmen konnte und ob eine Krankheit behandelt wurde. Der Fehler ist, ein Werkzeug für den Skandal verantwortlich zu machen.","prueffrage":"Was haben der verurteilte Versuch und die zugelassene Therapie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Den Vergleich der Werkzeuge anzustellen wirkt gründlich, weil die Kommentatorin gerade das Werkzeug beschuldigt. Aber dort steht die Antwort schon fest: In beiden Fällen kam CRISPR zum Einsatz. Was sich nicht unterscheidet, kann keinen Unterschied erklären."},{"option":2,"text":"Fehlschnitte der Genschere sind ein echtes technisches Thema. Die Frage danach gilt aber für beide Anwendungen gleichermaßen, sie sagt also nicht, warum eine verurteilt und die andere zugelassen wurde."},{"option":3,"text":"Wer zahlt und wer begutachtet, ist als Quellenfrage berechtigt, wenn man Interessen prüfen will. Sie klärt aber nicht, wer hier wen verändert hat, und genau daran liegt der Unterschied zwischen den beiden Fällen."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"MIT Technology Review (30.12.2019): „He Jiankui sentenced to three years in prison for CRISPR babies“","oeffentlich":true,"url":"https://www.technologyreview.com/2019/12/30/131061/he-jiankui-sentenced-to-three-years-in-prison-for-crispr-babies","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"},{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"24fa93f5a649a142"}},{"id":"qx-c1-052","clusterId":"C","werkstueckRef":"C.3.6","stufe":4,"question":"Welche Einordnung des Angebots ist am besten begründet?","options":["Das Angebot ist vertretbar, weil erwachsene Kunden selbst entscheiden dürfen und das Risiko der teuren Behandlung freiwillig auf sich nehmen.","Das Angebot ist vertretbar, weil die Entwickler der Methode den Nobelpreis erhalten haben und die Klinik sich damit auf ein anerkanntes Verfahren stützt.","Das Angebot ist abzulehnen, weil Altern ein natürlicher Vorgang ist und die Natur ihre Ordnung nicht ohne Not durch einen Eingriff ins Erbgut ändern lassen sollte.","Das Angebot ist ein Warnsignal, weil hier für mehrere zehntausend Euro Hoffnung verkauft wird, bevor Wirksamkeit und Sicherheit der Behandlung belegt sind."],"correctIndex":3,"explanation":"Ein Nobelpreis würdigt die Entdeckung einer Methode, nicht die Wirksamkeit oder Sicherheit einer einzelnen Anwendung. Ob eine Behandlung hilft, zeigen nur kontrollierte Studien und eine behördliche Zulassung. Die Klinik bietet außerhalb davon eine Behandlung gegen ein derart breites Ziel wie „Alterung“ an, zeigt keine Belege und verlangt hohe Preise: Hier wird Hoffnung zu Geld gemacht, bevor die Wissenschaft nachgezogen hat. Seriös wäre ein Angebot erst als zugelassenes Medikament oder im Rahmen einer regulären klinischen Studie. Entscheidend ist also nicht die Technik, sondern der Prüfstatus der konkreten Anwendung. Die Selbstbestimmung Erwachsener ist ein wichtiger Grundsatz, setzt aber voraus, dass sie die Belege kennen, die hier fehlen. Der Nobelpreis klingt nach einem Gütesiegel, sagt aber etwas über die Methode und nichts darüber, ob diese Anwendung hilft. Dass Altern natürlich sei, klingt nach einem Maßstab, taugt aber nicht, denn geprüfte, zugelassene Therapien zeigen, dass dieselbe Methode Leben retten kann.","coreRule":"⚡ Prüfe bei „CRISPR-Angeboten“ zuerst: Gibt es ein zugelassenes Medikament oder eine reguläre Studie? Wenn nicht, ist Vorsicht geboten. Ein Preis für die Methode ist kein Beleg für die Anwendung.","beleg":"Werkstück C.3.6 (Anwendung & Relevanz, „Gegen unregulierte ‚Gentherapie‘-Kliniken“; Red Flags)","status":"entwurf","scenario":"Eine Klinik wirbt außerhalb von Studien mit „CRISPR-Behandlungen gegen Alterung“. Die Behandlung kostet mehrere zehntausend Euro. Belastbare Wirksamkeitsnachweise zeigt die Klinik nicht, nennt aber stolz, dass die Entwickler der Methode den Nobelpreis erhalten haben.","kurz":"Entscheidend ist der Prüfstatus der konkreten Anwendung, nicht die Technik. Der Nobelpreis würdigt eine Methode; ob diese Behandlung hilft und sicher ist, zeigen nur kontrollierte Studien. Ohne sie wird hier Hoffnung verkauft.","prueffrage":"Was führt die Klinik zu ihren Gunsten an, und bezieht sich das auf die Methode allgemein oder auf genau diese Behandlung?","rueckmeldung":[{"option":0,"text":"Selbstbestimmung Erwachsener ist ein wichtiger Grundsatz. Eine freie Entscheidung über Risiko und Kosten setzt aber voraus, dass man die Belege kennt, und genau die zeigt die Klinik nicht."},{"option":1,"text":"Der Preis ist echt und die Methode anerkannt. Er würdigt aber die Entdeckung der Methode und sagt nichts darüber, ob diese Anwendung wirkt und sicher ist. Dafür braucht es Studien und Zulassung."},{"option":2,"text":"Dass etwas natürlich ist, sagt noch nichts darüber, ob es gut ist oder bleiben soll. Dieselbe Methode kann in geprüften, zugelassenen Therapien Leben retten. Für die Ablehnung zählt der fehlende Beleg, nicht die Natürlichkeit."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration: „Important Patient and Consumer Information About Regenerative Medicine Therapies“","oeffentlich":true,"url":"https://www.fda.gov/vaccines-blood-biologics/consumers-biologics/important-patient-and-consumer-information-about-regenerative-medicine-therapies","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4f58c07319e18c2d"}},{"id":"qx-c1-053","clusterId":"C","werkstueckRef":"C.4.1","stufe":1,"question":"Welche Schlussfolgerung stützen die Daten am besten?","options":["Die Erkrankung wird durch winzige, unsichtbare Krankheitserreger verursacht, die Ärzte und Studenten an den Händen vom Seziersaal zu den Müttern der ersten Abteilung tragen.","Die Erkrankung hängt von der Erfahrung ab: Die Hebammen haben mehr Routine bei Geburten als Ärzte und Studenten, deshalb sterben bei ihnen nur etwa 2 % der Mütter.","Die Erkrankung hängt von den Müttern ab: Frauen mit schwereren Geburten kommen eher in die erste Abteilung der Ärzte, deshalb sterben dort bis zu 18 % von ihnen.","Die Erkrankung entsteht durch grobe Untersuchungen: Ärzte und Studenten untersuchen die Frauen häufiger und verletzen dabei die Geburtswege stärker als die Hebammen."],"correctIndex":0,"explanation":"Der Unterschied zwischen den Abteilungen fällt mit einem Faktor zusammen: Wer aus dem Seziersaal kommt, trägt etwas auf den Händen zu den Müttern. Dass die Sterblichkeit nach dem Desinfizieren der Hände sofort und deutlich fällt, stützt diese Ursache: Wird die vermutete Ursache entfernt, verschwindet der Effekt. Das passt zu der Erklärung, dass viele Krankheiten durch unsichtbare Mikroorganismen verursacht werden, die in den Körper gelangen und sich dort vermehren (Keimtheorie). Mehr Routine der Hebammen klingt plausibel, würde aber nicht erklären, warum dieselben Ärzte nach dem Desinfizieren der Hände plötzlich viel weniger Mütter verlieren. Unterschiede zwischen den Müttern klingen möglich, ändern sich aber durch eine Maßnahme an den Händen der Ärzte nicht. Grobe Untersuchungen wären eine denkbare Ursache, doch sie blieben auch nach der Chlorlösung genauso grob.","coreRule":"⚡ Wenn das Entfernen einer vermuteten Ursache die Wirkung beseitigt und ein Unterschied zwischen Gruppen genau mit dieser Ursache zusammenfällt, ist die Ursachen-Erklärung gestützt – bei Krankheiten oft: ein spezifischer Erreger statt diffuser „Dünste“ oder „Milieus“.","beleg":"Werkstück C.4.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Geburtsklinik gibt es zwei Abteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben im Schnitt rund 10 % der Mütter an Kindbettfieber, in einzelnen Monaten bis zu 18 %. In der zweiten, betreut ausschließlich von Hebammen, sind es im Schnitt rund 3,5 %. Die Ärzte und Studenten kommen vor ihrer Arbeit direkt aus dem Seziersaal, die Hebammen nicht. Nachdem sich alle Ärzte vor jeder Untersuchung die Hände in einer Chlorlösung desinfizieren müssen, fällt die Sterblichkeit in der ersten Abteilung auf unter 2 %.","kurz":"Der Unterschied fällt mit dem Gang aus dem Seziersaal zusammen, und er verschwindet, sobald die Hände desinfiziert werden. Das spricht für etwas, das an den Händen haftet. Wer nur auf die Unterschiede der Abteilungen schaut, übersieht, dass sich diese Unterschiede nicht geändert haben.","prueffrage":"Worin unterscheiden sich die beiden Abteilungen außer der Sterblichkeit noch, und was änderte sich genau vor dem Rückgang?","rueckmeldung":[{"option":1,"text":"Dass Hebammen mehr Routine haben, klingt plausibel. Nach dem Desinfizieren der Hände arbeiten aber dieselben Ärzte mit unveränderter Erfahrung, und trotzdem sterben deutlich weniger Mütter. Routine erklärt das nicht."},{"option":2,"text":"Dass schwerere Geburten eher in der ärztlichen Abteilung landen, wäre möglich, steht aber nirgends in den Angaben. Und die Mütter bleiben dieselben, wenn sich die Ärzte die Hände desinfizieren, ihre Sterblichkeit sinkt dennoch."},{"option":3,"text":"Grobes Untersuchen wäre als Ursache denkbar, wird im Szenario aber nicht berichtet. Die Chlorlösung macht die Untersuchungen nicht sanfter, und doch fällt die Sterblichkeit. Der Grund liegt also nicht in der Art des Untersuchens."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"654380190bd8f48b"}},{"id":"qx-c1-054","clusterId":"C","werkstueckRef":"C.4.1","stufe":2,"question":"Welche Schlussfolgerung passt am besten zu dem Muster in den Beobachtungen, und welcher nächste Schritt prüft sie?","options":["Etwas von den Leichen im Seziersaal gelangt über die Hände der Ärzte zu den Müttern; die Ärzte sollten sich vor jeder Untersuchung die Hände desinfizieren und die Sterblichkeit weiter beobachten.","Die Hebammen haben mehr Erfahrung bei Geburten als die Ärzte und Studenten; die Ärzte sollten von ihnen geschult werden, und die Sterblichkeit sollte weiter beobachtet werden.","Schlechte Dünste aus dem Seziersaal ziehen durchs Haus; der Seziersaal sollte weiter von den Geburtsräumen entfernt liegen, und die Sterblichkeit sollte weiter beobachtet werden.","Die Ärzte und Studenten untersuchen die Frauen häufiger und gröber als die Hebammen; sie sollten schonender untersuchen, und die Sterblichkeit sollte weiter beobachtet werden."],"correctIndex":0,"explanation":"Die Ausgangslage legt einen gemeinsamen Faktor nahe: Genau die Gruppe mit der hohen Sterblichkeit kommt vom Sezieren, die andere nicht. Dass der Arzt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen stirbt, stützt die Annahme, dass etwas von den Leichen die Krankheit auslöst. Der Weg über die Hände erklärt, warum die Abteilung mit den Ärzten betroffen ist und die andere nicht. Diese Erklärung lässt sich gezielt prüfen: Wenn sich die Ärzte die Hände desinfizieren und die Sterblichkeit sinkt, spricht das für sie. Genau das geschah historisch bei Semmelweis in Wien, wo die Rate nach Chlorwaschungen auf unter zwei Prozent fiel, zeitweise unter eins. Eine Beobachtung kann den Anfang liefern, belastbar wird die Erklärung erst durch Prüfung und Wiederholung. Mehr Erfahrung der Hebammen klingt einleuchtend, erklärt aber nicht die Symptome des gestorbenen Arztes.","coreRule":"⚡ Such den Faktor, in dem sich die Gruppen unterscheiden, formuliere daraus eine Erklärung und prüfe sie mit einer gezielten Maßnahme.","beleg":"Werkstück C.4.1 (Der Arzt, der sich die Hände wusch; Verbindungen); Fn. gl-c-semmelweis (Semmelweis 1861; Best/Neuhauser 2004)","status":"entwurf","scenario":"Eine Klinik hat zwei Geburtsabteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben bis zu 18 % der Mütter an Kindbettfieber, in der zweiten, betreut von Hebammen, nur etwa 2 %. Geburtsposition und Belüftung wurden schon verändert, ohne dass sich etwas bessert. Dann stirbt ein Arzt der Klinik an einer Schnittwunde, die er sich bei einer Leichenöffnung zugezogen hat, mit denselben Symptomen wie die erkrankten Mütter. Die Ärzte und Studenten der ersten Abteilung kommen direkt aus dem Seziersaal, die Hebammen nicht.","kurz":"Die Ärzte kommen vom Sezieren, die Hebammen nicht, und der gestorbene Arzt zeigte nach einer Schnittwunde bei der Leichenöffnung dieselben Symptome. Das legt einen Stoff von den Leichen nahe, der über die Hände übertragen wird; Händedesinfektion prüft das.","prueffrage":"Was haben die Personen der Abteilung mit hoher Sterblichkeit gemeinsam, das bei der anderen Abteilung fehlt?","rueckmeldung":[{"option":1,"text":"Erfahrung bei Geburten kann viel ausmachen und klingt einleuchtend. Sie erklärt aber nicht, warum ein Arzt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen stirbt. Genau dieser Hinweis bleibt dabei unerklärt."},{"option":2,"text":"Der Seziersaal ist hier tatsächlich ein wichtiger Anhaltspunkt. Die Dünste-Idee passt aber nicht zu den Beobachtungen: Das Lüften hat nichts gebracht, und sie erklärt nicht, warum nur die Abteilung der Ärzte betroffen ist."},{"option":3,"text":"Dass der Unterschied in der Art der Untersuchung liegen könnte, ist eine naheliegende Vermutung. Im Szenario steht dazu aber nichts, und sie erklärt nicht, warum der Arzt nach der Schnittwunde bei der Leichenöffnung dieselbe Krankheit bekam."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a1c319d259420107"}},{"id":"qx-c1-055","clusterId":"C","werkstueckRef":"C.4.1","stufe":3,"question":"Welche Bewertung ist an diesem Gespräch am stichhaltigsten?","options":["Ein gesunder Lebensstil ist sinnvoll, ersetzt aber nicht den gezielten Schutz gegen einen bestimmten Erreger: Gegen Wundstarrkrampf nach einer Verletzung an rostigem Metall reicht allgemeine Abwehrstärke nicht aus.","Ein gesunder Lebensstil senkt nachweislich das Risiko vieler Infektionen, und Antibiotika helfen nicht gegen Viren; bei einer Wunde an rostigem Metall ist die Haltung der Bekannten daher nachvollziehbar.","Erwachsene dürfen über Impfungen und Behandlungen am eigenen Körper frei entscheiden; an der Haltung der Bekannten zu Tetanus-Impfung und Antibiotikum lässt sich deshalb sachlich nichts bemängeln.","Die Bekannte schließt von ihrem eigenen guten Befinden auf die Wirkung ihres Lebensstils bei allen Menschen und verallgemeinert voreilig; ein Einzelfall sagt wenig über das Infektionsrisiko vieler."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil und ein gut funktionierendes Immunsystem helfen dabei, Krankheiten abzuwehren. Der Fehler liegt woanders: Die Bekannte setzt diese allgemeinen Maßnahmen an die Stelle von spezifischen Schutzmaßnahmen. Tetanus wird durch einen bestimmten Erreger verursacht. Dagegen schützt die Impfung gezielt, und bei einer bakteriellen Wundinfektion wirken Antibiotika gezielt gegen den Erreger. Allgemeine Abwehrstärke kann das nicht ersetzen. Dass ein gesunder Lebensstil das Risiko vieler Infektionen senkt und Antibiotika nicht gegen Viren helfen, stimmt, trifft aber nicht den Wundstarrkrampf, der durch Bakterien verursacht wird. Selbstbestimmung über den eigenen Körper ist ein wichtiger Grundsatz, bewertet aber nicht, ob die Begründung der Bekannten trägt. Eine Verallgemeinerung auf andere Menschen würde ein Einzelfall nahelegen, doch sie setzt nur für sich selbst Wohlbefinden mit Schutz gleich.","coreRule":"⚡ Lebensstil stärkt, ersetzt aber weder Impfung noch Antibiotika bei Infektionen mit spezifischen Erregern.","beleg":"Werkstück C.4.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Bekannte erzählt: „Ich ernähre mich sehr bewusst, schlafe gut und treibe viel Sport. Mein Immunsystem ist bestens, deshalb brauche ich keine Tetanus-Impfung. Und wenn ich mir mal an rostigem Metall die Hand aufreiße und die Wunde sich entzündet, kommt kein Antibiotikum infrage, ich vertraue auf meine Abwehrkräfte.“","kurz":"Ein gesunder Lebensstil stärkt die Abwehr allgemein, schützt aber nicht gezielt vor dem Tetanus-Erreger. Der Denkfehler liegt darin, allgemeine Stärke an die Stelle spezifischen Schutzes zu setzen: Impfung und Antibiotikum wirken gezielt, Abwehrkräfte nicht.","prueffrage":"Erkranken auch sportliche, gut ernährte Menschen ohne Impfung an Wundstarrkrampf, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Daran stimmt: Lebensstil senkt das Risiko vieler Infektionen, und Antibiotika wirken nicht gegen Viren. Wundstarrkrampf geht aber auf Bakterien zurück, daher trägt der Schluss auf ihre Haltung nicht."},{"option":2,"text":"Die freie Entscheidung über den eigenen Körper ist ein wichtiger Grundsatz. Gefragt war aber, ob die Begründung der Bekannten stichhaltig ist, und die lässt sich sehr wohl sachlich prüfen, ohne ihr Recht zur Entscheidung anzutasten."},{"option":3,"text":"Der Verdacht auf eine Verallgemeinerung liegt nahe, doch die Bekannte spricht nur über sich selbst, nicht über andere. Ihr Fehler ist ein anderer: Sie setzt Wohlbefinden mit gezieltem Schutz gegen einen Erreger gleich."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Centers for Disease Control and Prevention (CDC): „About Tetanus“","oeffentlich":true,"url":"https://www.cdc.gov/tetanus/about/index.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"25e23b795454706b"}},{"id":"qx-c1-056","clusterId":"C","werkstueckRef":"C.4.1","stufe":4,"question":"Ein Therapeut behauptet: „Keime sind nicht die Ursache von Infektionen, sondern nur ein Symptom des ‚ungesunden Milieus‘. Mit einer Entsäuerungskur heilst du die Krankheit.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wer hat die Milieu-Idee entwickelt, denn so alte Theorien aus dem 19. Jahrhundert sind allein wegen ihres Alters überholt?","Wie erklärt diese Sicht, dass sich dieselbe Krankheit bei jeder Ansteckung mit demselben Erreger zeigt, denn eine Behauptung muss zu den Befunden passen?","Wie viele zufriedene Kunden hat die Kur, denn spürbare Besserung nach der Anwendung beweist, dass die Therapie wirkt?","Sind Keime nur unter dem Mikroskop sichtbar, denn nur mit bloßem Auge Sichtbares kann als Krankheitsursache gelten?"],"correctIndex":1,"explanation":"Eine Behauptung wird nicht dadurch stark, dass sie plausibel klingt, sondern dadurch, dass sie die vorhandenen Befunde erklären kann. Hier lautet der Befund: Bestimmte Mikroben lösen bestimmte Krankheiten mit bestimmten Symptomen aus, und wo man die Übertragung der Erreger gezielt unterbindet (Hygiene, Impfung, Antibiotika), sinkt die Erkrankungsrate. Das Beispiel Semmelweis zeigt, wie stark so ein Eingriff wirkt: Nach der Einführung der Chlorwaschungen fiel die Sterblichkeit durch Kindbettfieber in seiner Abteilung von bis zu 18 Prozent auf unter zwei Prozent. Erst die Arbeit von Pasteur und Koch bestätigte später die Keimtheorie dahinter. Wer behauptet, Keime seien nur ein Symptom, muss erklären, warum diese Muster so zuverlässig auftreten. Das Alter einer Idee sagt nichts darüber, ob sie zu den Befunden passt. Auch die Zufriedenheit einzelner Kunden beantwortet diese Frage nicht, denn sie zeigt nicht, ob die Kur der Grund für die Besserung war. Dass Keime mit bloßem Auge unsichtbar sind, spricht nicht gegen ihre Wirkung, denn die Wirkung zeigt sich in den Folgen, nicht in der Sichtbarkeit.","coreRule":"⚡ Verlange Erklärung für die Belege: Wer eine etablierte Ursache bestreitet, muss erklären, warum spezifische Mikroben, spezifische Krankheiten und Heilung durch Beseitigung der Mikroben so zuverlässig zusammenfallen.","beleg":"Werkstück C.4.1 (Anwendung & Relevanz, „Bei der Leugnung der Keimtheorie“; Aktivierungs-Frage)","status":"entwurf","kurz":"Eine Behauptung überzeugt nicht durch Plausibilität, sondern dadurch, dass sie die Befunde erklärt. Wer Keime zum bloßen Symptom erklärt, muss erklären, warum bestimmte Erreger zuverlässig bestimmte Krankheiten auslösen und warum weniger Übertragung weniger Erkrankungen bringt.","prueffrage":"Was geschieht mit der Zahl bestimmter Erkrankungen, wenn Hygiene oder Impfung die Übertragung ihrer Erreger unterbindet?","rueckmeldung":[{"option":0,"text":"Wer eine Behauptung auf ihren Ursprung zurückverfolgt, wirkt gründlich. Das Alter einer Idee entscheidet aber nicht über ihre Geltung: Ob sie trägt, zeigt sich daran, ob sie zu den vorhandenen Befunden passt."},{"option":2,"text":"Zufriedene Kunden wirken wie ein Beleg aus der Praxis. Sie zeigen aber nur, dass es nach der Kur vielen besser ging, nicht, dass die Kur der Grund war. Die Besserung kann auch ohne sie eingetreten sein."},{"option":3,"text":"Dass Keime nur unter dem Mikroskop sichtbar sind, stimmt, und das Unsichtbare kann Misstrauen wecken. Ob etwas Ursache sein kann, hängt aber nicht von seiner Sichtbarkeit ab, sondern davon, ob sich seine Wirkung in den Folgen zeigt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a5c664b13e590835"}},{"id":"qx-c1-057","clusterId":"C","werkstueckRef":"C.4.2","stufe":1,"question":"Eine Freundin hat eine fiebrige Erkältung und will sich beim Arzt „etwas Starkes“ verschreiben lassen: „Das ist eine Infektion, also muss ein Antibiotikum her.“ Wie beurteilst du ihre Schlussfolgerung?","options":["Sie ist ein Zirkelschluss, denn das Antibiotikum steckt schon in der Annahme „Infektion“: Die Freundin setzt voraus, was sie erst begründen müsste.","Sie ist unvollständig, denn bei dieser fiebrigen Erkältung entscheidet der Erreger: Antibiotika wirken nur gegen Bakterien, nicht gegen Viren.","Sie ist ein Fehlschluss von Korrelation auf Ursache, denn weil Fieber und Erkältung gemeinsam auftreten, folgert sie vorschnell einen Zusammenhang.","Sie ist eine Verfügbarkeitsverzerrung, denn sie urteilt nach auffälligen Einzelfällen im Gedächtnis, etwa nach Bekannten, denen ein Antibiotikum half."],"correctIndex":1,"explanation":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher. Bakterien sind einzellige Lebewesen mit eigenem Stoffwechsel; Antibiotika greifen Strukturen an, die menschlichen Zellen fehlen oder sich von ihnen unterscheiden, etwa die bakterielle Zellwand. Viren gelten meist nicht als Lebewesen: Sie bestehen aus Erbgut in einer Proteinhülle, haben weder Zellwand noch eigenen Stoffwechsel und vermehren sich nur, indem sie eine Wirtszelle umprogrammieren, deshalb wirken Antibiotika gegen sie nicht, auch bei starken Symptomen. Unnötiger Einsatz begünstigt zudem resistente Bakterien. Die klärende Frage lautet also nicht „Infektion ja oder nein?“, sondern „Welcher Erreger?“. Ein Zirkelschluss liegt nicht vor, denn „Antibiotikum“ steckt nicht schon im Begriff „Infektion“. Ein Fehlschluss von Korrelation auf Ursache wäre es, wenn sie Fieber und Erkältung ursächlich verknüpfte, sie wendet aber eine Regel auf eine Diagnose an. Eine Verfügbarkeitsverzerrung würde auffällige Einzelfälle voraussetzen, von denen keine Rede ist.","coreRule":"⚡ Erst fragen, welcher Erreger: Bakterium (eigenständiger Zwerg) oder Virus (Gen-Pirat, der eine Zelle kapern muss). Davon hängt die Behandlung ab.","beleg":"Werkstück C.4.2 (Kernidee; Kontext & Tiefe, „Bakterien“ und „Viren“; Anwendung & Relevanz, Antibiotika-Krise)","status":"entwurf","scenario":"","kurz":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher. Antibiotika wirken gegen Bakterien, nicht gegen Viren; der Fehler liegt darin, aus „Infektion“ allein auf ein Antibiotikum zu schließen.","prueffrage":"Wie verlaufen fiebrige Erkältungen gewöhnlich, und in welchen Fällen verschreiben Ärzte dabei überhaupt ein Antibiotikum?","rueckmeldung":[{"option":0,"text":"Ein Zirkelschluss klingt plausibel, weil die Folgerung so mühelos aus dem Wort „Infektion“ zu kommen scheint. Ein Antibiotikum ist aber nicht schon im Begriff „Infektion“ enthalten; die Freundin übergeht vielmehr die Frage, welcher Erreger beteiligt ist."},{"option":2,"text":"Fieber und Erkältung treten tatsächlich zusammen auf. Die Freundin leitet daraus aber keine Ursache ab, sondern wendet eine Regel auf eine Diagnose an. Das Problem liegt darin, dass diese Regel den Erreger außer Acht lässt."},{"option":3,"text":"Dass Einzelfälle das Urteil verzerren, kommt bei Medikamenten oft vor. Im Fall der Freundin ist aber von keinen Bekannten oder früheren Erfahrungen die Rede, die ihren Schluss stützen würden. Er beruht vielmehr auf einer Regel, die den Erreger übergeht."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Antibiotics","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/antibiotics/overview-of-antibiotics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2663782add1167d5"}},{"id":"qx-c1-058","clusterId":"C","werkstueckRef":"C.4.2","stufe":2,"question":"Eine Bekannte lehnt eine Impfung ab: „Da spritzen die mir ja die Krankheit direkt in den Körper.“ Welche Erwiderung trifft den Kern?","options":["Die Krankheit selbst ist für Ungeimpfte oft viel gefährlicher als die Spritze. Wer sich impfen lässt, geht daher das deutlich kleinere Risiko ein.","Impfstoffe enthalten oft nur ungefährliche Bestandteile oder abgeschwächte bzw. abgetötete Erreger. Das Immunsystem lernt daran, den Erreger zu erkennen.","Mit der Spritze schützt sie auch Menschen, die sich nicht impfen lassen können, weil sich die Krankheit weniger ausbreitet. Das nennt man Herdenimmunität.","Bei manchen Krankheiten hält der Schutz der Spritze nicht ein Leben lang, sodass Auffrischungen nötig sind. Die Krankheit bleibt also nicht dauerhaft fern."],"correctIndex":1,"explanation":"Die Sorge verwechselt den vollständigen, aktiven Erreger mit dem, was tatsächlich gespritzt wird. Impfstoffe enthalten oft nur harmlose Bestandteile des Erregers, etwa ein Oberflächenprotein oder ein unschädlich gemachtes Bakteriengift, oder abgeschwächte bzw. abgetötete Erreger, die in aller Regel keine Krankheit auslösen. Daran lernt das Immunsystem den Eindringling kennen wie an einem „Fahndungsfoto“ und bildet Antikörper und Gedächtniszellen, sodass es den echten Erreger später rasch erkennt und bekämpft. Dass die Krankheit für Ungeimpfte gefährlicher ist, stimmt und klingt beruhigend, beantwortet aber nicht, was in der Spritze steckt. Der Schutz anderer durch Herdenimmunität ist ein gutes Argument, räumt aber die Sorge nicht aus, man bekomme die Krankheit selbst gespritzt. Dass der Schutz nachlassen kann, betrifft die Dauer der Wirkung, nicht den Inhalt der Spritze.","coreRule":"⚡ Wer eine Aussage über Impfstoffe prüft, fragt zuerst: Was wird tatsächlich gespritzt, der ganze aktive Erreger oder nur ein „Fahndungsfoto“?","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Impfungen“; Anwendung & Relevanz, „In der Impfdebatte“; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Sorge verwechselt den vollen, aktiven Erreger mit dem, was gespritzt wird: Impfstoffe enthalten oft nur harmlose Bestandteile oder abgeschwächte bzw. abgetötete Erreger, an denen das Immunsystem den echten Erreger kennenlernt.","prueffrage":"Erkranken Geimpfte nach der Spritze an der Krankheit, gegen die sie geimpft wurden, und wie oft kommt das vor?","rueckmeldung":[{"option":0,"text":"Dass die Krankheit für Ungeimpfte oft gefährlicher ist, stimmt und klingt beruhigend. Es beantwortet aber nicht, was in der Spritze steckt, und genau das war die Sorge der Bekannten."},{"option":2,"text":"Der Schutz anderer durch Herdenimmunität ist ein gutes Argument für das Impfen. Die Angst, man bekomme die Krankheit selbst gespritzt, räumt es jedoch nicht aus, weil es den Inhalt der Spritze nicht berührt."},{"option":3,"text":"Bei manchen Krankheiten lässt der Schutz tatsächlich nach, und Auffrischungen sind nötig. Das betrifft aber die Dauer der Wirkung, nicht den Inhalt der Spritze, um den es in der Sorge der Bekannten geht."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f9c342407c3b70ed"}},{"id":"qx-c1-059","clusterId":"C","werkstueckRef":"C.4.2","stufe":3,"question":"Welcher Einwand trifft den Kern, warum diese Werbung unglaubwürdig ist?","options":["Viren vermehren sich in lebenden Körperzellen und haben keine Zellwand; ein Mittel muss in der Zelle wirken, ohne sie zu schädigen, daher ist „ganz ohne Nebenwirkungen“ kaum glaubwürdig.","Viren verändern sich so schnell, dass sie gegen jedes Mittel rasch unempfindlich werden; ein Mittel, das „genauso gezielt“ wirkt wie Antibiotika gegen Bakterien, lässt sich deshalb gar nicht herstellen.","Der Pharmakonzern wirbt für sein eigenes Mittel und verdient daran; schon deshalb ist das Versprechen „ganz ohne Nebenwirkungen“ unglaubwürdig, selbst wenn das Mittel gezielt wirken könnte.","Viren sind keine Lebewesen und lassen sich nicht abtöten; ein Mittel, das sie gezielt bekämpft wie Antibiotika die Bakterien, ist schon im Ansatz widersinnig, daher ist die Werbung unglaubwürdig."],"correctIndex":0,"explanation":"Antibiotika sind deshalb so gezielt, weil Bakterien Strukturen haben, die menschliche Zellen nicht besitzen, etwa die Zellwand. Dort kann ein Wirkstoff ansetzen, ohne Körperzellen zu treffen. Viren haben weder Zellwand noch eigenen Stoffwechsel. Sie vermehren sich, indem sie eine lebende Wirtszelle umprogrammieren. Ein antivirales Mittel muss deshalb in die bereits infizierte Zelle gelangen und dort die Vermehrung des Virus stören, ohne die Wirtszelle zu sehr zu schädigen. Das ist deutlich schwieriger als bei Antibiotika; manche antivirale Mittel setzen zwar an virusspezifischen Schritten an, aber das Versprechen, genauso gezielt und völlig ohne Nebenwirkungen zu wirken, ist nicht plausibel. Dass sich Viren rasch verändern, ist richtig, doch auch Bakterien werden gegen Antibiotika unempfindlich; das betrifft die Dauer der Wirkung, nicht die Zielgenauigkeit oder die Nebenwirkungen. Dass ein Konzern an seinem Mittel verdient, mahnt zur Vorsicht, widerlegt das Versprechen aber nicht und erklärt nicht, warum es biologisch unplausibel ist. Dass sich Viren nicht „abtöten“ lassen, ist eine Frage der Wörter: Antivirale Mittel hemmen die Vermehrung, ein gezielter Ansatz ist also grundsätzlich möglich.","coreRule":"⚡ Gegen Bakterien gibt es Angriffsflächen von außen, gegen Viren muss man in die gekaperte Zelle hinein. Bei Heilversprechen prüfst du deshalb zuerst, ob ein plausibler Mechanismus erklärt wird.","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Antivirale Medikamente“; „Wie man sie bekämpft“)","status":"entwurf","scenario":"Ein Pharmakonzern wirbt für ein neues Mittel: „Wirkt gegen Viren genauso gezielt wie gängige Antibiotika gegen Bakterien, und das ganz ohne Nebenwirkungen.“","kurz":"Viren vermehren sich in lebenden Körperzellen, ein Mittel muss dort wirken, ohne die Zelle zu schädigen. Das ist schwerer als bei Bakterien mit ihrer Zellwand, daher ist „genauso gezielt“ und „ganz ohne Nebenwirkungen“ kaum plausibel.","prueffrage":"Haben gängige Antibiotika selbst Nebenwirkungen, und gibt es bereits zugelassene Mittel gegen Viren?","rueckmeldung":[{"option":1,"text":"Dass sich Viren rasch verändern und Resistenzen entstehen, stimmt. Das betrifft aber nur, wie lange ein Mittel wirkt, nicht wie gezielt es ist oder welche Nebenwirkungen es hat. Auch Bakterien werden gegen Antibiotika unempfindlich, und antivirale Mittel gibt es trotzdem."},{"option":2,"text":"Ein Konzern, der sein eigenes Mittel bewirbt, verdient tatsächlich einen kritischen Blick. Wer das Versprechen wegen des Eigeninteresses ablehnt, sagt aber nichts darüber, ob es biologisch stimmen kann. Der Einwand lässt sogar offen, dass das Mittel gezielt wirkt."},{"option":3,"text":"Viren haben keinen eigenen Stoffwechsel, daher passt das Wort „abtöten“ schlecht. Antivirale Mittel hemmen jedoch die Vermehrung, ein gezielter Ansatz ist also grundsätzlich möglich. Schwierig ist er aus anderem Grund, nicht widersinnig."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"84d14e49b7567a6b"}},{"id":"qx-c1-060","clusterId":"C","werkstueckRef":"C.4.2","stufe":4,"question":"Ein Bekannter sagt: „Ich lasse mich nicht mit mRNA impfen. Die verändert doch mein Erbgut.“ Welche Rückfrage prüft diese Befürchtung am besten?","options":["Was genau bringt der Impfstoff in die Körperzellen, und was machen die Zellen anschließend damit?","Wie viele Menschen in seinem Umfeld sind schon geimpft, und ist bei ihnen danach etwas Auffälliges passiert?","Wie gut schützt die Impfung vor schweren Verläufen der Krankheit, und lohnt sie sich für ihn überhaupt?","Gibt es Impfstoffe ohne mRNA, die er stattdessen nehmen könnte, und wie verträglich sind diese?"],"correctIndex":0,"explanation":"Die Sorge hängt an einer Sachfrage: Was bringt der Impfstoff in die Zelle, und was geschieht damit? mRNA ist eine Arbeitsanweisung für die Herstellung eines Proteins. Die Körperzellen bauen daraufhin ein Oberflächenprotein des Virus, das dem Immunsystem als „Fahndungsfoto“ dient. Das vorübergehende Ablesen eines Bauplans ist etwas ganz anderes als ein Eingriff ins Erbgut, und Fachleute sehen übereinstimmend keine Gefahr für das menschliche Erbgut. Wer so nachfragt, prüft die Behauptung an ihrem Mechanismus. Die Erfahrungen aus dem Umfeld klingen nach praktischer Prüfung, doch einzelne Eindrücke zeigen nicht, ob sich das Erbgut verändert. Die Frage nach dem Schutz vor schweren Verläufen ist sinnvoll, betrifft aber den Nutzen und nicht die Befürchtung. Die Suche nach Impfstoffen ohne mRNA klingt nach einer Lösung, umgeht die Sorge aber, statt sie zu prüfen.","coreRule":"⚡ Prüfe eine Befürchtung zuerst am behaupteten Mechanismus: Was passiert in der Zelle tatsächlich? mRNA liefert den Bauplan für ein Protein, nicht für Veränderungen am Erbgut.","beleg":"Werkstück C.4.2 (Anwendung & Relevanz, „In der Impfdebatte“); Fn. gl-c-mrna (Kuhrt/Oude-Aost/Betsch 2021, Fakten-Check Impfen; Verweis auf Band II, Sektion II.3.2)","status":"entwurf","scenario":"Im Gespräch über die Corona-Impfung äußert ein Bekannter seine Sorge, ein mRNA-Impfstoff greife ins Erbgut ein.","kurz":"Die Befürchtung hängt an einer Sachfrage: Was gelangt in die Zelle, und was geschieht damit? mRNA ist nur eine vorübergehend abgelesene Bauanleitung für ein Virusprotein. Wer so fragt, prüft die Behauptung an ihrem Mechanismus.","prueffrage":"Welche Untersuchungen gibt es dazu, ob Geimpfte ein verändertes Erbgut haben, und was zeigen sie?","rueckmeldung":[{"option":1,"text":"Erfahrungen aus dem Umfeld wirken wie eine praktische Prüfung. Eine Veränderung des Erbguts würde man aber im Alltag niemandem ansehen, und ein paar unauffällige Fälle können sie weder belegen noch ausschließen."},{"option":2,"text":"Der Schutz vor schweren Verläufen ist eine berechtigte Frage, betrifft aber den Nutzen der Impfung. Die geäußerte Sorge, ob das Erbgut verändert wird, bleibt dabei ungeprüft."},{"option":3,"text":"Ein Impfstoff ohne mRNA kann eine Lösung für ihn sein. Die Behauptung über das Erbgut wird damit aber umgangen statt geprüft, und sie steht danach unverändert im Raum."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CDC: How COVID-19 vaccines work (Seite zur Funktionsweise der mRNA-Impfstoffe)","oeffentlich":true,"url":"https://www.cdc.gov/covid/vaccines/how-they-work.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kuhrt, Oude-Aost & Betsch 2021, Fakten-Check Impfen, Gräfe und Unzer (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"e43ac943cce4956b"}}]`);export{t as n,n as t};